window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["LAM"]={"book":"LAM","editions":{"hbo-source":[[1,1,"אֵיכָ֣ה ׀ יָשְׁבָ֣ה בָדָ֗ד הָ⁠עִיר֙ רַבָּ֣תִי עָ֔ם הָיְתָ֖ה כְּ⁠אַלְמָנָ֑ה רַּבָּ֣תִי בַ⁠גּוֹיִ֗ם שָׂרָ֨תִי֙ בַּ⁠מְּדִינ֔וֹת הָיְתָ֖ה לָ⁠מַֽס׃ס","ʼéyká֣h ׀ yáşĕ̌bá֣h bádá֗d há⁠ʻiyr֙ rabá֣̇ţiy ʻá֔m háyĕţá֖h kĕ̇⁠ʼalĕmáná֑h rȧbá֣̇ţiy ba⁠ġwòyi֗m şá̂rá֨ţiy֙ bȧ⁠mĕ̇diyn֔wòţ háyĕţá֖h lá⁠maֽs׃s"],[1,2,"בָּכ֨וֹ תִבְכֶּ֜ה בַּ⁠לַּ֗יְלָה וְ⁠דִמְעָתָ⁠הּ֙ עַ֣ל לֶֽחֱיָ֔⁠הּ אֵֽין־לָ֥⁠הּ מְנַחֵ֖ם מִ⁠כָּל־אֹהֲבֶ֑י⁠הָ כָּל־רֵעֶ֨י⁠הָ֙ בָּ֣גְדוּ בָ֔⁠הּ הָ֥יוּ לָ֖⁠הּ לְ⁠אֹיְבִֽים׃ס","bá̇k֨wò ţibĕkė֜h bȧ⁠lȧ֗yĕláh wĕ⁠dimĕʻáţá⁠ḣ֙ ʻa֣l leֽẖèyá֔⁠ḣ ʼéֽyn-lá֥⁠ḣ mĕnaẖé֖m mi⁠ká̇l-ʼòhàbe֑y⁠há ká̇l-réʻe֨y⁠há֙ bá֣̇gĕdẇ bá֔⁠ḣ há֥yẇ lá֖⁠ḣ lĕ⁠ʼòyĕbiֽym׃s"],[1,3,"גָּֽלְתָ֨ה יְהוּדָ֤ה מֵ⁠עֹ֨נִי֙ וּ⁠מֵ⁠רֹ֣ב עֲבֹדָ֔ה הִ֚יא יָשְׁבָ֣ה בַ⁠גּוֹיִ֔ם לֹ֥א מָצְאָ֖ה מָנ֑וֹחַ כָּל־רֹדְפֶ֥י⁠הָ הִשִּׂיג֖וּ⁠הָ בֵּ֥ין הַ⁠מְּצָרִֽים׃ס","gáֽ̇lĕţá֨h yĕhẇdá֤h mé⁠ʻò֨niy֙ ẇ⁠mé⁠rò֣b ʻàbòdá֔h hi֚yʼ yáşĕ̌bá֣h ba⁠ġwòyi֔m lò֥ʼ máẕĕʼá֖h mán֑wòẖa ká̇l-ròdĕpe֥y⁠há hişi̇̂yg֖ẇ⁠há bé֥̇yn ha⁠mĕ̇ẕáriֽym׃s"],[1,4,"דַּרְכֵ֨י צִיּ֜וֹן אֲבֵל֗וֹת מִ⁠בְּלִי֙ בָּאֵ֣י מוֹעֵ֔ד כָּל־שְׁעָרֶ֨י⁠הָ֙ שֽׁוֹמֵמִ֔ין כֹּהֲנֶ֖י⁠הָ נֶאֱנָחִ֑ים בְּתוּלֹתֶ֥י⁠הָ נּוּג֖וֹת וְ⁠הִ֥יא מַר־לָֽ⁠הּ׃ס","dȧrĕké֨y ẕiẏ֜wòn ʼàbél֗wòţ mi⁠bĕ̇liy֙ bá̇ʼé֣y mwòʻé֔d ká̇l-şĕ̌ʻáre֨y⁠há֙ şֽ̌wòmémi֔yn kò̇hàne֖y⁠há neʼènáẖi֑ym bĕ̇ţẇlòţe֥y⁠há ṅẇg֖wòţ wĕ⁠hi֥yʼ mar-láֽ⁠ḣ׃s"],[1,5,"הָי֨וּ צָרֶ֤י⁠הָ לְ⁠רֹאשׁ֙ אֹיְבֶ֣י⁠הָ שָׁל֔וּ כִּֽי־יְהוָ֥ה הוֹגָ֖⁠הּ עַ֣ל רֹב־פְּשָׁעֶ֑י⁠הָ עוֹלָלֶ֛י⁠הָ הָלְכ֥וּ שְׁבִ֖י לִ⁠פְנֵי־צָֽר׃ס","háy֨ẇ ẕáre֤y⁠há lĕ⁠ròʼş̌֙ ʼòyĕbe֣y⁠há şá̌l֔ẇ kiֽ̇y-yĕhwá֥h hwògá֖⁠ḣ ʻa֣l ròb-pĕ̇şá̌ʻe֑y⁠há ʻwòlále֛y⁠há hálĕk֥ẇ şĕ̌bi֖y li⁠pĕnéy-ẕáֽr׃s"],[1,6,"וַ⁠יֵּצֵ֥א מן־בת־צִיּ֖וֹן כָּל־הֲדָרָ֑⁠הּ הָי֣וּ שָׂרֶ֗י⁠הָ כְּ⁠אַיָּלִים֙ לֹא־מָצְא֣וּ מִרְעֶ֔ה וַ⁠יֵּלְכ֥וּ בְ⁠לֹא־כֹ֖חַ לִ⁠פְנֵ֥י רוֹדֵֽף׃ס","wa⁠yé̇ẕé֥ʼ mn-bţ-ẕiẏ֖wòn ká̇l-hàdárá֑⁠ḣ háy֣ẇ şá̂re֗y⁠há kĕ̇⁠ʼayá̇liym֙ lòʼ-máẕĕʼ֣ẇ mirĕʻe֔h wa⁠yé̇lĕk֥ẇ bĕ⁠lòʼ-kò֖ẖa li⁠pĕné֥y rwòdéֽp׃s"],[1,7,"זָֽכְרָ֣ה יְרוּשָׁלִַ֗ם יְמֵ֤י עָנְיָ⁠הּ֙ וּ⁠מְרוּדֶ֔י⁠הָ כֹּ֚ל מַחֲמֻדֶ֔י⁠הָ אֲשֶׁ֥ר הָי֖וּ מִ֣⁠ימֵי קֶ֑דֶם בִּ⁠נְפֹ֧ל עַמָּ֣⁠הּ בְּ⁠יַד־צָ֗ר וְ⁠אֵ֤ין עוֹזֵר֙ לָ֔⁠הּ רָא֣וּ⁠הָ צָרִ֔ים שָׂחֲק֖וּ עַ֥ל מִשְׁבַּתֶּֽ⁠הָ׃ס","záֽkĕrá֣h yĕrẇşá̌lia֗m yĕmé֤y ʻánĕyá⁠ḣ֙ ẇ⁠mĕrẇde֔y⁠há kò֚̇l maẖàmude֔y⁠há ʼàşě֥r háy֖ẇ mi֣⁠yméy qe֑dem bi̇⁠nĕpò֧l ʻamá֣̇⁠ḣ bĕ̇⁠yad-ẕá֗r wĕ⁠ʼé֤yn ʻwòzér֙ lá֔⁠ḣ ráʼ֣ẇ⁠há ẕári֔ym şá̂ẖàq֖ẇ ʻa֥l mişĕ̌bȧţėֽ⁠há׃s"],[1,8,"חֵ֤טְא חָֽטְאָה֙ יְר֣וּשָׁלִַ֔ם עַל־כֵּ֖ן לְ⁠נִידָ֣ה הָיָ֑תָה כָּֽל־מְכַבְּדֶ֤י⁠הָ הִזִּיל֨וּ⁠הָ֙ כִּי־רָא֣וּ עֶרְוָתָ֔⁠הּ גַּם־הִ֥יא נֶאֶנְחָ֖ה וַ⁠תָּ֥שָׁב אָחֽוֹר׃ס","ẖé֤tĕʼ ẖáֽtĕʼáh֙ yĕr֣ẇşá̌lia֔m ʻal-ké֖̇n lĕ⁠niydá֣h háyá֑ţáh káֽ̇l-mĕkabĕ̇de֤y⁠há hizi̇yl֨ẇ⁠há֙ ki̇y-ráʼ֣ẇ ʻerĕwáţá֔⁠ḣ gȧm-hi֥yʼ neʼenĕẖá֖h wa⁠ţá֥̇şá̌b ʼáẖֽwòr׃s"],[1,9,"טֻמְאָתָ֣⁠הּ בְּ⁠שׁוּלֶ֗י⁠הָ לֹ֤א זָֽכְרָה֙ אַחֲרִיתָ֔⁠הּ וַ⁠תֵּ֣רֶד פְּלָאִ֔ים אֵ֥ין מְנַחֵ֖ם לָ֑⁠הּ רְאֵ֤ה יְהוָה֙ אֶת־עָנְיִ֔⁠י כִּ֥י הִגְדִּ֖יל אוֹיֵֽב׃ס","tumĕʼáţá֣⁠ḣ bĕ̇⁠ş̌ẇle֗y⁠há lò֤ʼ záֽkĕráh֙ ʼaẖàriyţá֔⁠ḣ wa⁠ţé֣̇red pĕ̇láʼi֔ym ʼé֥yn mĕnaẖé֖m lá֑⁠ḣ rĕʼé֤h yĕhwáh֙ ʼeţ-ʻánĕyi֔⁠y ki֥̇y higĕdi֖̇yl ʼwòyéֽb׃s"],[1,10,"יָד⁠וֹ֙ פָּ֣רַשׂ צָ֔ר עַ֖ל כָּל־מַחֲמַדֶּ֑י⁠הָ כִּֽי־רָאֲתָ֤ה גוֹיִם֙ בָּ֣אוּ מִקְדָּשָׁ֔⁠הּ אֲשֶׁ֣ר צִוִּ֔יתָה לֹא־יָבֹ֥אוּ בַ⁠קָּהָ֖ל לָֽ⁠ךְ׃ס","yád⁠wò֙ pá֣̇raş̂ ẕá֔r ʻa֖l ká̇l-maẖàmadė֑y⁠há kiֽ̇y-ráʼàţá֤h gwòyim֙ bá֣̇ʼẇ miqĕdá̇şá̌֔⁠ḣ ʼàşě֣r ẕiwi̇֔yţáh lòʼ-yábò֥ʼẇ ba⁠qá̇há֖l láֽ⁠kĕ׃s"],[1,11,"כָּל־עַמָּ֤⁠הּ נֶאֱנָחִים֙ מְבַקְּשִׁ֣ים לֶ֔חֶם נָתְנ֧וּ מחמודי⁠הם בְּ⁠אֹ֖כֶל לְ⁠הָשִׁ֣יב נָ֑פֶשׁ רְאֵ֤ה יְהוָה֙ וְֽ⁠הַבִּ֔יטָ⁠ה כִּ֥י הָיִ֖יתִי זוֹלֵלָֽה׃ס","ká̇l-ʻamá֤̇⁠ḣ neʼènáẖiym֙ mĕbaqĕ̇şǐ֣ym le֔ẖem náţĕn֧ẇ mẖmwdy⁠hm bĕ̇⁠ʼò֖kel lĕ⁠háşǐ֣yb ná֑peş̌ rĕʼé֤h yĕhwáh֙ wĕֽ⁠habi̇֔ytá⁠h ki֥̇y háyi֖yţiy zwòléláֽh׃s"],[1,12,"ל֣וֹא אֲלֵי⁠כֶם֮ כָּל־עֹ֣בְרֵי דֶרֶךְ֒ הַבִּ֣יטוּ וּ⁠רְא֗וּ אִם־יֵ֤שׁ מַכְאוֹב֙ כְּ⁠מַכְאֹבִ֔⁠י אֲשֶׁ֥ר עוֹלַ֖ל לִ֑⁠י אֲשֶׁר֙ הוֹגָ֣ה יְהוָ֔ה בְּ⁠י֖וֹם חֲר֥וֹן אַפּֽ⁠וֹ׃ס","l֣wòʼ ʼàléy⁠kem֮ ká̇l-ʻò֣bĕréy derekĕ֒ habi֣̇ytẇ ẇ⁠rĕʼ֗ẇ ʼim-yé֤ş̌ makĕʼwòb֙ kĕ̇⁠makĕʼòbi֔⁠y ʼàşě֥r ʻwòla֖l li֑⁠y ʼàşěr֙ hwògá֣h yĕhwá֔h bĕ̇⁠y֖wòm ẖàr֥wòn ʼaṗֽ⁠wò׃s"],[1,13,"מִ⁠מָּר֛וֹם שָֽׁלַח־אֵ֥שׁ בְּ⁠עַצְמֹתַ֖⁠י וַ⁠יִּרְדֶּ֑⁠נָּה פָּרַ֨שׂ רֶ֤שֶׁת לְ⁠רַגְלַ⁠י֙ הֱשִׁיבַ֣⁠נִי אָח֔וֹר נְתָנַ֨⁠נִי֙ שֹֽׁמֵמָ֔ה כָּל־הַ⁠יּ֖וֹם דָּוָֽה׃ס","mi⁠má̇r֛wòm şáֽ̌laẖ-ʼé֥ş̌ bĕ̇⁠ʻaẕĕmòţa֖⁠y wa⁠yi̇rĕdė֑⁠ná̇h pá̇ra֨ş̂ re֤şěţ lĕ⁠ragĕla⁠y֙ hèşǐyba֣⁠niy ʼáẖ֔wòr nĕţána֨⁠niy֙ şòֽ̌mémá֔h ká̇l-ha⁠ẏ֖wòm dá̇wáֽh׃s"],[1,14,"נִשְׂקַד֩ עֹ֨ל פְּשָׁעַ֜⁠י בְּ⁠יָד֗⁠וֹ יִשְׂתָּֽרְג֛וּ עָל֥וּ עַל־צַוָּארִ֖⁠י הִכְשִׁ֣יל כֹּחִ֑⁠י נְתָנַ֣⁠נִי אֲדֹנָ֔⁠י בִּ⁠ידֵ֖י לֹא־אוּכַ֥ל קֽוּם׃ס","nişĕ̂qad֩ ʻò֨l pĕ̇şá̌ʻa֜⁠y bĕ̇⁠yád֗⁠wò yişĕ̂ţáֽ̇rĕg֛ẇ ʻál֥ẇ ʻal-ẕawá̇ʼri֖⁠y hikĕşǐ֣yl kò̇ẖi֑⁠y nĕţána֣⁠niy ʼàdòná֔⁠y bi̇⁠ydé֖y lòʼ-ʼẇka֥l qֽẇm׃s"],[1,15,"סִלָּ֨ה כָל־אַבִּירַ֤⁠י ׀ אֲדֹנָ⁠י֙ בְּ⁠קִרְבִּ֔⁠י קָרָ֥א עָלַ֛⁠י מוֹעֵ֖ד לִ⁠שְׁבֹּ֣ר בַּחוּרָ֑⁠י גַּ֚ת דָּרַ֣ךְ אֲדֹנָ֔⁠י לִ⁠בְתוּלַ֖ת בַּת־יְהוּדָֽה׃ס","silá̇֨h kál-ʼabi̇yra֤⁠y ׀ ʼàdòná⁠y֙ bĕ̇⁠qirĕbi̇֔⁠y qárá֥ʼ ʻála֛⁠y mwòʻé֖d li⁠şĕ̌bò֣̇r bȧẖẇrá֑⁠y gȧ֚ţ dá̇ra֣kĕ ʼàdòná֔⁠y li⁠bĕţẇla֖ţ bȧţ-yĕhẇdáֽh׃s"],[1,16,"עַל־אֵ֣לֶּה ׀ אֲנִ֣י בוֹכִיָּ֗ה עֵינִ֤⁠י ׀ עֵינִ⁠י֙ יֹ֣רְדָה מַּ֔יִם כִּֽי־רָחַ֥ק מִמֶּ֛⁠נִּי מְנַחֵ֖ם מֵשִׁ֣יב נַפְשִׁ֑⁠י הָי֤וּ בָנַ⁠י֙ שֽׁוֹמֵמִ֔ים כִּ֥י גָבַ֖ר אוֹיֵֽב׃ס","ʻal-ʼé֣lėh ׀ ʼàni֣y bwòkiyá̇֗h ʻéyni֤⁠y ׀ ʻéyni⁠y֙ yò֣rĕdáh mȧ֔yim kiֽ̇y-ráẖa֥q mimė֛⁠ni̇y mĕnaẖé֖m méşǐ֣yb napĕşǐ֑⁠y háy֤ẇ bána⁠y֙ şֽ̌wòmémi֔ym ki֥̇y gába֖r ʼwòyéֽb׃s"],[1,17,"פֵּֽרְשָׂ֨ה צִיּ֜וֹן בְּ⁠יָדֶ֗י⁠הָ אֵ֤ין מְנַחֵם֙ לָ֔⁠הּ צִוָּ֧ה יְהוָ֛ה לְ⁠יַעֲקֹ֖ב סְבִיבָ֣י⁠ו צָרָ֑י⁠ו הָיְתָ֧ה יְרוּשָׁלִַ֛ם לְ⁠נִדָּ֖ה בֵּינֵי⁠הֶֽם׃ס","péֽ̇rĕşá̂֨h ẕiẏ֜wòn bĕ̇⁠yáde֗y⁠há ʼé֤yn mĕnaẖém֙ lá֔⁠ḣ ẕiwá֧̇h yĕhwá֛h lĕ⁠yaʻàqò֖b sĕbiybá֣y⁠w ẕárá֑y⁠w háyĕţá֧h yĕrẇşá̌lia֛m lĕ⁠nidá֖̇h bé̇ynéy⁠heֽm׃s"],[1,18,"צַדִּ֥יק ה֛וּא יְהוָ֖ה כִּ֣י פִ֣י⁠הוּ מָרִ֑יתִי שִׁמְעוּ־נָ֣א כָל־עמים וּ⁠רְאוּ֙ מַכְאֹבִ֔⁠י בְּתוּלֹתַ֥⁠י וּ⁠בַחוּרַ֖⁠י הָלְכ֥וּ בַ⁠שֶּֽׁבִי׃ס","ẕadi֥̇yq h֛ẇʼ yĕhwá֖h ki֣̇y pi֣y⁠hẇ mári֑yţiy şǐmĕʻẇ-ná֣ʼ kál-ʻmym ẇ⁠rĕʼẇ֙ makĕʼòbi֔⁠y bĕ̇ţẇlòţa֥⁠y ẇ⁠baẖẇra֖⁠y hálĕk֥ẇ ba⁠şėֽ̌biy׃s"],[1,19,"קָרָ֤אתִי לַֽ⁠מְאַהֲבַ⁠י֙ הֵ֣מָּה רִמּ֔וּ⁠נִי כֹּהֲנַ֥⁠י וּ⁠זְקֵנַ֖⁠י בָּ⁠עִ֣יר גָּוָ֑עוּ כִּֽי־בִקְשׁ֥וּ אֹ֨כֶל֙ לָ֔⁠מוֹ וְ⁠יָשִׁ֖יבוּ אֶת־נַפְשָֽׁ⁠ם׃ס","qárá֤ʼţiy laֽ⁠mĕʼahàba⁠y֙ hé֣má̇h riṁ֔ẇ⁠niy kò̇hàna֥⁠y ẇ⁠zĕqéna֖⁠y bá̇⁠ʻi֣yr gá̇wá֑ʻẇ kiֽ̇y-biqĕş֥̌ẇ ʼò֨kel֙ lá֔⁠mwò wĕ⁠yáşǐ֖ybẇ ʼeţ-napĕşáֽ̌⁠m׃s"],[1,20,"רְאֵ֨ה יְהוָ֤ה כִּֽי־צַר־לִ⁠י֙ מֵעַ֣⁠י חֳמַרְמָ֔רוּ נֶהְפַּ֤ךְ לִבִּ⁠י֙ בְּ⁠קִרְבִּ֔⁠י כִּ֥י מָר֖וֹ מָרִ֑יתִי מִ⁠ח֥וּץ שִׁכְּלָה־חֶ֖רֶב בַּ⁠בַּ֥יִת כַּ⁠מָּֽוֶת׃ס","rĕʼé֨h yĕhwá֤h kiֽ̇y-ẕar-li⁠y֙ méʻa֣⁠y ẖomarĕmá֔rẇ nehĕpȧ֤kĕ libi̇⁠y֙ bĕ̇⁠qirĕbi̇֔⁠y ki֥̇y már֖wò mári֑yţiy mi⁠ẖ֥ẇẕ şǐkĕ̇láh-ẖe֖reb bȧ⁠bȧ֥yiţ kȧ⁠máֽ̇weţ׃s"],[1,21,"שָׁמְע֞וּ כִּ֧י נֶאֱנָחָ֣ה אָ֗נִי אֵ֤ין מְנַחֵם֙ לִ֔⁠י כָּל־אֹ֨יְבַ֜⁠י שָׁמְע֤וּ רָֽעָתִ⁠י֙ שָׂ֔שׂוּ כִּ֥י אַתָּ֖ה עָשִׂ֑יתָ הֵבֵ֥אתָ יוֹם־קָרָ֖אתָ וְ⁠יִֽהְי֥וּ כָמֽוֹ⁠נִי׃ס","şá̌mĕʻ֞ẇ ki֧̇y neʼènáẖá֣h ʼá֗niy ʼé֤yn mĕnaẖém֙ li֔⁠y ká̇l-ʼò֨yĕba֜⁠y şá̌mĕʻ֤ẇ ráֽʻáţi⁠y֙ şá̂֔ş̂ẇ ki֥̇y ʼaţá֖̇h ʻáşî֑yţá hébé֥ʼţá ywòm-qárá֖ʼţá wĕ⁠yiֽhĕy֥ẇ kámֽwò⁠niy׃s"],[1,22,"תָּבֹ֨א כָל־רָעָתָ֤⁠ם לְ⁠פָנֶ֨י⁠ךָ֙ וְ⁠עוֹלֵ֣ל לָ֔⁠מוֹ כַּ⁠אֲשֶׁ֥ר עוֹלַ֛לְתָּ לִ֖⁠י עַ֣ל כָּל־פְּשָׁעָ֑⁠י כִּֽי־רַבּ֥וֹת אַנְחֹתַ֖⁠י וְ⁠לִבִּ֥⁠י דַוָּֽי׃פ","ţá̇bò֨ʼ kál-ráʻáţá֤⁠m lĕ⁠páne֨y⁠ká֙ wĕ⁠ʻwòlé֣l lá֔⁠mwò kȧ⁠ʼàşě֥r ʻwòla֛lĕţá̇ li֖⁠y ʻa֣l ká̇l-pĕ̇şá̌ʻá֑⁠y kiֽ̇y-raḃ֥wòţ ʼanĕẖòţa֖⁠y wĕ⁠libi֥̇⁠y dawáֽ̇y׃p"],[2,1,"אֵיכָה֩ יָעִ֨יב בְּ⁠אַפּ֤⁠וֹ ׀ אֲדֹנָ⁠י֙ אֶת־בַּת־צִיּ֔וֹן הִשְׁלִ֤יךְ מִ⁠שָּׁמַ֨יִם֙ אֶ֔רֶץ תִּפְאֶ֖רֶת יִשְׂרָאֵ֑ל וְ⁠לֹא־זָכַ֥ר הֲדֹם־רַגְלָ֖י⁠ו בְּ⁠י֥וֹם אַפּֽ⁠וֹ׃ס","ʼéykáh֩ yáʻi֨yb bĕ̇⁠ʼaṗ֤⁠wò ׀ ʼàdòná⁠y֙ ʼeţ-bȧţ-ẕiẏ֔wòn hişĕ̌li֤ykĕ mi⁠şá̇̌ma֨yim֙ ʼe֔reẕ ţi̇pĕʼe֖reţ yişĕ̂ráʼé֑l wĕ⁠lòʼ-záka֥r hàdòm-ragĕlá֖y⁠w bĕ̇⁠y֥wòm ʼaṗֽ⁠wò׃s"],[2,2,"בִּלַּ֨ע אֲדֹנָ֜⁠י לא חָמַ֗ל אֵ֚ת כָּל־נְא֣וֹת יַעֲקֹ֔ב הָרַ֧ס בְּ⁠עֶבְרָת֛⁠וֹ מִבְצְרֵ֥י בַת־יְהוּדָ֖ה הִגִּ֣יעַ לָ⁠אָ֑רֶץ חִלֵּ֥ל מַמְלָכָ֖ה וְ⁠שָׂרֶֽי⁠הָ׃ס","bi̇lȧ֨ʻ ʼàdòná֜⁠y lʼ ẖáma֗l ʼé֚ţ ká̇l-nĕʼ֣wòţ yaʻàqò֔b hára֧s bĕ̇⁠ʻebĕráţ֛⁠wò mibĕẕĕré֥y baţ-yĕhẇdá֖h higi֣̇yʻa lá⁠ʼá֑reẕ ẖilé֥̇l mamĕláká֖h wĕ⁠şá̂reֽy⁠há׃s"],[2,3,"גָּדַ֣ע בָּֽ⁠חֳרִי אַ֗ף כֹּ֚ל קֶ֣רֶן יִשְׂרָאֵ֔ל הֵשִׁ֥יב אָח֛וֹר יְמִינ֖⁠וֹ מִ⁠פְּנֵ֣י אוֹיֵ֑ב וַ⁠יִּבְעַ֤ר בְּ⁠יַעֲקֹב֙ כְּ⁠אֵ֣שׁ לֶֽהָבָ֔ה אָכְלָ֖ה סָבִֽיב׃ס","gá̇da֣ʻ báֽ̇⁠ẖoriy ʼa֗p kò֚̇l qe֣ren yişĕ̂ráʼé֔l héşǐ֥yb ʼáẖ֛wòr yĕmiyn֖⁠wò mi⁠pĕ̇né֣y ʼwòyé֑b wa⁠yi̇bĕʻa֤r bĕ̇⁠yaʻàqòb֙ kĕ̇⁠ʼé֣ş̌ leֽhábá֔h ʼákĕlá֖h sábiֽyb׃s"],[2,4,"דָּרַ֨ךְ קַשְׁתּ֜⁠וֹ כְּ⁠אוֹיֵ֗ב נִצָּ֤ב יְמִינ⁠וֹ֙ כְּ⁠צָ֔ר וַֽ⁠יַּהֲרֹ֔ג כֹּ֖ל מַחֲמַדֵּי־עָ֑יִן בְּ⁠אֹ֨הֶל֙ בַּת־צִיּ֔וֹן שָׁפַ֥ךְ כָּ⁠אֵ֖שׁ חֲמָתֽ⁠וֹ׃ס","dá̇ra֨kĕ qaşĕ̌ţ̇֜⁠wò kĕ̇⁠ʼwòyé֗b niẕá֤̇b yĕmiyn⁠wò֙ kĕ̇⁠ẕá֔r waֽ⁠yȧhàrò֔g kò֖̇l maẖàmadé̇y-ʻá֑yin bĕ̇⁠ʼò֨hel֙ bȧţ-ẕiẏ֔wòn şá̌pa֥kĕ ká̇⁠ʼé֖ş̌ ẖàmáţֽ⁠wò׃s"],[2,5,"הָיָ֨ה אֲדֹנָ֤⁠י ׀ כְּ⁠אוֹיֵב֙ בִּלַּ֣ע יִשְׂרָאֵ֔ל בִּלַּע֙ כָּל־אַרְמְנוֹתֶ֔י⁠הָ שִׁחֵ֖ת מִבְצָרָ֑י⁠ו וַ⁠יֶּ֨רֶב֙ בְּ⁠בַת־יְהוּדָ֔ה תַּאֲנִיָּ֖ה וַ⁠אֲנִיָּֽה׃ס","háyá֨h ʼàdòná֤⁠y ׀ kĕ̇⁠ʼwòyéb֙ bi̇lȧ֣ʻ yişĕ̂ráʼé֔l bi̇lȧʻ֙ ká̇l-ʼarĕmĕnwòţe֔y⁠há şǐẖé֖ţ mibĕẕárá֑y⁠w wa⁠yė֨reb֙ bĕ̇⁠baţ-yĕhẇdá֔h ţȧʼàniyá֖̇h wa⁠ʼàniyáֽ̇h׃s"],[2,6,"וַ⁠יַּחְמֹ֤ס כַּ⁠גַּן֙ שֻׂכּ֔⁠וֹ שִׁחֵ֖ת מוֹעֲד֑⁠וֹ שִׁכַּ֨ח יְהוָ֤ה ׀ בְּ⁠צִיּוֹן֙ מוֹעֵ֣ד וְ⁠שַׁבָּ֔ת וַ⁠יִּנְאַ֥ץ בְּ⁠זַֽעַם־אַפּ֖⁠וֹ מֶ֥לֶךְ וְ⁠כֹהֵֽן׃ס","wa⁠yȧẖĕmò֤s kȧ⁠gȧn֙ şûk̇֔⁠wò şǐẖé֖ţ mwòʻàd֑⁠wò şǐkȧ֨ẖ yĕhwá֤h ׀ bĕ̇⁠ẕiẏwòn֙ mwòʻé֣d wĕ⁠şǎbá̇֔ţ wa⁠yi̇nĕʼa֥ẕ bĕ̇⁠zaֽʻam-ʼaṗ֖⁠wò me֥lekĕ wĕ⁠kòhéֽn׃s"],[2,7,"זָנַ֨ח אֲדֹנָ֤⁠י ׀ מִזְבְּח⁠וֹ֙ נִאֵ֣ר מִקְדָּשׁ֔⁠וֹ הִסְגִּיר֙ בְּ⁠יַד־אוֹיֵ֔ב חוֹמֹ֖ת אַרְמְנוֹתֶ֑י⁠הָ ק֛וֹל נָתְנ֥וּ בְּ⁠בֵית־יְהוָ֖ה כְּ⁠י֥וֹם מוֹעֵֽד׃ס","zána֨ẖ ʼàdòná֤⁠y ׀ mizĕbĕ̇ẖ⁠wò֙ niʼé֣r miqĕdá̇ş̌֔⁠wò hisĕgi̇yr֙ bĕ̇⁠yad-ʼwòyé֔b ẖwòmò֖ţ ʼarĕmĕnwòţe֑y⁠há q֛wòl náţĕn֥ẇ bĕ̇⁠béyţ-yĕhwá֖h kĕ̇⁠y֥wòm mwòʻéֽd׃s"],[2,8,"חָשַׁ֨ב יְהוָ֤ה ׀ לְ⁠הַשְׁחִית֙ חוֹמַ֣ת בַּת־צִיּ֔וֹן נָ֣טָה קָ֔ו לֹא־הֵשִׁ֥יב יָד֖⁠וֹ מִ⁠בַּלֵּ֑עַ וַ⁠יַּֽאֲבֶל־חֵ֥ל וְ⁠חוֹמָ֖ה יַחְדָּ֥ו אֻמְלָֽלוּ׃ס","ẖáşǎ֨b yĕhwá֤h ׀ lĕ⁠haşĕ̌ẖiyţ֙ ẖwòma֣ţ bȧţ-ẕiẏ֔wòn ná֣táh qá֔w lòʼ-héşǐ֥yb yád֖⁠wò mi⁠bȧlé֑̇ʻa wa⁠yȧֽʼàbel-ẖé֥l wĕ⁠ẖwòmá֖h yaẖĕdá֥̇w ʼumĕláֽlẇ׃s"],[2,9,"טָבְע֤וּ בָ⁠אָ֨רֶץ֙ שְׁעָרֶ֔י⁠הָ אִבַּ֥ד וְ⁠שִׁבַּ֖ר בְּרִיחֶ֑י⁠הָ מַלְכָּ֨⁠הּ וְ⁠שָׂרֶ֤י⁠הָ בַ⁠גּוֹיִם֙ אֵ֣ין תּוֹרָ֔ה גַּם־נְבִיאֶ֕י⁠הָ לֹא־מָצְא֥וּ חָז֖וֹן מֵ⁠יְהוָֽה׃ס","tábĕʻ֤ẇ bá⁠ʼá֨reẕ֙ şĕ̌ʻáre֔y⁠há ʼibȧ֥d wĕ⁠şǐbȧ֖r bĕ̇riyẖe֑y⁠há malĕká̇֨⁠ḣ wĕ⁠şá̂re֤y⁠há ba⁠ġwòyim֙ ʼé֣yn ţ̇wòrá֔h gȧm-nĕbiyʼe֕y⁠há lòʼ-máẕĕʼ֥ẇ ẖáz֖wòn mé⁠yĕhwáֽh׃s"],[2,10,"יֵשְׁב֨וּ לָ⁠אָ֤רֶץ יִדְּמוּ֙ זִקְנֵ֣י בַת־צִיּ֔וֹן הֶֽעֱל֤וּ עָפָר֙ עַל־רֹאשָׁ֔⁠ם חָגְר֖וּ שַׂקִּ֑ים הוֹרִ֤ידוּ לָ⁠אָ֨רֶץ֙ רֹאשָׁ֔⁠ן בְּתוּלֹ֖ת יְרוּשָׁלִָֽם׃ס","yéşĕ̌b֨ẇ lá⁠ʼá֤reẕ yidĕ̇mẇ֙ ziqĕné֣y baţ-ẕiẏ֔wòn heֽʻèl֤ẇ ʻápár֙ ʻal-ròʼşá̌֔⁠m ẖágĕr֖ẇ şâqi֑̇ym hwòri֤ydẇ lá⁠ʼá֨reẕ֙ ròʼşá̌֔⁠n bĕ̇ţẇlò֖ţ yĕrẇşá̌liáֽm׃s"],[2,11,"כָּל֨וּ בַ⁠דְּמָע֤וֹת עֵינַ⁠י֙ חֳמַרְמְר֣וּ מֵעַ֔⁠י נִשְׁפַּ֤ךְ לָ⁠אָ֨רֶץ֙ כְּבֵדִ֔⁠י עַל־שֶׁ֖בֶר בַּת־עַמִּ֑⁠י בֵּֽ⁠עָטֵ֤ף עוֹלֵל֙ וְ⁠יוֹנֵ֔ק בִּ⁠רְחֹב֖וֹת קִרְיָֽה׃ס","ká̇l֨ẇ ba⁠dĕ̇máʻ֤wòţ ʻéyna⁠y֙ ẖomarĕmĕr֣ẇ méʻa֔⁠y nişĕ̌pȧ֤kĕ lá⁠ʼá֨reẕ֙ kĕ̇bédi֔⁠y ʻal-şě֖ber bȧţ-ʻami֑̇⁠y béֽ̇⁠ʻáté֤p ʻwòlél֙ wĕ⁠ywòné֔q bi̇⁠rĕẖòb֖wòţ qirĕyáֽh׃s"],[2,12,"לְ⁠אִמֹּתָ⁠ם֙ יֹֽאמְר֔וּ אַיֵּ֖ה דָּגָ֣ן וָ⁠יָ֑יִן בְּ⁠הִֽתְעַטְּפָ֤⁠ם כֶּֽ⁠חָלָל֙ בִּ⁠רְחֹב֣וֹת עִ֔יר בְּ⁠הִשְׁתַּפֵּ֣ךְ נַפְשָׁ֔⁠ם אֶל־חֵ֖יק אִמֹּתָֽ⁠ם׃ס","lĕ⁠ʼimò̇ţá⁠m֙ yòֽʼmĕr֔ẇ ʼayé֖̇h dá̇gá֣n wá⁠yá֑yin bĕ̇⁠hiֽţĕʻatĕ̇pá֤⁠m kėֽ⁠ẖálál֙ bi̇⁠rĕẖòb֣wòţ ʻi֔yr bĕ̇⁠hişĕ̌ţȧpé֣̇kĕ napĕşá̌֔⁠m ʼel-ẖé֖yq ʼimò̇ţáֽ⁠m׃s"],[2,13,"מָֽה־אֲעִידֵ֞⁠ךְ מָ֣ה אֲדַמֶּה־לָּ֗⁠ךְ הַ⁠בַּת֙ יְר֣וּשָׁלִַ֔ם מָ֤ה אַשְׁוֶה־לָּ⁠ךְ֙ וַ⁠אֲנַֽחֲמֵ֔⁠ךְ בְּתוּלַ֖ת בַּת־צִיּ֑וֹן כִּֽי־גָד֥וֹל כַּ⁠יָּ֛ם שִׁבְרֵ֖⁠ךְ מִ֥י יִרְפָּא־לָֽ⁠ךְ׃ס","máֽh-ʼàʻiydé֞⁠kĕ má֣h ʼàdamėh-lá̇֗⁠kĕ ha⁠bȧţ֙ yĕr֣ẇşá̌lia֔m má֤h ʼaşĕ̌weh-lá̇⁠kĕ֙ wa⁠ʼànaֽẖàmé֔⁠kĕ bĕ̇ţẇla֖ţ bȧţ-ẕiẏ֑wòn kiֽ̇y-gád֥wòl kȧ⁠yá֛̇m şǐbĕré֖⁠kĕ mi֥y yirĕpá̇ʼ-láֽ⁠kĕ׃s"],[2,14,"נְבִיאַ֗יִ⁠ךְ חָ֤זוּ לָ⁠ךְ֙ שָׁ֣וְא וְ⁠תָפֵ֔ל וְ⁠לֹֽא־גִלּ֥וּ עַל־עֲוֺנֵ֖⁠ךְ לְ⁠הָשִׁ֣יב שבית⁠ך וַ⁠יֶּ֣חֱזוּ לָ֔⁠ךְ מַשְׂא֥וֹת שָׁ֖וְא וּ⁠מַדּוּחִֽים׃ס","nĕbiyʼa֗yi⁠kĕ ẖá֤zẇ lá⁠kĕ֙ şá֣̌wĕʼ wĕ⁠ţápé֔l wĕ⁠lòֽʼ-gil֥̇ẇ ʻal-ʻàwֺné֖⁠kĕ lĕ⁠háşǐ֣yb şbyţ⁠k wa⁠yė֣ẖèzẇ lá֔⁠kĕ maşĕ̂ʼ֥wòţ şá֖̌wĕʼ ẇ⁠maḋẇẖiֽym׃s"],[2,15,"סָֽפְק֨וּ עָלַ֤יִ⁠ךְ כַּפַּ֨יִם֙ כָּל־עֹ֣בְרֵי דֶ֔רֶךְ שָֽׁרְקוּ֙ וַ⁠יָּנִ֣עוּ רֹאשָׁ֔⁠ם עַל־בַּ֖ת יְרוּשָׁלִָ֑ם הֲ⁠זֹ֣את הָ⁠עִ֗יר שֶׁ⁠יֹּֽאמְרוּ֙ כְּלִ֣ילַת יֹ֔פִי מָשׂ֖וֹשׂ לְ⁠כָל־הָ⁠אָֽרֶץ׃ס","sáֽpĕq֨ẇ ʻála֤yi⁠kĕ kȧpȧ֨yim֙ ká̇l-ʻò֣bĕréy de֔rekĕ şáֽ̌rĕqẇ֙ wa⁠yá̇ni֣ʻẇ ròʼşá̌֔⁠m ʻal-bȧ֖ţ yĕrẇşá̌liá֑m hà⁠zò֣ʼţ há⁠ʻi֗yr şě⁠yòֽ̇ʼmĕrẇ֙ kĕ̇li֣ylaţ yò֔piy máş֖̂wòş̂ lĕ⁠kál-há⁠ʼáֽreẕ׃s"],[2,16,"פָּצ֨וּ עָלַ֤יִ⁠ךְ פִּי⁠הֶם֙ כָּל־א֣וֹיְבַ֔יִ⁠ךְ שָֽׁרְקוּ֙ וַ⁠יַּֽחַרְקוּ־שֵׁ֔ן אָמְר֖וּ בִּלָּ֑עְנוּ אַ֣ךְ זֶ֥ה הַ⁠יּ֛וֹם שֶׁ⁠קִּוִּינֻ֖⁠הוּ מָצָ֥אנוּ רָאִֽינוּ׃ס","pá̇ẕ֨ẇ ʻála֤yi⁠kĕ pi̇y⁠hem֙ ká̇l-ʼ֣wòyĕba֔yi⁠kĕ şáֽ̌rĕqẇ֙ wa⁠yȧֽẖarĕqẇ-şé̌֔n ʼámĕr֖ẇ bi̇lá֑̇ʻĕnẇ ʼa֣kĕ ze֥h ha⁠ẏ֛wòm şě⁠qi̇wi̇ynu֖⁠hẇ máẕá֥ʼnẇ ráʼiֽynẇ׃s"],[2,17,"עָשָׂ֨ה יְהוָ֜ה אֲשֶׁ֣ר זָמָ֗ם בִּצַּ֤ע אֶמְרָת⁠וֹ֙ אֲשֶׁ֣ר צִוָּ֣ה מִֽ⁠ימֵי־קֶ֔דֶם הָרַ֖ס וְ⁠לֹ֣א חָמָ֑ל וַ⁠יְשַׂמַּ֤ח עָלַ֨יִ⁠ךְ֙ אוֹיֵ֔ב הֵרִ֖ים קֶ֥רֶן צָרָֽיִ⁠ךְ׃ס","ʻáşá̂֨h yĕhwá֜h ʼàşě֣r zámá֗m bi̇ẕȧ֤ʻ ʼemĕráţ⁠wò֙ ʼàşě֣r ẕiwá֣̇h miֽ⁠yméy-qe֔dem hára֖s wĕ⁠lò֣ʼ ẖámá֑l wa⁠yĕşâmȧ֤ẖ ʻála֨yi⁠kĕ֙ ʼwòyé֔b héri֖ym qe֥ren ẕáráֽyi⁠kĕ׃s"],[2,18,"צָעַ֥ק לִבָּ֖⁠ם אֶל־אֲדֹנָ֑⁠י חוֹמַ֣ת בַּת־צִ֠יּוֹן הוֹרִ֨ידִי כַ⁠נַּ֤חַל דִּמְעָה֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה אַֽל־תִּתְּנִ֤י פוּגַת֙ לָ֔⁠ךְ אַל־תִּדֹּ֖ם בַּת־עֵינֵֽ⁠ךְ׃ס","ẕáʻa֥q libá֖̇⁠m ʼel-ʼàdòná֑⁠y ẖwòma֣ţ bȧţ-ẕi֠ẏwòn hwòri֨ydiy ka⁠nȧ֤ẖal di̇mĕʻáh֙ ywòmá֣m wá⁠la֔yĕláh ʼaֽl-ţi̇ţĕ̇ni֤y pẇgaţ֙ lá֔⁠kĕ ʼal-ţi̇dò֖̇m bȧţ-ʻéynéֽ⁠kĕ׃s"],[2,19,"ק֣וּמִי ׀ רֹ֣נִּי ב⁠ליל לְ⁠רֹאשׁ֙ אַשְׁמֻר֔וֹת שִׁפְכִ֤י כַ⁠מַּ֨יִם֙ לִבֵּ֔⁠ךְ נֹ֖כַח פְּנֵ֣י אֲדֹנָ֑⁠י שְׂאִ֧י אֵלָ֣י⁠ו כַּפַּ֗יִ⁠ךְ עַל־נֶ֨פֶשׁ֙ עֽוֹלָלַ֔יִ⁠ךְ הָ⁠עֲטוּפִ֥ים בְּ⁠רָעָ֖ב בְּ⁠רֹ֥אשׁ כָּל־חוּצֽוֹת׃ס","q֣ẇmiy ׀ rò֣ni̇y b⁠lyl lĕ⁠ròʼş̌֙ ʼaşĕ̌mur֔wòţ şǐpĕki֤y ka⁠mȧ֨yim֙ libé̇֔⁠kĕ nò֖kaẖ pĕ̇né֣y ʼàdòná֑⁠y şĕ̂ʼi֧y ʼélá֣y⁠w kȧpȧ֗yi⁠kĕ ʻal-ne֨peş̌֙ ʻֽwòlála֔yi⁠kĕ há⁠ʻàtẇpi֥ym bĕ̇⁠ráʻá֖b bĕ̇⁠rò֥ʼş̌ ká̇l-ẖẇẕֽwòţ׃s"],[2,20,"רְאֵ֤ה יְהוָה֙ וְֽ⁠הַבִּ֔יטָ⁠ה לְ⁠מִ֖י עוֹלַ֣לְתָּ כֹּ֑ה אִם־תֹּאכַ֨לְנָה נָשִׁ֤ים פִּרְיָ⁠ם֙ עֹלֲלֵ֣י טִפֻּחִ֔ים אִם־יֵהָרֵ֛ג בְּ⁠מִקְדַּ֥שׁ אֲדֹנָ֖⁠י כֹּהֵ֥ן וְ⁠נָבִֽיא׃ס","rĕʼé֤h yĕhwáh֙ wĕֽ⁠habi̇֔ytá⁠h lĕ⁠mi֖y ʻwòla֣lĕţá̇ kò֑̇h ʼim-ţò̇ʼka֨lĕnáh náşǐ֤ym pi̇rĕyá⁠m֙ ʻòlàlé֣y tipu̇ẖi֔ym ʼim-yéháré֛g bĕ̇⁠miqĕdȧ֥ş̌ ʼàdòná֖⁠y kò̇hé֥n wĕ⁠nábiֽyʼ׃s"],[2,21,"שָׁכְב֨וּ לָ⁠אָ֤רֶץ חוּצוֹת֙ נַ֣עַר וְ⁠זָקֵ֔ן בְּתוּלֹתַ֥⁠י וּ⁠בַחוּרַ֖⁠י נָפְל֣וּ בֶ⁠חָ֑רֶב הָרַ֨גְתָּ֙ בְּ⁠י֣וֹם אַפֶּ֔⁠ךָ טָבַ֖חְתָּ לֹ֥א חָמָֽלְתָּ׃ס","şá̌kĕb֨ẇ lá⁠ʼá֤reẕ ẖẇẕwòţ֙ na֣ʻar wĕ⁠záqé֔n bĕ̇ţẇlòţa֥⁠y ẇ⁠baẖẇra֖⁠y nápĕl֣ẇ be⁠ẖá֑reb hára֨gĕţá̇֙ bĕ̇⁠y֣wòm ʼapė֔⁠ká tába֖ẖĕţá̇ lò֥ʼ ẖámáֽlĕţá̇׃s"],[2,22,"תִּקְרָא֩ כְ⁠י֨וֹם מוֹעֵ֤ד מְגוּרַ⁠י֙ מִ⁠סָּבִ֔יב וְ⁠לֹ֥א הָיָ֛ה בְּ⁠י֥וֹם אַף־יְהוָ֖ה פָּלִ֣יט וְ⁠שָׂרִ֑יד אֲשֶׁר־טִפַּ֥חְתִּי וְ⁠רִבִּ֖יתִי אֹיְבִ֥⁠י כִלָּֽ⁠ם׃פ","ţi̇qĕráʼ֩ kĕ⁠y֨wòm mwòʻé֤d mĕgẇra⁠y֙ mi⁠sá̇bi֔yb wĕ⁠lò֥ʼ háyá֛h bĕ̇⁠y֥wòm ʼap-yĕhwá֖h pá̇li֣yt wĕ⁠şá̂ri֑yd ʼàşěr-tipȧ֥ẖĕţi̇y wĕ⁠ribi֖̇yţiy ʼòyĕbi֥⁠y kiláֽ̇⁠m׃p"],[3,1,"אֲנִ֤י הַ⁠גֶּ֨בֶר֙ רָאָ֣ה עֳנִ֔י בְּ⁠שֵׁ֖בֶט עֶבְרָתֽ⁠וֹ׃","ʼàni֤y ha⁠gė֨ber֙ ráʼá֣h ʻoni֔y bĕ̇⁠şé֖̌bet ʻebĕráţֽ⁠wò׃"],[3,2,"אוֹתִ֥⁠י נָהַ֛ג וַ⁠יֹּלַ֖ךְ חֹ֥שֶׁךְ וְ⁠לֹא־אֽוֹר׃","ʼwòţi֥⁠y náha֛g wa⁠yò̇la֖kĕ ẖò֥şěkĕ wĕ⁠lòʼ-ʼֽwòr׃"],[3,3,"אַ֣ךְ בִּ֥⁠י יָשֻׁ֛ב יַהֲפֹ֥ךְ יָד֖⁠וֹ כָּל־הַ⁠יּֽוֹם׃ס","ʼa֣kĕ bi֥̇⁠y yáşǔ֛b yahàpò֥kĕ yád֖⁠wò ká̇l-ha⁠ẏֽwòm׃s"],[3,4,"בִּלָּ֤ה בְשָׂרִ⁠י֙ וְ⁠עוֹרִ֔⁠י שִׁבַּ֖ר עַצְמוֹתָֽ⁠י׃","bi̇lá֤̇h bĕşá̂ri⁠y֙ wĕ⁠ʻwòri֔⁠y şǐbȧ֖r ʻaẕĕmwòţáֽ⁠y׃"],[3,5,"בָּנָ֥ה עָלַ֛⁠י וַ⁠יַּקַּ֖ף רֹ֥אשׁ וּ⁠תְלָאָֽה׃","bá̇ná֥h ʻála֛⁠y wa⁠yȧqȧ֖p rò֥ʼş̌ ẇ⁠ţĕláʼáֽh׃"],[3,6,"בְּ⁠מַחֲשַׁכִּ֥ים הוֹשִׁיבַ֖⁠נִי כְּ⁠מֵתֵ֥י עוֹלָֽם׃ס","bĕ̇⁠maẖàşǎki֥̇ym hwòşǐyba֖⁠niy kĕ̇⁠méţé֥y ʻwòláֽm׃s"],[3,7,"גָּדַ֧ר בַּעֲדִ֛⁠י וְ⁠לֹ֥א אֵצֵ֖א הִכְבִּ֥יד נְחָשְׁתִּֽ⁠י׃","gá̇da֧r bȧʻàdi֛⁠y wĕ⁠lò֥ʼ ʼéẕé֖ʼ hikĕbi֥̇yd nĕẖáşĕ̌ţiֽ̇⁠y׃"],[3,8,"גַּ֣ם כִּ֤י אֶזְעַק֙ וַ⁠אֲשַׁוֵּ֔עַ שָׂתַ֖ם תְּפִלָּתִֽ⁠י׃","gȧ֣m ki֤̇y ʼezĕʻaq֙ wa⁠ʼàşǎwé̇֔ʻa şá̂ţa֖m ţĕ̇pilá̇ţiֽ⁠y׃"],[3,9,"גָּדַ֤ר דְּרָכַ⁠י֙ בְּ⁠גָזִ֔ית נְתִיבֹתַ֖⁠י עִוָּֽה׃ס","gá̇da֤r dĕ̇ráka⁠y֙ bĕ̇⁠gázi֔yţ nĕţiybòţa֖⁠y ʻiwáֽ̇h׃s"],[3,10,"דֹּ֣ב אֹרֵ֥ב הוּא֙ לִ֔⁠י אריה בְּ⁠מִסְתָּרִֽים׃","dò֣̇b ʼòré֥b hẇʼ֙ li֔⁠y ʼryh bĕ̇⁠misĕţá̇riֽym׃"],[3,11,"דְּרָכַ֥⁠י סוֹרֵ֛ר וַֽ⁠יְפַשְּׁחֵ֖⁠נִי שָׂמַ֥⁠נִי שֹׁמֵֽם׃","dĕ̇ráka֥⁠y swòré֛r waֽ⁠yĕpaşĕ̇̌ẖé֖⁠niy şá̂ma֥⁠niy şò̌méֽm׃"],[3,12,"דָּרַ֤ךְ קַשְׁת⁠וֹ֙ וַ⁠יַּצִּיבֵ֔⁠נִי כַּ⁠מַּטָּרָ֖א לַ⁠חֵֽץ׃ס","dá̇ra֤kĕ qaşĕ̌ţ⁠wò֙ wa⁠yȧẕi̇ybé֔⁠niy kȧ⁠mȧtá̇rá֖ʼ la⁠ẖéֽẕ׃s"],[3,13,"הֵבִיא֙ בְּ⁠כִלְיוֹתָ֔⁠י בְּנֵ֖י אַשְׁפָּתֽ⁠וֹ׃","hébiyʼ֙ bĕ̇⁠kilĕywòţá֔⁠y bĕ̇né֖y ʼaşĕ̌pá̇ţֽ⁠wò׃"],[3,14,"הָיִ֤יתִי שְּׂחֹק֙ לְ⁠כָל־עַמִּ֔⁠י נְגִינָתָ֖⁠ם כָּל־הַ⁠יּֽוֹם׃","háyi֤yţiy şĕ̇̂ẖòq֙ lĕ⁠kál-ʻami̇֔⁠y nĕgiynáţá֖⁠m ká̇l-ha⁠ẏֽwòm׃"],[3,15,"הִשְׂבִּיעַ֥⁠נִי בַ⁠מְּרוֹרִ֖ים הִרְוַ֥⁠נִי לַעֲנָֽה׃ס","hişĕ̂bi̇yʻa֥⁠niy ba⁠mĕ̇rwòri֖ym hirĕwa֥⁠niy laʻànáֽh׃s"],[3,16,"וַ⁠יַּגְרֵ֤ס בֶּֽ⁠חָצָץ֙ שִׁנָּ֔⁠י הִכְפִּישַׁ֖⁠נִי בָּ⁠אֵֽפֶר׃","wa⁠yȧgĕré֤s bėֽ⁠ẖáẕáẕ֙ şǐná̇֔⁠y hikĕpi̇yşǎ֖⁠niy bá̇⁠ʼéֽper׃"],[3,17,"וַ⁠תִּזְנַ֧ח מִ⁠שָּׁל֛וֹם נַפְשִׁ֖⁠י נָשִׁ֥יתִי טוֹבָֽה׃","wa⁠ţi̇zĕna֧ẖ mi⁠şá̇̌l֛wòm napĕşǐ֖⁠y náşǐ֥yţiy twòbáֽh׃"],[3,18,"וָ⁠אֹמַר֙ אָבַ֣ד נִצְחִ֔⁠י וְ⁠תוֹחַלְתִּ֖⁠י מֵ⁠יְהוָֽה׃ס","wá⁠ʼòmar֙ ʼába֣d niẕĕẖi֔⁠y wĕ⁠ţwòẖalĕţi֖̇⁠y mé⁠yĕhwáֽh׃s"],[3,19,"זְכָר־עָנְיִ֥⁠י וּ⁠מְרוּדִ֖⁠י לַעֲנָ֥ה וָ⁠רֹֽאשׁ׃","zĕkár-ʻánĕyi֥⁠y ẇ⁠mĕrẇdi֖⁠y laʻàná֥h wá⁠ròֽʼş̌׃"],[3,20,"זָכ֣וֹר תִּזְכּ֔וֹר ו⁠תשיח עָלַ֖⁠י נַפְשִֽׁ⁠י׃","zák֣wòr ţi̇zĕk̇֔wòr w⁠ţşyẖ ʻála֖⁠y napĕşǐֽ⁠y׃"],[3,21,"זֹ֛את אָשִׁ֥יב אֶל־לִבִּ֖⁠י עַל־כֵּ֥ן אוֹחִֽיל׃ס","zò֛ʼţ ʼáşǐ֥yb ʼel-libi֖̇⁠y ʻal-ké֥̇n ʼwòẖiֽyl׃s"],[3,22,"חַֽסְדֵ֤י יְהוָה֙ כִּ֣י לֹא־תָ֔מְנוּ כִּ֥י לֹא־כָל֖וּ רַחֲמָֽי⁠ו׃","ẖaֽsĕdé֤y yĕhwáh֙ ki֣̇y lòʼ-ţá֔mĕnẇ ki֥̇y lòʼ-kál֖ẇ raẖàmáֽy⁠w׃"],[3,23,"חֲדָשִׁים֙ לַ⁠בְּקָרִ֔ים רַבָּ֖ה אֱמוּנָתֶֽ⁠ךָ׃","ẖàdáşǐym֙ la⁠bĕ̇qári֔ym rabá֖̇h ʼèmẇnáţeֽ⁠ká׃"],[3,24,"חֶלְקִ֤⁠י יְהוָה֙ אָמְרָ֣ה נַפְשִׁ֔⁠י עַל־כֵּ֖ן אוֹחִ֥יל לֽ⁠וֹ׃ס","ẖelĕqi֤⁠y yĕhwáh֙ ʼámĕrá֣h napĕşǐ֔⁠y ʻal-ké֖̇n ʼwòẖi֥yl lֽ⁠wò׃s"],[3,25,"ט֤וֹב יְהוָה֙ לְ⁠קוָֹ֔⁠ו לְ⁠נֶ֖פֶשׁ תִּדְרְשֶֽׁ⁠נּוּ׃","t֤wòb yĕhwáh֙ lĕ⁠qwáò֔⁠w lĕ⁠ne֖peş̌ ţi̇dĕrĕşěֽ⁠ṅẇ׃"],[3,26,"ט֤וֹב וְ⁠יָחִיל֙ וְ⁠דוּמָ֔ם לִ⁠תְשׁוּעַ֖ת יְהוָֽה׃","t֤wòb wĕ⁠yáẖiyl֙ wĕ⁠dẇmá֔m li⁠ţĕş̌ẇʻa֖ţ yĕhwáֽh׃"],[3,27,"ט֣וֹב לַ⁠גֶּ֔בֶר כִּֽי־יִשָּׂ֥א עֹ֖ל בִּ⁠נְעוּרָֽי⁠ו׃ס","t֣wòb la⁠gė֔ber kiֽ̇y-yişá֥̇̂ʼ ʻò֖l bi̇⁠nĕʻẇráֽy⁠w׃s"],[3,28,"יֵשֵׁ֤ב בָּדָד֙ וְ⁠יִדֹּ֔ם כִּ֥י נָטַ֖ל עָלָֽי⁠ו׃","yéşé֤̌b bá̇dád֙ wĕ⁠yidò̇֔m ki֥̇y náta֖l ʻáláֽy⁠w׃"],[3,29,"יִתֵּ֤ן בֶּֽ⁠עָפָר֙ פִּ֔י⁠הוּ אוּלַ֖י יֵ֥שׁ תִּקְוָֽה׃","yiţé֤̇n bėֽ⁠ʻápár֙ pi̇֔y⁠hẇ ʼẇla֖y yé֥ş̌ ţi̇qĕwáֽh׃"],[3,30,"יִתֵּ֧ן לְ⁠מַכֵּ֛⁠הוּ לֶ֖חִי יִשְׂבַּ֥ע בְּ⁠חֶרְפָּֽה׃ס","yiţé֧̇n lĕ⁠maké֛̇⁠hẇ le֖ẖiy yişĕ̂bȧ֥ʻ bĕ̇⁠ẖerĕpáֽ̇h׃s"],[3,31,"כִּ֣י לֹ֥א יִזְנַ֛ח לְ⁠עוֹלָ֖ם אֲדֹנָֽ⁠י׃","ki֣̇y lò֥ʼ yizĕna֛ẖ lĕ⁠ʻwòlá֖m ʼàdònáֽ⁠y׃"],[3,32,"כִּ֣י אִם־הוֹגָ֔ה וְ⁠רִחַ֖ם כְּ⁠רֹ֥ב חסד⁠ו׃","ki֣̇y ʼim-hwògá֔h wĕ⁠riẖa֖m kĕ̇⁠rò֥b ẖsd⁠w׃"],[3,33,"כִּ֣י לֹ֤א עִנָּה֙ מִ⁠לִּבּ֔⁠וֹ וַ⁠יַּגֶּ֖ה בְנֵי־אִֽישׁ׃ס","ki֣̇y lò֤ʼ ʻiná̇h֙ mi⁠li̇ḃ֔⁠wò wa⁠yȧgė֖h bĕnéy-ʼiֽyş̌׃s"],[3,34,"לְ⁠דַכֵּא֙ תַּ֣חַת רַגְלָ֔י⁠ו כֹּ֖ל אֲסִ֥ירֵי אָֽרֶץ׃","lĕ⁠daké̇ʼ֙ ţȧ֣ẖaţ ragĕlá֔y⁠w kò֖̇l ʼàsi֥yréy ʼáֽreẕ׃"],[3,35,"לְ⁠הַטּוֹת֙ מִשְׁפַּט־גָּ֔בֶר נֶ֖גֶד פְּנֵ֥י עֶלְיֽוֹן׃","lĕ⁠haṫwòţ֙ mişĕ̌pȧt-gá̇֔ber ne֖ged pĕ̇né֥y ʻelĕyֽwòn׃"],[3,36,"לְ⁠עַוֵּ֤ת אָדָם֙ בְּ⁠רִיב֔⁠וֹ אֲדֹנָ֖⁠י לֹ֥א רָאָֽה׃ס","lĕ⁠ʻawé֤̇ţ ʼádám֙ bĕ̇⁠riyb֔⁠wò ʼàdòná֖⁠y lò֥ʼ ráʼáֽh׃s"],[3,37,"מִ֣י זֶ֤ה אָמַר֙ וַ⁠תֶּ֔הִי אֲדֹנָ֖⁠י לֹ֥א צִוָּֽה׃","mi֣y ze֤h ʼámar֙ wa⁠ţė֔hiy ʼàdòná֖⁠y lò֥ʼ ẕiwáֽ̇h׃"],[3,38,"מִ⁠פִּ֤י עֶלְיוֹן֙ לֹ֣א תֵצֵ֔א הָ⁠רָע֖וֹת וְ⁠הַ⁠טּֽוֹב׃","mi⁠pi֤̇y ʻelĕywòn֙ lò֣ʼ ţéẕé֔ʼ há⁠ráʻ֖wòţ wĕ⁠ha⁠ṫֽwòb׃"],[3,39,"מַה־יִּתְאוֹנֵן֙ אָדָ֣ם חָ֔י גֶּ֖בֶר עַל־חטא⁠ו׃ס","mah-yi̇ţĕʼwònén֙ ʼádá֣m ẖá֔y gė֖ber ʻal-ẖtʼ⁠w׃s"],[3,40,"נַחְפְּשָׂ֤ה דְרָכֵ֨י⁠נוּ֙ וְֽ⁠נַחְקֹ֔רָה וְ⁠נָשׁ֖וּבָה עַד־יְהוָֽה׃","naẖĕpĕ̇şá֤̂h dĕráké֨y⁠nẇ֙ wĕֽ⁠naẖĕqò֔ráh wĕ⁠náş֖̌ẇbáh ʻad-yĕhwáֽh׃"],[3,41,"נִשָּׂ֤א לְבָבֵ֨⁠נוּ֙ אֶל־כַּפָּ֔יִם אֶל־אֵ֖ל בַּ⁠שָּׁמָֽיִם׃","nişá֤̇̂ʼ lĕbábé֨⁠nẇ֙ ʼel-kȧpá̇֔yim ʼel-ʼé֖l bȧ⁠şá̇̌máֽyim׃"],[3,42,"נַ֤חְנוּ פָשַׁ֨עְנוּ֙ וּ⁠מָרִ֔ינוּ אַתָּ֖ה לֹ֥א סָלָֽחְתָּ׃ס","na֤ẖĕnẇ páşǎ֨ʻĕnẇ֙ ẇ⁠mári֔ynẇ ʼaţá֖̇h lò֥ʼ sáláֽẖĕţá̇׃s"],[3,43,"סַכֹּ֤תָה בָ⁠אַף֙ וַֽ⁠תִּרְדְּפֵ֔⁠נוּ הָרַ֖גְתָּ לֹ֥א חָמָֽלְתָּ׃","sakò֤̇ţáh bá⁠ʼap֙ waֽ⁠ţi̇rĕdĕ̇pé֔⁠nẇ hára֖gĕţá̇ lò֥ʼ ẖámáֽlĕţá̇׃"],[3,44,"סַכּ֤וֹתָה בֶֽ⁠עָנָן֙ לָ֔⁠ךְ מֵ⁠עֲב֖וֹר תְּפִלָּֽה׃","sak֤̇wòţáh beֽ⁠ʻánán֙ lá֔⁠kĕ mé⁠ʻàb֖wòr ţĕ̇piláֽ̇h׃"],[3,45,"סְחִ֧י וּ⁠מָא֛וֹס תְּשִׂימֵ֖⁠נוּ בְּ⁠קֶ֥רֶב הָ⁠עַמִּֽים׃ס","sĕẖi֧y ẇ⁠máʼ֛wòs ţĕ̇şîymé֖⁠nẇ bĕ̇⁠qe֥reb há⁠ʻamiֽ̇ym׃s"],[3,46,"פָּצ֥וּ עָלֵ֛י⁠נוּ פִּי⁠הֶ֖ם כָּל־אֹיְבֵֽי⁠נוּ׃","pá̇ẕ֥ẇ ʻálé֛y⁠nẇ pi̇y⁠he֖m ká̇l-ʼòyĕbéֽy⁠nẇ׃"],[3,47,"פַּ֧חַד וָ⁠פַ֛חַת הָ֥יָה לָ֖⁠נוּ הַ⁠שֵּׁ֥את וְ⁠הַ⁠שָּֽׁבֶר׃","pȧ֧ẖad wá⁠pa֛ẖaţ há֥yáh lá֖⁠nẇ ha⁠şé֥̇̌ʼţ wĕ⁠ha⁠şáֽ̇̌ber׃"],[3,48,"פַּלְגֵי־מַ֨יִם֙ תֵּרַ֣ד עֵינִ֔⁠י עַל־שֶׁ֖בֶר בַּת־עַמִּֽ⁠י׃ס","pȧlĕgéy-ma֨yim֙ ţé̇ra֣d ʻéyni֔⁠y ʻal-şě֖ber bȧţ-ʻamiֽ̇⁠y׃s"],[3,49,"עֵינִ֧⁠י נִגְּרָ֛ה וְ⁠לֹ֥א תִדְמֶ֖ה מֵ⁠אֵ֥ין הֲפֻגֽוֹת׃","ʻéyni֧⁠y nigĕ̇rá֛h wĕ⁠lò֥ʼ ţidĕme֖h mé⁠ʼé֥yn hàpugֽwòţ׃"],[3,50,"עַד־יַשְׁקִ֣יף וְ⁠יֵ֔רֶא יְהוָ֖ה מִ⁠שָּׁמָֽיִם׃","ʻad-yaşĕ̌qi֣yp wĕ⁠yé֔reʼ yĕhwá֖h mi⁠şá̇̌máֽyim׃"],[3,51,"עֵינִ⁠י֙ עֽוֹלְלָ֣ה לְ⁠נַפְשִׁ֔⁠י מִ⁠כֹּ֖ל בְּנ֥וֹת עִירִֽ⁠י׃ס","ʻéyni⁠y֙ ʻֽwòlĕlá֣h lĕ⁠napĕşǐ֔⁠y mi⁠kò֖̇l bĕ̇n֥wòţ ʻiyriֽ⁠y׃s"],[3,52,"צ֥וֹד צָד֛וּ⁠נִי כַּ⁠צִּפּ֖וֹר אֹיְבַ֥⁠י חִנָּֽם׃","ẕ֥wòd ẕád֛ẇ⁠niy kȧ⁠ẕi̇ṗ֖wòr ʼòyĕba֥⁠y ẖináֽ̇m׃"],[3,53,"צָֽמְת֤וּ בַ⁠בּוֹר֙ חַיָּ֔⁠י וַ⁠יַּדּוּ־אֶ֖בֶן בִּֽ⁠י׃","ẕáֽmĕţ֤ẇ ba⁠ḃwòr֙ ẖayá̇֔⁠y wa⁠yȧḋẇ-ʼe֖ben biֽ̇⁠y׃"],[3,54,"צָֽפוּ־מַ֥יִם עַל־רֹאשִׁ֖⁠י אָמַ֥רְתִּי נִגְזָֽרְתִּי׃ס","ẕáֽpẇ-ma֥yim ʻal-ròʼşǐ֖⁠y ʼáma֥rĕţi̇y nigĕzáֽrĕţi̇y׃s"],[3,55,"קָרָ֤אתִי שִׁמְ⁠ךָ֙ יְהוָ֔ה מִ⁠בּ֖וֹר תַּחְתִּיּֽוֹת׃","qárá֤ʼţiy şǐmĕ⁠ká֙ yĕhwá֔h mi⁠ḃ֖wòr ţȧẖĕţi̇ẏֽwòţ׃"],[3,56,"קוֹלִ֖⁠י שָׁמָ֑עְתָּ אַל־תַּעְלֵ֧ם אָזְנְ⁠ךָ֛ לְ⁠רַוְחָתִ֖⁠י לְ⁠שַׁוְעָתִֽ⁠י׃","qwòli֖⁠y şá̌má֑ʻĕţá̇ ʼal-ţȧʻĕlé֧m ʼázĕnĕ⁠ká֛ lĕ⁠rawĕẖáţi֖⁠y lĕ⁠şǎwĕʻáţiֽ⁠y׃"],[3,57,"קָרַ֨בְתָּ֙ בְּ⁠י֣וֹם אֶקְרָאֶ֔⁠ךָּ אָמַ֖רְתָּ אַל־תִּירָֽא׃ס","qára֨bĕţá̇֙ bĕ̇⁠y֣wòm ʼeqĕráʼe֔⁠ká̇ ʼáma֖rĕţá̇ ʼal-ţi̇yráֽʼ׃s"],[3,58,"רַ֧בְתָּ אֲדֹנָ֛⁠י רִיבֵ֥י נַפְשִׁ֖⁠י גָּאַ֥לְתָּ חַיָּֽ⁠י׃","ra֧bĕţá̇ ʼàdòná֛⁠y riybé֥y napĕşǐ֖⁠y gá̇ʼa֥lĕţá̇ ẖayáֽ̇⁠y׃"],[3,59,"רָאִ֤יתָה יְהוָה֙ עַוָּ֣תָתִ֔⁠י שָׁפְטָ֖⁠ה מִשְׁפָּטִֽ⁠י׃","ráʼi֤yţáh yĕhwáh֙ ʻawá֣̇ţáţi֔⁠y şá̌pĕtá֖⁠h mişĕ̌pá̇tiֽ⁠y׃"],[3,60,"רָאִ֨יתָה֙ כָּל־נִקְמָתָ֔⁠ם כָּל־מַחְשְׁבֹתָ֖⁠ם לִֽ⁠י׃ס","ráʼi֨yţáh֙ ká̇l-niqĕmáţá֔⁠m ká̇l-maẖĕşĕ̌bòţá֖⁠m liֽ⁠y׃s"],[3,61,"שָׁמַ֤עְתָּ חֶרְפָּתָ⁠ם֙ יְהוָ֔ה כָּל־מַחְשְׁבֹתָ֖⁠ם עָלָֽ⁠י׃","şá̌ma֤ʻĕţá̇ ẖerĕpá̇ţá⁠m֙ yĕhwá֔h ká̇l-maẖĕşĕ̌bòţá֖⁠m ʻáláֽ⁠y׃"],[3,62,"שִׂפְתֵ֤י קָמַ⁠י֙ וְ⁠הֶגְיוֹנָ֔⁠ם עָלַ֖⁠י כָּל־הַ⁠יּֽוֹם׃","şîpĕţé֤y qáma⁠y֙ wĕ⁠hegĕywòná֔⁠m ʻála֖⁠y ká̇l-ha⁠ẏֽwòm׃"],[3,63,"שִׁבְתָּ֤⁠ם וְ⁠קִֽימָתָ⁠ם֙ הַבִּ֔יטָ⁠ה אֲנִ֖י מַנְגִּינָתָֽ⁠ם׃ס","şǐbĕţá֤̇⁠m wĕ⁠qiֽymáţá⁠m֙ habi̇֔ytá⁠h ʼàni֖y manĕgi̇ynáţáֽ⁠m׃s"],[3,64,"תָּשִׁ֨יב לָ⁠הֶ֥ם גְּמ֛וּל יְהוָ֖ה כְּ⁠מַעֲשֵׂ֥ה יְדֵי⁠הֶֽם׃","ţá̇şǐ֨yb lá⁠he֥m gĕ̇m֛ẇl yĕhwá֖h kĕ̇⁠maʻàşé֥̂h yĕdéy⁠heֽm׃"],[3,65,"תִּתֵּ֤ן לָ⁠הֶם֙ מְגִנַּת־לֵ֔ב תַּאֲלָֽתְ⁠ךָ֖ לָ⁠הֶֽם׃","ţi̇ţé֤̇n lá⁠hem֙ mĕginȧţ-lé֔b ţȧʼàláֽţĕ⁠ká֖ lá⁠heֽm׃"],[3,66,"תִּרְדֹּ֤ף בְּ⁠אַף֙ וְ⁠תַשְׁמִידֵ֔⁠ם מִ⁠תַּ֖חַת שְׁמֵ֥י יְהוָֽה׃פ","ţi̇rĕdò֤̇p bĕ̇⁠ʼap֙ wĕ⁠ţaşĕ̌miydé֔⁠m mi⁠ţȧ֖ẖaţ şĕ̌mé֥y yĕhwáֽh׃p"],[4,1,"אֵיכָה֙ יוּעַ֣ם זָהָ֔ב יִשְׁנֶ֖א הַ⁠כֶּ֣תֶם הַ⁠טּ֑וֹב תִּשְׁתַּפֵּ֨כְנָה֙ אַבְנֵי־קֹ֔דֶשׁ בְּ⁠רֹ֖אשׁ כָּל־חוּצֽוֹת׃ס","ʼéykáh֙ yẇʻa֣m záhá֔b yişĕ̌ne֖ʼ ha⁠kė֣ţem ha⁠ṫ֑wòb ţi̇şĕ̌ţȧpé̇֨kĕnáh֙ ʼabĕnéy-qò֔deş̌ bĕ̇⁠rò֖ʼş̌ ká̇l-ẖẇẕֽwòţ׃s"],[4,2,"בְּנֵ֤י צִיּוֹן֙ הַ⁠יְקָרִ֔ים הַ⁠מְסֻלָּאִ֖ים בַּ⁠פָּ֑ז אֵיכָ֤ה נֶחְשְׁבוּ֙ לְ⁠נִבְלֵי־חֶ֔רֶשׂ מַעֲשֵׂ֖ה יְדֵ֥י יוֹצֵֽר׃ס","bĕ̇né֤y ẕiẏwòn֙ ha⁠yĕqári֔ym ha⁠mĕsulá̇ʼi֖ym bȧ⁠pá֑̇z ʼéyká֤h neẖĕşĕ̌bẇ֙ lĕ⁠nibĕléy-ẖe֔reş̂ maʻàşé֖̂h yĕdé֥y ywòẕéֽr׃s"],[4,3,"גַּם־תנין חָ֣לְצוּ שַׁ֔ד הֵינִ֖יקוּ גּוּרֵי⁠הֶ֑ן בַּת־עַמִּ֣⁠י לְ⁠אַכְזָ֔ר כי ענים בַּ⁠מִּדְבָּֽר׃ס","gȧm-ţnyn ẖá֣lĕẕẇ şǎ֔d héyni֖yqẇ ġẇréy⁠he֑n bȧţ-ʻami֣̇⁠y lĕ⁠ʼakĕzá֔r ky ʻnym bȧ⁠mi̇dĕbáֽ̇r׃s"],[4,4,"דָּבַ֨ק לְשׁ֥וֹן יוֹנֵ֛ק אֶל־חכּ֖⁠וֹ בַּ⁠צָּמָ֑א עֽוֹלָלִים֙ שָׁ֣אֲלוּ לֶ֔חֶם פֹּרֵ֖שׂ אֵ֥ין לָ⁠הֶֽם׃ס","dá̇ba֨q lĕş֥̌wòn ywòné֛q ʼel-ẖk֖̇⁠wò bȧ⁠ẕá̇má֑ʼ ʻֽwòláliym֙ şá֣̌ʼàlẇ le֔ẖem pò̇ré֖ş̂ ʼé֥yn lá⁠heֽm׃s"],[4,5,"הָ⁠אֹֽכְלִים֙ לְ⁠מַ֣עֲדַנִּ֔ים נָשַׁ֖מּוּ בַּ⁠חוּצ֑וֹת הָ⁠אֱמֻנִים֙ עֲלֵ֣י תוֹלָ֔ע חִבְּק֖וּ אַשְׁפַּתּֽוֹת׃ס","há⁠ʼòֽkĕliym֙ lĕ⁠ma֣ʻàdani̇֔ym náşǎ֖ṁẇ bȧ⁠ẖẇẕ֑wòţ há⁠ʼèmuniym֙ ʻàlé֣y ţwòlá֔ʻ ẖibĕ̇q֖ẇ ʼaşĕ̌pȧţֽ̇wòţ׃s"],[4,6,"וַ⁠יִּגְדַּל֙ עֲוֺ֣ן בַּת־עַמִּ֔⁠י מֵֽ⁠חַטַּ֖את סְדֹ֑ם הַֽ⁠הֲפוּכָ֣ה כְמוֹ־רָ֔גַע וְ⁠לֹא־חָ֥לוּ בָ֖⁠הּ יָדָֽיִם׃ס","wa⁠yi̇gĕdȧl֙ ʻàwֺ֣n bȧţ-ʻami̇֔⁠y méֽ⁠ẖatȧ֖ʼţ sĕdò֑m haֽ⁠hàpẇká֣h kĕmwò-rá֔gaʻ wĕ⁠lòʼ-ẖá֥lẇ bá֖⁠ḣ yádáֽyim׃s"],[4,7,"זַכּ֤וּ נְזִירֶ֨י⁠הָ֙ מִ⁠שֶּׁ֔לֶג צַח֖וּ מֵ⁠חָלָ֑ב אָ֤דְמוּ עֶ֨צֶם֙ מִ⁠פְּנִינִ֔ים סַפִּ֖יר גִּזְרָתָֽ⁠ם׃ס","zak֤̇ẇ nĕziyre֨y⁠há֙ mi⁠şė̌֔leg ẕaẖ֖ẇ mé⁠ẖálá֑b ʼá֤dĕmẇ ʻe֨ẕem֙ mi⁠pĕ̇niyni֔ym sapi֖̇yr gi̇zĕráţáֽ⁠m׃s"],[4,8,"חָשַׁ֤ךְ מִ⁠שְּׁחוֹר֙ תָּֽאֳרָ֔⁠ם לֹ֥א נִכְּר֖וּ בַּ⁠חוּצ֑וֹת צָפַ֤ד עוֹרָ⁠ם֙ עַל־עַצְמָ֔⁠ם יָבֵ֖שׁ הָיָ֥ה כָ⁠עֵֽץ׃ס","ẖáşǎ֤kĕ mi⁠şĕ̇̌ẖwòr֙ ţáֽ̇ʼorá֔⁠m lò֥ʼ nikĕ̇r֖ẇ bȧ⁠ẖẇẕ֑wòţ ẕápa֤d ʻwòrá⁠m֙ ʻal-ʻaẕĕmá֔⁠m yábé֖ş̌ háyá֥h ká⁠ʻéֽẕ׃s"],[4,9,"טוֹבִ֤ים הָיוּ֙ חַלְלֵי־חֶ֔רֶב מֵֽ⁠חַלְלֵ֖י רָעָ֑ב שֶׁ֣⁠הֵ֤ם יָז֨וּבוּ֙ מְדֻקָּרִ֔ים מִ⁠תְּנוּבֹ֖ת שָׂדָֽי׃ס","twòbi֤ym háyẇ֙ ẖalĕléy-ẖe֔reb méֽ⁠ẖalĕlé֖y ráʻá֑b şě֣⁠hé֤m yáz֨ẇbẇ֙ mĕduqá̇ri֔ym mi⁠ţĕ̇nẇbò֖ţ şá̂dáֽy׃s"],[4,10,"יְדֵ֗י נָשִׁים֙ רַחֲמָ֣נִיּ֔וֹת בִּשְּׁל֖וּ יַלְדֵי⁠הֶ֑ן הָי֤וּ לְ⁠בָרוֹת֙ לָ֔⁠מוֹ בְּ⁠שֶׁ֖בֶר בַּת־עַמִּֽ⁠י׃ס","yĕdé֗y náşǐym֙ raẖàmá֣niẏ֔wòţ bi̇şĕ̇̌l֖ẇ yalĕdéy⁠he֑n háy֤ẇ lĕ⁠bárwòţ֙ lá֔⁠mwò bĕ̇⁠şě֖ber bȧţ-ʻamiֽ̇⁠y׃s"],[4,11,"כִּלָּ֤ה יְהוָה֙ אֶת־חֲמָת֔⁠וֹ שָׁפַ֖ךְ חֲר֣וֹן אַפּ֑⁠וֹ וַ⁠יַּצֶּת־אֵ֣שׁ בְּ⁠צִיּ֔וֹן וַ⁠תֹּ֖אכַל יְסוֹדֹתֶֽי⁠הָ׃ס","ki̇lá֤̇h yĕhwáh֙ ʼeţ-ẖàmáţ֔⁠wò şá̌pa֖kĕ ẖàr֣wòn ʼaṗ֑⁠wò wa⁠yȧẕėţ-ʼé֣ş̌ bĕ̇⁠ẕiẏ֔wòn wa⁠ţò֖̇ʼkal yĕswòdòţeֽy⁠há׃s"],[4,12,"לֹ֤א הֶאֱמִ֨ינוּ֙ מַלְכֵי־אֶ֔רֶץ ו⁠כל יֹשְׁבֵ֣י תֵבֵ֑ל כִּ֤י יָבֹא֙ צַ֣ר וְ⁠אוֹיֵ֔ב בְּ⁠שַׁעֲרֵ֖י יְרוּשָׁלִָֽם׃ס","lò֤ʼ heʼèmi֨ynẇ֙ malĕkéy-ʼe֔reẕ w⁠kl yòşĕ̌bé֣y ţébé֑l ki֤̇y yábòʼ֙ ẕa֣r wĕ⁠ʼwòyé֔b bĕ̇⁠şǎʻàré֖y yĕrẇşá̌liáֽm׃s"],[4,13,"מֵֽ⁠חַטֹּ֣את נְבִיאֶ֔י⁠הָ עֲוֺנ֖וֹת כֹּהֲנֶ֑י⁠הָ הַ⁠שֹּׁפְכִ֥ים בְּ⁠קִרְבָּ֖⁠הּ דַּ֥ם צַדִּיקִֽים׃ס","méֽ⁠ẖatò֣̇ʼţ nĕbiyʼe֔y⁠há ʻàwֺn֖wòţ kò̇hàne֑y⁠há ha⁠şò̇̌pĕki֥ym bĕ̇⁠qirĕbá֖̇⁠ḣ dȧ֥m ẕadi̇yqiֽym׃s"],[4,14,"נָע֤וּ עִוְרִים֙ בַּֽ⁠חוּצ֔וֹת נְגֹֽאֲל֖וּ בַּ⁠דָּ֑ם בְּ⁠לֹ֣א יֽוּכְל֔וּ יִגְּע֖וּ בִּ⁠לְבֻשֵׁי⁠הֶֽם׃ס","náʻ֤ẇ ʻiwĕriym֙ bȧֽ⁠ẖẇẕ֔wòţ nĕgòֽʼàl֖ẇ bȧ⁠dá֑̇m bĕ̇⁠lò֣ʼ yֽẇkĕl֔ẇ yigĕ̇ʻ֖ẇ bi̇⁠lĕbuşé̌y⁠heֽm׃s"],[4,15,"ס֣וּרוּ טָמֵ֞א קָ֣רְאוּ לָ֗⁠מוֹ ס֤וּרוּ ס֨וּרוּ֙ אַל־תִּגָּ֔עוּ כִּ֥י נָצ֖וּ גַּם־נָ֑עוּ אָֽמְרוּ֙ בַּ⁠גּוֹיִ֔ם לֹ֥א יוֹסִ֖יפוּ לָ⁠גֽוּר׃ס","s֣ẇrẇ támé֞ʼ qá֣rĕʼẇ lá֗⁠mwò s֤ẇrẇ s֨ẇrẇ֙ ʼal-ţi̇gá̇֔ʻẇ ki֥̇y náẕ֖ẇ gȧm-ná֑ʻẇ ʼáֽmĕrẇ֙ bȧ⁠ġwòyi֔m lò֥ʼ ywòsi֖ypẇ lá⁠gֽẇr׃s"],[4,16,"פְּנֵ֤י יְהוָה֙ חִלְּקָ֔⁠ם לֹ֥א יוֹסִ֖יף לְ⁠הַבִּיטָ֑⁠ם פְּנֵ֤י כֹהֲנִים֙ לֹ֣א נָשָׂ֔אוּ זקנים לֹ֥א חָנָֽנוּ׃ס","pĕ̇né֤y yĕhwáh֙ ẖilĕ̇qá֔⁠m lò֥ʼ ywòsi֖yp lĕ⁠habi̇ytá֑⁠m pĕ̇né֤y kòhàniym֙ lò֣ʼ náşá̂֔ʼẇ zqnym lò֥ʼ ẖánáֽnẇ׃s"],[4,17,"עוד⁠ינה תִּכְלֶ֣ינָה עֵינֵ֔י⁠נוּ אֶל־עֶזְרָתֵ֖⁠נוּ הָ֑בֶל בְּ⁠צִפִּיָּתֵ֣⁠נוּ צִפִּ֔ינוּ אֶל־גּ֖וֹי לֹ֥א יוֹשִֽׁעַ׃ס","ʻwd⁠ynh ţi̇kĕle֣ynáh ʻéyné֔y⁠nẇ ʼel-ʻezĕráţé֖⁠nẇ há֑bel bĕ̇⁠ẕipi̇yá̇ţé֣⁠nẇ ẕipi̇֔ynẇ ʼel-ġ֖wòy lò֥ʼ ywòşǐֽʻa׃s"],[4,18,"צָד֣וּ צְעָדֵ֔י⁠נוּ מִ⁠לֶּ֖כֶת בִּ⁠רְחֹבֹתֵ֑י⁠נוּ קָרַ֥ב קִצֵּ֛י⁠נוּ מָלְא֥וּ יָמֵ֖י⁠נוּ כִּי־בָ֥א קִצֵּֽי⁠נוּ׃ס","ẕád֣ẇ ẕĕʻádé֔y⁠nẇ mi⁠lė֖keţ bi̇⁠rĕẖòbòţé֑y⁠nẇ qára֥b qiẕé֛̇y⁠nẇ málĕʼ֥ẇ yámé֖y⁠nẇ ki̇y-bá֥ʼ qiẕéֽ̇y⁠nẇ׃s"],[4,19,"קַלִּ֤ים הָיוּ֙ רֹדְפֵ֔י⁠נוּ מִ⁠נִּשְׁרֵ֖י שָׁמָ֑יִם עַל־הֶ⁠הָרִ֣ים דְּלָקֻ֔⁠נוּ בַּ⁠מִּדְבָּ֖ר אָ֥רְבוּ לָֽ⁠נוּ׃ס","qali֤̇ym háyẇ֙ ròdĕpé֔y⁠nẇ mi⁠ni̇şĕ̌ré֖y şá̌má֑yim ʻal-he⁠hári֣ym dĕ̇láqu֔⁠nẇ bȧ⁠mi̇dĕbá֖̇r ʼá֥rĕbẇ láֽ⁠nẇ׃s"],[4,20,"ר֤וּחַ אַפֵּ֨י⁠נוּ֙ מְשִׁ֣יחַ יְהוָ֔ה נִלְכַּ֖ד בִּ⁠שְׁחִיתוֹתָ֑⁠ם אֲשֶׁ֣ר אָמַ֔רְנוּ בְּ⁠צִלּ֖⁠וֹ נִֽחְיֶ֥ה בַ⁠גּוֹיִֽם׃ס","r֤ẇẖa ʼapé̇֨y⁠nẇ֙ mĕşǐ֣yẖa yĕhwá֔h nilĕkȧ֖d bi̇⁠şĕ̌ẖiyţwòţá֑⁠m ʼàşě֣r ʼáma֔rĕnẇ bĕ̇⁠ẕil֖̇⁠wò niֽẖĕye֥h ba⁠ġwòyiֽm׃s"],[4,21,"שִׂ֤ישִׂי וְ⁠שִׂמְחִי֙ בַּת־אֱד֔וֹם יושבתי בְּ⁠אֶ֣רֶץ ע֑וּץ גַּם־עָלַ֨יִ⁠ךְ֙ תַּעֲבָר־כּ֔וֹס תִּשְׁכְּרִ֖י וְ⁠תִתְעָרִֽי׃ס","şî֤yşîy wĕ⁠şîmĕẖiy֙ bȧţ-ʼèd֔wòm ywşbţy bĕ̇⁠ʼe֣reẕ ʻ֑ẇẕ gȧm-ʻála֨yi⁠kĕ֙ ţȧʻàbár-k̇֔wòs ţi̇şĕ̌kĕ̇ri֖y wĕ⁠ţiţĕʻáriֽy׃s"],[4,22,"תַּם־עֲוֺנֵ⁠ךְ֙ בַּת־צִיּ֔וֹן לֹ֥א יוֹסִ֖יף לְ⁠הַגְלוֹתֵ֑⁠ךְ פָּקַ֤ד עֲוֺנֵ⁠ךְ֙ בַּת־אֱד֔וֹם גִּלָּ֖ה עַל־חַטֹּאתָֽיִ⁠ךְ׃פ","ţȧm-ʻàwֺné⁠kĕ֙ bȧţ-ẕiẏ֔wòn lò֥ʼ ywòsi֖yp lĕ⁠hagĕlwòţé֑⁠kĕ pá̇qa֤d ʻàwֺné⁠kĕ֙ bȧţ-ʼèd֔wòm gi̇lá֖̇h ʻal-ẖatò̇ʼţáֽyi⁠kĕ׃p"],[5,1,"זְכֹ֤ר יְהוָה֙ מֶֽה־הָ֣יָה לָ֔⁠נוּ הביט וּ⁠רְאֵ֥ה אֶת־חֶרְפָּתֵֽ⁠נוּ׃","zĕkò֤r yĕhwáh֙ meֽh-há֣yáh lá֔⁠nẇ hbyt ẇ⁠rĕʼé֥h ʼeţ-ẖerĕpá̇ţéֽ⁠nẇ׃"],[5,2,"נַחֲלָתֵ֨⁠נוּ֙ נֶֽהֶפְכָ֣ה לְ⁠זָרִ֔ים בָּתֵּ֖י⁠נוּ לְ⁠נָכְרִֽים׃","naẖàláţé֨⁠nẇ֙ neֽhepĕká֣h lĕ⁠zári֔ym bá̇ţé֖̇y⁠nẇ lĕ⁠nákĕriֽym׃"],[5,3,"יְתוֹמִ֤ים הָיִ֨ינוּ֙ אין אָ֔ב אִמֹּתֵ֖י⁠נוּ כְּ⁠אַלְמָנֽוֹת׃","yĕţwòmi֤ym háyi֨ynẇ֙ ʼyn ʼá֔b ʼimò̇ţé֖y⁠nẇ kĕ̇⁠ʼalĕmánֽwòţ׃"],[5,4,"מֵימֵ֨י⁠נוּ֙ בְּ⁠כֶ֣סֶף שָׁתִ֔ינוּ עֵצֵ֖י⁠נוּ בִּ⁠מְחִ֥יר יָבֹֽאוּ׃","méymé֨y⁠nẇ֙ bĕ̇⁠ke֣sep şá̌ţi֔ynẇ ʻéẕé֖y⁠nẇ bi̇⁠mĕẖi֥yr yábòֽʼẇ׃"],[5,5,"עַ֤ל צַוָּארֵ֨⁠נוּ֙ נִרְדָּ֔פְנוּ יָגַ֖עְנוּ לא הֽוּנַ֖ח לָֽ⁠נוּ׃","ʻa֤l ẕawá̇ʼré֨⁠nẇ֙ nirĕdá̇֔pĕnẇ yága֖ʻĕnẇ lʼ hֽẇna֖ẖ láֽ⁠nẇ׃"],[5,6,"מִצְרַ֨יִם֙ נָתַ֣נּוּ יָ֔ד אַשּׁ֖וּר לִ⁠שְׂבֹּ֥עַֽ לָֽחֶם׃","miẕĕra֨yim֙ náţa֣ṅẇ yá֔d ʼaş֖̇̌ẇr li⁠şĕ̂bò֥̇ʻaֽ láֽẖem׃"],[5,7,"אֲבֹתֵ֤י⁠נוּ חָֽטְאוּ֙ אינ⁠ם אנחנו עֲוֺנֹתֵי⁠הֶ֥ם סָבָֽלְנוּ׃","ʼàbòţé֤y⁠nẇ ẖáֽtĕʼẇ֙ ʼyn⁠m ʼnẖnw ʻàwֺnòţéy⁠he֥m sábáֽlĕnẇ׃"],[5,8,"עֲבָדִים֙ מָ֣שְׁלוּ בָ֔⁠נוּ פֹּרֵ֖ק אֵ֥ין מִ⁠יָּדָֽ⁠ם׃","ʻàbádiym֙ má֣şĕ̌lẇ bá֔⁠nẇ pò̇ré֖q ʼé֥yn mi⁠yá̇dáֽ⁠m׃"],[5,9,"בְּ⁠נַפְשֵׁ֨⁠נוּ֙ נָבִ֣יא לַחְמֵ֔⁠נוּ מִ⁠פְּנֵ֖י חֶ֥רֶב הַ⁠מִּדְבָּֽר׃","bĕ̇⁠napĕşé̌֨⁠nẇ֙ nábi֣yʼ laẖĕmé֔⁠nẇ mi⁠pĕ̇né֖y ẖe֥reb ha⁠mi̇dĕbáֽ̇r׃"],[5,10,"עוֹרֵ֨⁠נוּ֙ כְּ⁠תַנּ֣וּר נִכְמָ֔רוּ מִ⁠פְּנֵ֖י זַלְעֲפ֥וֹת רָעָֽב׃","ʻwòré֨⁠nẇ֙ kĕ̇⁠ţaṅ֣ẇr nikĕmá֔rẇ mi⁠pĕ̇né֖y zalĕʻàp֥wòţ ráʻáֽb׃"],[5,11,"נָשִׁים֙ בְּ⁠צִיּ֣וֹן עִנּ֔וּ בְּתֻלֹ֖ת בְּ⁠עָרֵ֥י יְהוּדָֽה׃","náşǐym֙ bĕ̇⁠ẕiẏ֣wòn ʻiṅ֔ẇ bĕ̇ţulò֖ţ bĕ̇⁠ʻáré֥y yĕhẇdáֽh׃"],[5,12,"שָׂרִים֙ בְּ⁠יָדָ֣⁠ם נִתְל֔וּ פְּנֵ֥י זְקֵנִ֖ים לֹ֥א נֶהְדָּֽרוּ׃","şá̂riym֙ bĕ̇⁠yádá֣⁠m niţĕl֔ẇ pĕ̇né֥y zĕqéni֖ym lò֥ʼ nehĕdáֽ̇rẇ׃"],[5,13,"בַּחוּרִים֙ טְח֣וֹן נָשָׂ֔אוּ וּ⁠נְעָרִ֖ים בָּ⁠עֵ֥ץ כָּשָֽׁלוּ׃","bȧẖẇriym֙ tĕẖ֣wòn náşá̂֔ʼẇ ẇ⁠nĕʻári֖ym bá̇⁠ʻé֥ẕ ká̇şáֽ̌lẇ׃"],[5,14,"זְקֵנִים֙ מִ⁠שַּׁ֣עַר שָׁבָ֔תוּ בַּחוּרִ֖ים מִ⁠נְּגִינָתָֽ⁠ם׃","zĕqéniym֙ mi⁠şȧ֣̌ʻar şá̌bá֔ţẇ bȧẖẇri֖ym mi⁠nĕ̇giynáţáֽ⁠m׃"],[5,15,"שָׁבַת֙ מְשׂ֣וֹשׂ לִבֵּ֔⁠נוּ נֶהְפַּ֥ךְ לְ⁠אֵ֖בֶל מְחֹלֵֽ⁠נוּ׃","şá̌baţ֙ mĕş֣̂wòş̂ libé̇֔⁠nẇ nehĕpȧ֥kĕ lĕ⁠ʼé֖bel mĕẖòléֽ⁠nẇ׃"],[5,16,"נָֽפְלָה֙ עֲטֶ֣רֶת רֹאשֵׁ֔⁠נוּ אֽוֹי־נָ֥א לָ֖⁠נוּ כִּ֥י חָטָֽאנוּ׃","náֽpĕláh֙ ʻàte֣reţ ròʼşé̌֔⁠nẇ ʼֽwòy-ná֥ʼ lá֖⁠nẇ ki֥̇y ẖátáֽʼnẇ׃"],[5,17,"עַל־זֶ֗ה הָיָ֤ה דָוֶה֙ לִבֵּ֔⁠נוּ עַל־אֵ֖לֶּה חָשְׁכ֥וּ עֵינֵֽי⁠נוּ׃","ʻal-ze֗h háyá֤h dáweh֙ libé̇֔⁠nẇ ʻal-ʼé֖lėh ẖáşĕ̌k֥ẇ ʻéynéֽy⁠nẇ׃"],[5,18,"עַ֤ל הַר־צִיּוֹן֙ שֶׁ⁠שָּׁמֵ֔ם שׁוּעָלִ֖ים הִלְּכוּ־בֽ⁠וֹ׃פ","ʻa֤l har-ẕiẏwòn֙ şě⁠şá̇̌mé֔m ş̌ẇʻáli֖ym hilĕ̇kẇ-bֽ⁠wò׃p"],[5,19,"אַתָּ֤ה יְהוָה֙ לְ⁠עוֹלָ֣ם תֵּשֵׁ֔ב כִּסְאֲ⁠ךָ֖ לְ⁠דֹ֥ר וָ⁠דֽוֹר׃","ʼaţá֤̇h yĕhwáh֙ lĕ⁠ʻwòlá֣m ţé̇şé̌֔b ki̇sĕʼà⁠ká֖ lĕ⁠dò֥r wá⁠dֽwòr׃"],[5,20,"לָ֤⁠מָּה לָ⁠נֶ֨צַח֙ תִּשְׁכָּחֵ֔⁠נוּ תַּֽעַזְבֵ֖⁠נוּ לְ⁠אֹ֥רֶךְ יָמִֽים׃","lá֤⁠má̇h lá⁠ne֨ẕaẖ֙ ţi̇şĕ̌ká̇ẖé֔⁠nẇ ţȧֽʻazĕbé֖⁠nẇ lĕ⁠ʼò֥rekĕ yámiֽym׃"],[5,21,"הֲשִׁיבֵ֨⁠נוּ יְהוָ֤ה ׀ אֵלֶ֨י⁠ךָ֙ ו⁠נשוב חַדֵּ֥שׁ יָמֵ֖י⁠נוּ כְּ⁠קֶֽדֶם׃","hàşǐybé֨⁠nẇ yĕhwá֤h ׀ ʼéle֨y⁠ká֙ w⁠nşwb ẖadé֥̇ş̌ yámé֖y⁠nẇ kĕ̇⁠qeֽdem׃"],[5,22,"כִּ֚י אִם־מָאֹ֣ס מְאַסְתָּ֔⁠נוּ קָצַ֥פְתָּ עָלֵ֖י⁠נוּ עַד־מְאֹֽד׃","ki֚̇y ʼim-máʼò֣s mĕʼasĕţá̇֔⁠nẇ qáẕa֥pĕţá̇ ʻálé֖y⁠nẇ ʻad-mĕʼòֽd׃"]],"fra-lsg1910":[[1,1,"Eh quoi! elle est assise solitaire, cette ville si peuplée! Elle est semblable à une veuve! Grande entre les nations, souveraine parmi les états, Elle est réduite à la servitude!","Eh quoi! elle est assise solitaire, cette ville si peuplée! Elle est semblable à une veuve! Grande entre les nations, souveraine parmi les états, Elle est réduite à la servitude!"],[1,2,"Elle pleure durant la nuit, et ses joues sont couvertes de larmes; De tous ceux qui l'aimaient nul ne la console; Tous ses amis lui sont devenus infidèles, Ils sont devenus ses ennemis.","Elle pleure durant la nuit, et ses joues sont couvertes de larmes; De tous ceux qui l'aimaient nul ne la console; Tous ses amis lui sont devenus infidèles, Ils sont devenus ses ennemis."],[1,3,"Juda est en exil, victime de l'oppression et d'une grande servitude; Il habite au milieu des nations, Et il n'y trouve point de repos; Tous ses persécuteurs l'ont surpris dans l'angoisse.","Juda est en exil, victime de l'oppression et d'une grande servitude; Il habite au milieu des nations, Et il n'y trouve point de repos; Tous ses persécuteurs l'ont surpris dans l'angoisse."],[1,4,"Les chemins de Sion sont dans le deuil, car on ne va plus aux fêtes; Toutes ses portes sont désertes, Ses sacrificateurs gémissent, Ses vierges sont affligées, et elle est remplie d'amertume.","Les chemins de Sion sont dans le deuil, car on ne va plus aux fêtes; Toutes ses portes sont désertes, Ses sacrificateurs gémissent, Ses vierges sont affligées, et elle est remplie d'amertume."],[1,5,"Ses oppresseurs triomphent, ses ennemis sont en paix; Car l'Éternel l'a humiliée, À cause de la multitude de ses péchés; Ses enfants ont marché captifs devant l'oppresseur.","Ses oppresseurs triomphent, ses ennemis sont en paix; Car l'Éternel l'a humiliée, À cause de la multitude de ses péchés; Ses enfants ont marché captifs devant l'oppresseur."],[1,6,"La fille de Sion a perdu toute sa gloire; Ses chefs sont comme des cerfs Qui ne trouvent point de pâture, Et qui fuient sans force devant celui qui les chasse.","La fille de Sion a perdu toute sa gloire; Ses chefs sont comme des cerfs Qui ne trouvent point de pâture, Et qui fuient sans force devant celui qui les chasse."],[1,7,"Aux jours de sa détresse et de sa misère, Jérusalem s'est souvenue De tous les biens dès longtemps son partage, Quand son peuple est tombé sans secours sous la main de l'oppresseur; Ses ennemis l'ont vue, et ils ont ri de sa chute.","Aux jours de sa détresse et de sa misère, Jérusalem s'est souvenue De tous les biens dès longtemps son partage, Quand son peuple est tombé sans secours sous la main de l'oppresseur; Ses ennemis l'ont vue, et ils ont ri de sa chute."],[1,8,"Jérusalem a multiplié ses péchés, C'est pourquoi elle est un objet d'aversion; Tous ceux qui l'honoraient la méprisent, en voyant sa nudité; Elle-même soupire, et détourne la face.","Jérusalem a multiplié ses péchés, C'est pourquoi elle est un objet d'aversion; Tous ceux qui l'honoraient la méprisent, en voyant sa nudité; Elle-même soupire, et détourne la face."],[1,9,"La souillure était dans les pans de sa robe, et elle ne songeait pas à sa fin; Elle est tombée d'une manière étonnante, et nul ne la console. -Vois ma misère, ô Éternel! Quelle arrogance chez l'ennemi! -","La souillure était dans les pans de sa robe, et elle ne songeait pas à sa fin; Elle est tombée d'une manière étonnante, et nul ne la console. -Vois ma misère, ô Éternel! Quelle arrogance chez l'ennemi! -"],[1,10,"L'oppresseur a étendu la main Sur tout ce qu'elle avait de précieux; Elle a vu pénétrer dans son sanctuaire les nations Auxquelles tu avais défendu d'entrer dans ton assemblée.","L'oppresseur a étendu la main Sur tout ce qu'elle avait de précieux; Elle a vu pénétrer dans son sanctuaire les nations Auxquelles tu avais défendu d'entrer dans ton assemblée."],[1,11,"Tout son peuple soupire, il cherche du pain; Ils ont donné leurs choses précieuses pour de la nourriture, Afin de ranimer leur vie. -Vois, Éternel, regarde comme je suis avilie!","Tout son peuple soupire, il cherche du pain; Ils ont donné leurs choses précieuses pour de la nourriture, Afin de ranimer leur vie. -Vois, Éternel, regarde comme je suis avilie!"],[1,12,"Je m'adresse à vous, à vous tous qui passez ici! Regardez et voyez s'il est une douleur pareille à ma douleur, À celle dont j'ai été frappée! L'Éternel m'a affligée au jour de son ardente colère.","Je m'adresse à vous, à vous tous qui passez ici! Regardez et voyez s'il est une douleur pareille à ma douleur, À celle dont j'ai été frappée! L'Éternel m'a affligée au jour de son ardente colère."],[1,13,"D'en haut il a lancé dans mes os un feu qui les dévore; Il a tendu un filet sous mes pieds, Il m'a fait tomber en arrière; Il m'a jetée dans la désolation, dans une langueur de tous les jours.","D'en haut il a lancé dans mes os un feu qui les dévore; Il a tendu un filet sous mes pieds, Il m'a fait tomber en arrière; Il m'a jetée dans la désolation, dans une langueur de tous les jours."],[1,14,"Sa main a lié le joug de mes iniquités; Elles se sont entrelacées, appliquées sur mon cou; Il a brisé ma force; Le Seigneur m'a livrée à des mains auxquelles je ne puis résister.","Sa main a lié le joug de mes iniquités; Elles se sont entrelacées, appliquées sur mon cou; Il a brisé ma force; Le Seigneur m'a livrée à des mains auxquelles je ne puis résister."],[1,15,"Le Seigneur a terrassé tous mes guerriers au milieu de moi; Il a rassemblé contre moi une armée, Pour détruire mes jeunes hommes; Le Seigneur a foulé au pressoir la vierge, fille de Juda.","Le Seigneur a terrassé tous mes guerriers au milieu de moi; Il a rassemblé contre moi une armée, Pour détruire mes jeunes hommes; Le Seigneur a foulé au pressoir la vierge, fille de Juda."],[1,16,"C'est pour cela que je pleure, que mes yeux fondent en larmes; Car il s'est éloigné de moi, celui qui me consolerait, Qui ranimerait ma vie. Mes fils sont dans la désolation, parce que l'ennemi a triomphé. -","C'est pour cela que je pleure, que mes yeux fondent en larmes; Car il s'est éloigné de moi, celui qui me consolerait, Qui ranimerait ma vie. Mes fils sont dans la désolation, parce que l'ennemi a triomphé. -"],[1,17,"Sion a étendu les mains, Et personne ne l'a consolée; L'Éternel a envoyé contre Jacob les ennemis d'alentour; Jérusalem a été un objet d'horreur au milieu d'eux. -","Sion a étendu les mains, Et personne ne l'a consolée; L'Éternel a envoyé contre Jacob les ennemis d'alentour; Jérusalem a été un objet d'horreur au milieu d'eux. -"],[1,18,"L'Éternel est juste, Car j'ai été rebelle à ses ordres. Écoutez, vous tous, peuples, et voyez ma douleur! Mes vierges et mes jeunes hommes sont allés en captivité.","L'Éternel est juste, Car j'ai été rebelle à ses ordres. Écoutez, vous tous, peuples, et voyez ma douleur! Mes vierges et mes jeunes hommes sont allés en captivité."],[1,19,"J'ai appelé mes amis, et ils m'ont trompée. Mes sacrificateurs et mes anciens ont expiré dans la ville: Ils cherchaient de la nourriture, Afin de ranimer leur vie.","J'ai appelé mes amis, et ils m'ont trompée. Mes sacrificateurs et mes anciens ont expiré dans la ville: Ils cherchaient de la nourriture, Afin de ranimer leur vie."],[1,20,"Éternel, regarde ma détresse! Mes entrailles bouillonnent, Mon coeur est bouleversé au dedans de moi, Car j'ai été rebelle. Au dehors l'épée a fait ses ravages, au dedans la mort.","Éternel, regarde ma détresse! Mes entrailles bouillonnent, Mon coeur est bouleversé au dedans de moi, Car j'ai été rebelle. Au dehors l'épée a fait ses ravages, au dedans la mort."],[1,21,"On a entendu mes soupirs, et personne ne m'a consolée; Tous mes ennemis ont appris mon malheur, Ils se sont réjouis de ce que tu l'as causé; Tu amèneras, tu publieras le jour où ils seront comme moi.","On a entendu mes soupirs, et personne ne m'a consolée; Tous mes ennemis ont appris mon malheur, Ils se sont réjouis de ce que tu l'as causé; Tu amèneras, tu publieras le jour où ils seront comme moi."],[1,22,"Que toute leur méchanceté vienne devant toi, Et traite-les comme tu m'as traitée, À cause de toutes mes transgressions! Car mes soupirs sont nombreux, et mon coeur est souffrant.","Que toute leur méchanceté vienne devant toi, Et traite-les comme tu m'as traitée, À cause de toutes mes transgressions! Car mes soupirs sont nombreux, et mon coeur est souffrant."],[2,1,"Eh quoi! le Seigneur, dans sa colère, a couvert de nuages la fille de Sion! Il a précipité du ciel sur la terre la magnificence d'Israël! Il ne s'est pas souvenu de son marchepied, Au jour de sa colère!","Eh quoi! le Seigneur, dans sa colère, a couvert de nuages la fille de Sion! Il a précipité du ciel sur la terre la magnificence d'Israël! Il ne s'est pas souvenu de son marchepied, Au jour de sa colère!"],[2,2,"Le Seigneur a détruit sans pitié toutes les demeures de Jacob; Il a, dans sa fureur, renversé les forteresses de la fille de Juda, Il les a fait rouler à terre; Il a profané le royaume et ses chefs.","Le Seigneur a détruit sans pitié toutes les demeures de Jacob; Il a, dans sa fureur, renversé les forteresses de la fille de Juda, Il les a fait rouler à terre; Il a profané le royaume et ses chefs."],[2,3,"Il a, dans son ardente colère, abattu toute la force d'Israël; Il a retiré sa droite en présence de l'ennemi; Il a allumé dans Jacob des flammes de feu, Qui dévorent de tous côtés.","Il a, dans son ardente colère, abattu toute la force d'Israël; Il a retiré sa droite en présence de l'ennemi; Il a allumé dans Jacob des flammes de feu, Qui dévorent de tous côtés."],[2,4,"Il a tendu son arc comme un ennemi; Sa droite s'est dressée comme celle d'un assaillant; Il a fait périr tout ce qui plaisait aux regards; Il a répandu sa fureur comme un feu sur la tente de la fille de Sion.","Il a tendu son arc comme un ennemi; Sa droite s'est dressée comme celle d'un assaillant; Il a fait périr tout ce qui plaisait aux regards; Il a répandu sa fureur comme un feu sur la tente de la fille de Sion."],[2,5,"Le Seigneur a été comme un ennemi; Il a dévoré Israël, il a dévoré tous ses palais, Il a détruit ses forteresses; Il a rempli la fille de Juda de plaintes et de gémissements.","Le Seigneur a été comme un ennemi; Il a dévoré Israël, il a dévoré tous ses palais, Il a détruit ses forteresses; Il a rempli la fille de Juda de plaintes et de gémissements."],[2,6,"Il a dévasté sa tente comme un jardin, Il a détruit le lieu de son assemblée; L'Éternel a fait oublier en Sion les fêtes et le sabbat, Et, dans sa violente colère, il a rejeté le roi et le sacrificateur.","Il a dévasté sa tente comme un jardin, Il a détruit le lieu de son assemblée; L'Éternel a fait oublier en Sion les fêtes et le sabbat, Et, dans sa violente colère, il a rejeté le roi et le sacrificateur."],[2,7,"Le Seigneur a dédaigné son autel, repoussé son sanctuaire; Il a livré entre les mains de l'ennemi les murs des palais de Sion; Les cris ont retenti dans la maison de l'Éternel, Comme en un jour de fête.","Le Seigneur a dédaigné son autel, repoussé son sanctuaire; Il a livré entre les mains de l'ennemi les murs des palais de Sion; Les cris ont retenti dans la maison de l'Éternel, Comme en un jour de fête."],[2,8,"L'Éternel avait résolu de détruire les murs de la fille de Sion; Il a tendu le cordeau, il n'a pas retiré sa main sans les avoir anéantis; Il a plongé dans le deuil rempart et murailles, Qui n'offrent plus ensemble qu'une triste ruine.","L'Éternel avait résolu de détruire les murs de la fille de Sion; Il a tendu le cordeau, il n'a pas retiré sa main sans les avoir anéantis; Il a plongé dans le deuil rempart et murailles, Qui n'offrent plus ensemble qu'une triste ruine."],[2,9,"Ses portes sont enfoncées dans la terre; Il en a détruit, rompu les barres. Son roi et ses chefs sont parmi les nations; il n'y a plus de loi. Même les prophètes ne reçoivent aucune vision de l'Éternel.","Ses portes sont enfoncées dans la terre; Il en a détruit, rompu les barres. Son roi et ses chefs sont parmi les nations; il n'y a plus de loi. Même les prophètes ne reçoivent aucune vision de l'Éternel."],[2,10,"Les anciens de la fille de Sion sont assis à terre, ils sont muets; Ils ont couvert leur tête de poussière, Ils se sont revêtus de sacs; Les vierges de Jérusalem laissent retomber leur tête vers la terre.","Les anciens de la fille de Sion sont assis à terre, ils sont muets; Ils ont couvert leur tête de poussière, Ils se sont revêtus de sacs; Les vierges de Jérusalem laissent retomber leur tête vers la terre."],[2,11,"Mes yeux se consument dans les larmes, mes entrailles bouillonnent, Ma bile se répand sur la terre, À cause du désastre de la fille de mon peuple, Des enfants et des nourrissons en défaillance dans les rues de la ville.","Mes yeux se consument dans les larmes, mes entrailles bouillonnent, Ma bile se répand sur la terre, À cause du désastre de la fille de mon peuple, Des enfants et des nourrissons en défaillance dans les rues de la ville."],[2,12,"Ils disaient à leurs mères: Où y a-t-il du blé et du vin? Et ils tombaient comme des blessés dans les rues de la ville, Ils rendaient l'âme sur le sein de leurs mères.","Ils disaient à leurs mères: Où y a-t-il du blé et du vin? Et ils tombaient comme des blessés dans les rues de la ville, Ils rendaient l'âme sur le sein de leurs mères."],[2,13,"Que dois-je te dire? à quoi te comparer, fille de Jérusalem? Qui trouver de semblable à toi, et quelle consolation te donner, Vierge, fille de Sion? Car ta plaie est grande comme la mer: qui pourra te guérir?","Que dois-je te dire? à quoi te comparer, fille de Jérusalem? Qui trouver de semblable à toi, et quelle consolation te donner, Vierge, fille de Sion? Car ta plaie est grande comme la mer: qui pourra te guérir?"],[2,14,"Tes prophètes ont eu pour toi des visions vaines et fausses; Ils n'ont pas mis à nu ton iniquité, Afin de détourner de toi la captivité; Ils t'ont donné des oracles mensongers et trompeurs.","Tes prophètes ont eu pour toi des visions vaines et fausses; Ils n'ont pas mis à nu ton iniquité, Afin de détourner de toi la captivité; Ils t'ont donné des oracles mensongers et trompeurs."],[2,15,"Tous les passants battent des mains sur toi, Ils sifflent, ils secouent la tête contre la fille de Jérusalem: Est-ce là cette ville qu'on appelait une beauté parfaite, La joie de toute la terre?","Tous les passants battent des mains sur toi, Ils sifflent, ils secouent la tête contre la fille de Jérusalem: Est-ce là cette ville qu'on appelait une beauté parfaite, La joie de toute la terre?"],[2,16,"Tous tes ennemis ouvrent la bouche contre toi, Ils sifflent, ils grincent des dents, Ils disent: Nous l'avons engloutie! C'est bien le jour que nous attendions, nous l'avons atteint, nous le voyons!","Tous tes ennemis ouvrent la bouche contre toi, Ils sifflent, ils grincent des dents, Ils disent: Nous l'avons engloutie! C'est bien le jour que nous attendions, nous l'avons atteint, nous le voyons!"],[2,17,"L'Éternel a exécuté ce qu'il avait résolu, Il a accompli la parole qu'il avait dès longtemps arrêtée, Il a détruit sans pitié; Il a fait de toi la joie de l'ennemi, Il a relevé la force de tes oppresseurs.","L'Éternel a exécuté ce qu'il avait résolu, Il a accompli la parole qu'il avait dès longtemps arrêtée, Il a détruit sans pitié; Il a fait de toi la joie de l'ennemi, Il a relevé la force de tes oppresseurs."],[2,18,"Leur coeur crie vers le Seigneur... Mur de la fille de Sion, répands jour et nuit des torrents de larmes! Ne te donne aucun relâche, Et que ton oeil n'ait point de repos!","Leur coeur crie vers le Seigneur... Mur de la fille de Sion, répands jour et nuit des torrents de larmes! Ne te donne aucun relâche, Et que ton oeil n'ait point de repos!"],[2,19,"Lève-toi, pousse des gémissements à l'entrée des veilles de la nuit! Répands ton coeur comme de l'eau, en présence du Seigneur! Lève tes mains vers lui pour la vie de tes enfants Qui meurent de faim aux coins de toutes les rues!","Lève-toi, pousse des gémissements à l'entrée des veilles de la nuit! Répands ton coeur comme de l'eau, en présence du Seigneur! Lève tes mains vers lui pour la vie de tes enfants Qui meurent de faim aux coins de toutes les rues!"],[2,20,"Vois, Éternel, regarde qui tu as ainsi traité! Fallait-il que des femmes dévorassent le fruit de leurs entrailles, Les petits enfants objets de leur tendresse? Que sacrificateurs et prophètes fussent massacrés dans le sanctuaire du Seigneur?","Vois, Éternel, regarde qui tu as ainsi traité! Fallait-il que des femmes dévorassent le fruit de leurs entrailles, Les petits enfants objets de leur tendresse? Que sacrificateurs et prophètes fussent massacrés dans le sanctuaire du Seigneur?"],[2,21,"Les enfants et les vieillards sont couchés par terre dans les rues; Mes vierges et mes jeunes hommes sont tombés par l'épée; Tu as tué, au jour de ta colère, Tu as égorgé sans pitié.","Les enfants et les vieillards sont couchés par terre dans les rues; Mes vierges et mes jeunes hommes sont tombés par l'épée; Tu as tué, au jour de ta colère, Tu as égorgé sans pitié."],[2,22,"Tu as appelé de toutes parts sur moi l'épouvante, comme à un jour de fête. Au jour de la colère de l'Éternel, il n'y a eu ni réchappé ni survivant. Ceux que j'avais soignés et élevés, Mon ennemi les a consumés.","Tu as appelé de toutes parts sur moi l'épouvante, comme à un jour de fête. Au jour de la colère de l'Éternel, il n'y a eu ni réchappé ni survivant. Ceux que j'avais soignés et élevés, Mon ennemi les a consumés."],[3,1,"Je suis l'homme qui a vu la misère Sous la verge de sa fureur.","Je suis l'homme qui a vu la misère Sous la verge de sa fureur."],[3,2,"Il m'a conduit, mené dans les ténèbres, Et non dans la lumière.","Il m'a conduit, mené dans les ténèbres, Et non dans la lumière."],[3,3,"Contre moi il tourne et retourne sa main Tout le jour.","Contre moi il tourne et retourne sa main Tout le jour."],[3,4,"Il a fait dépérir ma chair et ma peau, Il a brisé mes os.","Il a fait dépérir ma chair et ma peau, Il a brisé mes os."],[3,5,"Il a bâti autour de moi, Il m'a environné de poison et de douleur.","Il a bâti autour de moi, Il m'a environné de poison et de douleur."],[3,6,"Il me fait habiter dans les ténèbres, Comme ceux qui sont morts dès longtemps.","Il me fait habiter dans les ténèbres, Comme ceux qui sont morts dès longtemps."],[3,7,"Il m'a entouré d'un mur, pour que je ne sorte pas; Il m'a donné de pesantes chaînes.","Il m'a entouré d'un mur, pour que je ne sorte pas; Il m'a donné de pesantes chaînes."],[3,8,"J'ai beau crier et implorer du secours, Il ne laisse pas accès à ma prière.","J'ai beau crier et implorer du secours, Il ne laisse pas accès à ma prière."],[3,9,"Il a fermé mon chemin avec des pierres de taille, Il a détruit mes sentiers.","Il a fermé mon chemin avec des pierres de taille, Il a détruit mes sentiers."],[3,10,"Il a été pour moi un ours en embuscade, Un lion dans un lieu caché.","Il a été pour moi un ours en embuscade, Un lion dans un lieu caché."],[3,11,"Il a détourné mes voies, il m'a déchiré, Il m'a jeté dans la désolation.","Il a détourné mes voies, il m'a déchiré, Il m'a jeté dans la désolation."],[3,12,"Il a tendu son arc, et il m'a placé Comme un but pour sa flèche.","Il a tendu son arc, et il m'a placé Comme un but pour sa flèche."],[3,13,"Il a fait entrer dans mes reins Les traits de son carquois.","Il a fait entrer dans mes reins Les traits de son carquois."],[3,14,"Je suis pour tout mon peuple un objet de raillerie, Chaque jour l'objet de leurs chansons.","Je suis pour tout mon peuple un objet de raillerie, Chaque jour l'objet de leurs chansons."],[3,15,"Il m'a rassasié d'amertume, Il m'a enivré d'absinthe.","Il m'a rassasié d'amertume, Il m'a enivré d'absinthe."],[3,16,"Il a brisé mes dents avec des cailloux, Il m'a couvert de cendre.","Il a brisé mes dents avec des cailloux, Il m'a couvert de cendre."],[3,17,"Tu m'as enlevé la paix; Je ne connais plus le bonheur.","Tu m'as enlevé la paix; Je ne connais plus le bonheur."],[3,18,"Et j'ai dit: Ma force est perdue, Je n'ai plus d'espérance en l'Éternel!","Et j'ai dit: Ma force est perdue, Je n'ai plus d'espérance en l'Éternel!"],[3,19,"Quand je pense à ma détresse et à ma misère, À l'absinthe et au poison;","Quand je pense à ma détresse et à ma misère, À l'absinthe et au poison;"],[3,20,"Quand mon âme s'en souvient, Elle est abattue au dedans de moi.","Quand mon âme s'en souvient, Elle est abattue au dedans de moi."],[3,21,"Voici ce que je veux repasser en mon coeur, Ce qui me donnera de l'espérance.","Voici ce que je veux repasser en mon coeur, Ce qui me donnera de l'espérance."],[3,22,"Les bontés de l'Éternel ne sont pas épuisées, Ses compassions ne sont pas à leur terme;","Les bontés de l'Éternel ne sont pas épuisées, Ses compassions ne sont pas à leur terme;"],[3,23,"Elles se renouvellent chaque matin. Oh! que ta fidélité est grande!","Elles se renouvellent chaque matin. Oh! que ta fidélité est grande!"],[3,24,"L'Éternel est mon partage, dit mon âme; C'est pourquoi je veux espérer en lui.","L'Éternel est mon partage, dit mon âme; C'est pourquoi je veux espérer en lui."],[3,25,"L'Éternel a de la bonté pour qui espère en lui, Pour l'âme qui le cherche.","L'Éternel a de la bonté pour qui espère en lui, Pour l'âme qui le cherche."],[3,26,"Il est bon d'attendre en silence Le secours de l'Éternel.","Il est bon d'attendre en silence Le secours de l'Éternel."],[3,27,"Il est bon pour l'homme De porter le joug dans sa jeunesse.","Il est bon pour l'homme De porter le joug dans sa jeunesse."],[3,28,"Il se tiendra solitaire et silencieux, Parce que l'Éternel le lui impose;","Il se tiendra solitaire et silencieux, Parce que l'Éternel le lui impose;"],[3,29,"Il mettra sa bouche dans la poussière, Sans perdre toute espérance;","Il mettra sa bouche dans la poussière, Sans perdre toute espérance;"],[3,30,"Il présentera la joue à celui qui le frappe, Il se rassasiera d'opprobres.","Il présentera la joue à celui qui le frappe, Il se rassasiera d'opprobres."],[3,31,"Car le Seigneur Ne rejette pas à toujours.","Car le Seigneur Ne rejette pas à toujours."],[3,32,"Mais, lorsqu'il afflige, Il a compassion selon sa grande miséricorde;","Mais, lorsqu'il afflige, Il a compassion selon sa grande miséricorde;"],[3,33,"Car ce n'est pas volontiers qu'il humilie Et qu'il afflige les enfants des hommes.","Car ce n'est pas volontiers qu'il humilie Et qu'il afflige les enfants des hommes."],[3,34,"Quand on foule aux pieds Tous les captifs du pays,","Quand on foule aux pieds Tous les captifs du pays,"],[3,35,"Quand on viole la justice humaine À la face du Très-Haut,","Quand on viole la justice humaine À la face du Très-Haut,"],[3,36,"Quand on fait tort à autrui dans sa cause, Le Seigneur ne le voit-il pas?","Quand on fait tort à autrui dans sa cause, Le Seigneur ne le voit-il pas?"],[3,37,"Qui dira qu'une chose arrive, Sans que le Seigneur l'ait ordonnée?","Qui dira qu'une chose arrive, Sans que le Seigneur l'ait ordonnée?"],[3,38,"N'est-ce pas de la volonté du Très-Haut que viennent Les maux et les biens?","N'est-ce pas de la volonté du Très-Haut que viennent Les maux et les biens?"],[3,39,"Pourquoi l'homme vivant se plaindrait-il? Que chacun se plaigne de ses propres péchés.","Pourquoi l'homme vivant se plaindrait-il? Que chacun se plaigne de ses propres péchés."],[3,40,"Recherchons nos voies et sondons, Et retournons à l'Éternel;","Recherchons nos voies et sondons, Et retournons à l'Éternel;"],[3,41,"Élevons nos coeurs et nos mains Vers Dieu qui est au ciel:","Élevons nos coeurs et nos mains Vers Dieu qui est au ciel:"],[3,42,"Nous avons péché, nous avons été rebelles! Tu n'as point pardonné!","Nous avons péché, nous avons été rebelles! Tu n'as point pardonné!"],[3,43,"Tu t'es caché dans ta colère, et tu nous as poursuivis; Tu as tué sans miséricorde;","Tu t'es caché dans ta colère, et tu nous as poursuivis; Tu as tué sans miséricorde;"],[3,44,"Tu t'es enveloppé d'un nuage, Pour fermer accès à la prière.","Tu t'es enveloppé d'un nuage, Pour fermer accès à la prière."],[3,45,"Tu nous as rendus un objet de mépris et de dédain Au milieu des peuples.","Tu nous as rendus un objet de mépris et de dédain Au milieu des peuples."],[3,46,"Ils ouvrent la bouche contre nous, Tous ceux qui sont nos ennemis.","Ils ouvrent la bouche contre nous, Tous ceux qui sont nos ennemis."],[3,47,"Notre partage a été la terreur et la fosse, Le ravage et la ruine.","Notre partage a été la terreur et la fosse, Le ravage et la ruine."],[3,48,"Des torrents d'eau coulent de mes yeux, À cause de la ruine de la fille de mon peuple.","Des torrents d'eau coulent de mes yeux, À cause de la ruine de la fille de mon peuple."],[3,49,"Mon oeil fond en larmes, sans repos, Sans relâche,","Mon oeil fond en larmes, sans repos, Sans relâche,"],[3,50,"Jusqu'à ce que l'Éternel regarde et voie Du haut des cieux;","Jusqu'à ce que l'Éternel regarde et voie Du haut des cieux;"],[3,51,"Mon oeil me fait souffrir, À cause de toutes les filles de ma ville.","Mon oeil me fait souffrir, À cause de toutes les filles de ma ville."],[3,52,"Ils m'ont donné la chasse comme à un oiseau, Ceux qui sont à tort mes ennemis.","Ils m'ont donné la chasse comme à un oiseau, Ceux qui sont à tort mes ennemis."],[3,53,"Ils ont voulu anéantir ma vie dans une fosse, Et ils ont jeté des pierres sur moi.","Ils ont voulu anéantir ma vie dans une fosse, Et ils ont jeté des pierres sur moi."],[3,54,"Les eaux ont inondé ma tête; Je disais: Je suis perdu!","Les eaux ont inondé ma tête; Je disais: Je suis perdu!"],[3,55,"J'ai invoqué ton nom, ô Éternel, Du fond de la fosse.","J'ai invoqué ton nom, ô Éternel, Du fond de la fosse."],[3,56,"Tu as entendu ma voix: Ne ferme pas l'oreille à mes soupirs, à mes cris!","Tu as entendu ma voix: Ne ferme pas l'oreille à mes soupirs, à mes cris!"],[3,57,"Au jour où je t'ai invoqué, tu t'es approché, Tu as dit: Ne crains pas!","Au jour où je t'ai invoqué, tu t'es approché, Tu as dit: Ne crains pas!"],[3,58,"Seigneur, tu as défendu la cause de mon âme, Tu as racheté ma vie.","Seigneur, tu as défendu la cause de mon âme, Tu as racheté ma vie."],[3,59,"Éternel, tu as vu ce qu'on m'a fait souffrir: Rends-moi justice!","Éternel, tu as vu ce qu'on m'a fait souffrir: Rends-moi justice!"],[3,60,"Tu as vu toutes leurs vengeances, Tous leurs complots contre moi.","Tu as vu toutes leurs vengeances, Tous leurs complots contre moi."],[3,61,"Éternel, tu as entendu leurs outrages, Tous leurs complots contre moi,","Éternel, tu as entendu leurs outrages, Tous leurs complots contre moi,"],[3,62,"Les discours de mes adversaires, et les projets Qu'ils formaient chaque jour contre moi.","Les discours de mes adversaires, et les projets Qu'ils formaient chaque jour contre moi."],[3,63,"Regarde quand ils sont assis et quand ils se lèvent: Je suis l'objet de leurs chansons.","Regarde quand ils sont assis et quand ils se lèvent: Je suis l'objet de leurs chansons."],[3,64,"Tu leur donneras un salaire, ô Éternel, Selon l'oeuvre de leurs mains;","Tu leur donneras un salaire, ô Éternel, Selon l'oeuvre de leurs mains;"],[3,65,"Tu les livreras à l'endurcissement de leur coeur, À ta malédiction contre eux;","Tu les livreras à l'endurcissement de leur coeur, À ta malédiction contre eux;"],[3,66,"Tu les poursuivras dans ta colère, et tu les extermineras De dessous les cieux, ô Éternel!","Tu les poursuivras dans ta colère, et tu les extermineras De dessous les cieux, ô Éternel!"],[4,1,"Eh quoi! l'or a perdu son éclat! L'or pur est altéré! Les pierres du sanctuaire sont dispersées Aux coins de toutes les rues!","Eh quoi! l'or a perdu son éclat! L'or pur est altéré! Les pierres du sanctuaire sont dispersées Aux coins de toutes les rues!"],[4,2,"Les nobles fils de Sion, Estimés à l'égal de l'or pur, Sont regardés, hélas! comme des vases de terre, Ouvrage des mains du potier!","Les nobles fils de Sion, Estimés à l'égal de l'or pur, Sont regardés, hélas! comme des vases de terre, Ouvrage des mains du potier!"],[4,3,"Les chacals mêmes présentent la mamelle, Et allaitent leurs petits; Mais la fille de mon peuple est devenue cruelle Comme les autruches du désert.","Les chacals mêmes présentent la mamelle, Et allaitent leurs petits; Mais la fille de mon peuple est devenue cruelle Comme les autruches du désert."],[4,4,"La langue du nourrisson s'attache à son palais, Desséchée par la soif; Les enfants demandent du pain, Et personne ne leur en donne.","La langue du nourrisson s'attache à son palais, Desséchée par la soif; Les enfants demandent du pain, Et personne ne leur en donne."],[4,5,"Ceux qui se nourrissaient de mets délicats Périssent dans les rues; Ceux qui étaient élevés dans la pourpre Embrassent les fumiers.","Ceux qui se nourrissaient de mets délicats Périssent dans les rues; Ceux qui étaient élevés dans la pourpre Embrassent les fumiers."],[4,6,"Le châtiment de la fille de mon peuple est plus grand Que celui de Sodome, Détruite en un instant, Sans que personne ait porté la main sur elle.","Le châtiment de la fille de mon peuple est plus grand Que celui de Sodome, Détruite en un instant, Sans que personne ait porté la main sur elle."],[4,7,"Ses princes étaient plus éclatants que la neige, Plus blancs que le lait; Ils avaient le teint plus vermeil que le corail; Leur figure était comme le saphir.","Ses princes étaient plus éclatants que la neige, Plus blancs que le lait; Ils avaient le teint plus vermeil que le corail; Leur figure était comme le saphir."],[4,8,"Leur aspect est plus sombre que le noir; On ne les reconnaît pas dans les rues; Ils ont la peau collée sur les os, Sèche comme du bois.","Leur aspect est plus sombre que le noir; On ne les reconnaît pas dans les rues; Ils ont la peau collée sur les os, Sèche comme du bois."],[4,9,"Ceux qui périssent par l'épée sont plus heureux Que ceux qui périssent par la faim, Qui tombent exténués, Privés du fruit des champs.","Ceux qui périssent par l'épée sont plus heureux Que ceux qui périssent par la faim, Qui tombent exténués, Privés du fruit des champs."],[4,10,"Les femmes, malgré leur tendresse, Font cuire leurs enfants; Ils leur servent de nourriture, Au milieu du désastre de la fille de mon peuple.","Les femmes, malgré leur tendresse, Font cuire leurs enfants; Ils leur servent de nourriture, Au milieu du désastre de la fille de mon peuple."],[4,11,"L'Éternel a épuisé sa fureur, Il a répandu son ardente colère; Il a allumé dans Sion un feu Qui en dévore les fondements.","L'Éternel a épuisé sa fureur, Il a répandu son ardente colère; Il a allumé dans Sion un feu Qui en dévore les fondements."],[4,12,"Les rois de la terre n'auraient pas cru, Aucun des habitants du monde n'aurait cru Que l'adversaire, que l'ennemi entrerait Dans les portes de Jérusalem.","Les rois de la terre n'auraient pas cru, Aucun des habitants du monde n'aurait cru Que l'adversaire, que l'ennemi entrerait Dans les portes de Jérusalem."],[4,13,"Voilà le fruit des péchés de ses prophètes, Des iniquités de ses sacrificateurs, Qui ont répandu dans son sein Le sang des justes!","Voilà le fruit des péchés de ses prophètes, Des iniquités de ses sacrificateurs, Qui ont répandu dans son sein Le sang des justes!"],[4,14,"Ils erraient en aveugles dans les rues, Souillés de sang; On ne pouvait Toucher leurs vêtements.","Ils erraient en aveugles dans les rues, Souillés de sang; On ne pouvait Toucher leurs vêtements."],[4,15,"Éloignez-vous, impurs! leur criait-on, Éloignez-vous, éloignez-vous, ne nous touchez pas! Ils sont en fuite, ils errent çà et là; On dit parmi les nations: Ils n'auront plus leur demeure!","Éloignez-vous, impurs! leur criait-on, Éloignez-vous, éloignez-vous, ne nous touchez pas! Ils sont en fuite, ils errent çà et là; On dit parmi les nations: Ils n'auront plus leur demeure!"],[4,16,"L'Éternel les a dispersés dans sa colère, Il ne tourne plus les regards vers eux; On n'a eu ni respect pour les sacrificateurs, Ni pitié pour les vieillards.","L'Éternel les a dispersés dans sa colère, Il ne tourne plus les regards vers eux; On n'a eu ni respect pour les sacrificateurs, Ni pitié pour les vieillards."],[4,17,"Nos yeux se consumaient encore, Et nous attendions vainement du secours; Nos regards se portaient avec espérance Vers une nation qui ne nous a pas délivrés.","Nos yeux se consumaient encore, Et nous attendions vainement du secours; Nos regards se portaient avec espérance Vers une nation qui ne nous a pas délivrés."],[4,18,"On épiait nos pas, Pour nous empêcher d'aller sur nos places; Notre fin s'approchait, nos jours étaient accomplis... Notre fin est arrivée!","On épiait nos pas, Pour nous empêcher d'aller sur nos places; Notre fin s'approchait, nos jours étaient accomplis... Notre fin est arrivée!"],[4,19,"Nos persécuteurs étaient plus légers Que les aigles du ciel; Ils nous ont poursuivis sur les montagnes, Ils nous ont dressé des embûches dans le désert.","Nos persécuteurs étaient plus légers Que les aigles du ciel; Ils nous ont poursuivis sur les montagnes, Ils nous ont dressé des embûches dans le désert."],[4,20,"Celui qui nous faisait respirer, l'oint de l'Éternel, À été pris dans leurs fosses, Lui de qui nous disions: Nous vivrons sous son ombre parmi les nations.","Celui qui nous faisait respirer, l'oint de l'Éternel, À été pris dans leurs fosses, Lui de qui nous disions: Nous vivrons sous son ombre parmi les nations."],[4,21,"Réjouis-toi, tressaille d'allégresse, fille d'Édom, Habitante du pays d'Uts! Vers toi aussi passera la coupe; Tu t'enivreras, et tu seras mise à nu.","Réjouis-toi, tressaille d'allégresse, fille d'Édom, Habitante du pays d'Uts! Vers toi aussi passera la coupe; Tu t'enivreras, et tu seras mise à nu."],[4,22,"Fille de Sion, ton iniquité est expiée; Il ne t'enverra plus en captivité. Fille d'Édom, il châtiera ton iniquité, Il mettra tes péchés à découvert.","Fille de Sion, ton iniquité est expiée; Il ne t'enverra plus en captivité. Fille d'Édom, il châtiera ton iniquité, Il mettra tes péchés à découvert."],[5,1,"Souviens-toi, Éternel, de ce qui nous est arrivé! Regarde, vois notre opprobre!","Souviens-toi, Éternel, de ce qui nous est arrivé! Regarde, vois notre opprobre!"],[5,2,"Notre héritage a passé à des étrangers, Nos maisons à des inconnus.","Notre héritage a passé à des étrangers, Nos maisons à des inconnus."],[5,3,"Nous sommes orphelins, sans père; Nos mères sont comme des veuves.","Nous sommes orphelins, sans père; Nos mères sont comme des veuves."],[5,4,"Nous buvons notre eau à prix d'argent, Nous payons notre bois.","Nous buvons notre eau à prix d'argent, Nous payons notre bois."],[5,5,"Nous sommes poursuivis, le joug sur le cou; Nous sommes épuisés, nous n'avons point de repos.","Nous sommes poursuivis, le joug sur le cou; Nous sommes épuisés, nous n'avons point de repos."],[5,6,"Nous avons tendu la main vers l'Égypte, vers l'Assyrie, Pour nous rassasier de pain.","Nous avons tendu la main vers l'Égypte, vers l'Assyrie, Pour nous rassasier de pain."],[5,7,"Nos pères ont péché, ils ne sont plus, Et c'est nous qui portons la peine de leurs iniquités.","Nos pères ont péché, ils ne sont plus, Et c'est nous qui portons la peine de leurs iniquités."],[5,8,"Des esclaves dominent sur nous, Et personne ne nous délivre de leurs mains.","Des esclaves dominent sur nous, Et personne ne nous délivre de leurs mains."],[5,9,"Nous cherchons notre pain au péril de notre vie, Devant l'épée du désert.","Nous cherchons notre pain au péril de notre vie, Devant l'épée du désert."],[5,10,"Notre peau est brûlante comme un four, Par l'ardeur de la faim.","Notre peau est brûlante comme un four, Par l'ardeur de la faim."],[5,11,"Ils ont déshonoré les femmes dans Sion, Les vierges dans les villes de Juda.","Ils ont déshonoré les femmes dans Sion, Les vierges dans les villes de Juda."],[5,12,"Des chefs ont été pendus par leurs mains; La personne des vieillards n'a pas été respectée.","Des chefs ont été pendus par leurs mains; La personne des vieillards n'a pas été respectée."],[5,13,"Les jeunes hommes ont porté la meule, Les enfants chancelaient sous des fardeaux de bois.","Les jeunes hommes ont porté la meule, Les enfants chancelaient sous des fardeaux de bois."],[5,14,"Les vieillards ne vont plus à la porte, Les jeunes hommes ont cessé leurs chants.","Les vieillards ne vont plus à la porte, Les jeunes hommes ont cessé leurs chants."],[5,15,"La joie a disparu de nos coeurs, Le deuil a remplacé nos danses.","La joie a disparu de nos coeurs, Le deuil a remplacé nos danses."],[5,16,"La couronne de notre tête est tombée! Malheur à nous, parce que nous avons péché!","La couronne de notre tête est tombée! Malheur à nous, parce que nous avons péché!"],[5,17,"Si notre coeur est souffrant, Si nos yeux sont obscurcis,","Si notre coeur est souffrant, Si nos yeux sont obscurcis,"],[5,18,"C'est que la montagne de Sion est ravagée, C'est que les renards s'y promènent.","C'est que la montagne de Sion est ravagée, C'est que les renards s'y promènent."],[5,19,"Toi, l'Éternel, tu règnes à jamais; Ton trône subsiste de génération en génération.","Toi, l'Éternel, tu règnes à jamais; Ton trône subsiste de génération en génération."],[5,20,"Pourquoi nous oublierais-tu pour toujours, Nous abandonnerais-tu pour de longues années?","Pourquoi nous oublierais-tu pour toujours, Nous abandonnerais-tu pour de longues années?"],[5,21,"Fais-nous revenir vers toi, ô Éternel, et nous reviendrons! Donne-nous encore des jours comme ceux d'autrefois!","Fais-nous revenir vers toi, ô Éternel, et nous reviendrons! Donne-nous encore des jours comme ceux d'autrefois!"],[5,22,"Nous aurais-tu entièrement rejetés, Et t'irriterais-tu contre nous jusqu'à l'excès!","Nous aurais-tu entièrement rejetés, Et t'irriterais-tu contre nous jusqu'à l'excès!"]],"spa-rv1909":[[1,1,"¡CÓMOestá sentada solala ciudadpopulosa! La grandeentre las nacionesse ha vueltocomo viuda, la señorade provinciases hechatributaria.","¡CÓMOestá sentada solala ciudadpopulosa! La grandeentre las nacionesse ha vueltocomo viuda, la señorade provinciases hechatributaria."],[1,2,"Amargamentelloraen la noche, y sus lágrimasensus mejillas; no tiene quienla consuelede todossus amadores: todossus amigosle faltaron, volviéronsele enemigos.","Amargamentelloraen la noche, y sus lágrimasensus mejillas; no tiene quienla consuelede todossus amadores: todossus amigosle faltaron, volviéronsele enemigos."],[1,3,"Fuése Judá, á causa de la aflicción, y de la grandezade servidumbre; ellamoróentre las gentes, y nohallódescanso: todossusperseguidoreslaalcanzaronentreestrechuras.","Fuése Judá, á causa de la aflicción, y de la grandezade servidumbre; ellamoróentre las gentes, y nohallódescanso: todossusperseguidoreslaalcanzaronentreestrechuras."],[1,4,"Las calzadasde Sióntienen luto, porque no hayquien vengaá las solemnidades; todassuspuertasestán asoladas, sussacerdotesgimen, susvírgenesafligidas, y ellatiene amargura.","Las calzadasde Sióntienen luto, porque no hayquien vengaá las solemnidades; todassuspuertasestán asoladas, sussacerdotesgimen, susvírgenesafligidas, y ellatiene amargura."],[1,5,"Sus enemigoshan sido hechoscabeza, sus aborrecedoresfueron prosperados; porqueJehovála afligióporla multitudde sus rebeliones: sus niños fueronen cautividaddelantedel enemigo.","Sus enemigoshan sido hechoscabeza, sus aborrecedoresfueron prosperados; porqueJehovála afligióporla multitudde sus rebeliones: sus niños fueronen cautividaddelantedel enemigo."],[1,6,"Fuése dela hijadeSión todasu hermosura: sus príncipesfueroncomo ciervosque nohallanpasto, y anduvieronsin fortalezadelantedel perseguidor.","Fuése dela hijadeSión todasu hermosura: sus príncipesfueroncomo ciervosque nohallanpasto, y anduvieronsin fortalezadelantedel perseguidor."],[1,7,"Jerusalem, cuando cayósu puebloen manodel enemigoy nohubo quien le ayudase, se acordóde los díasde su aflicción, y de sus rebeliones, y de todassus cosas deseables quetuvodesde los tiemposantiguos: miráronlalos enemigos, y escarnecierondesus sábados.","Jerusalem, cuando cayósu puebloen manodel enemigoy nohubo quien le ayudase, se acordóde los díasde su aflicción, y de sus rebeliones, y de todassus cosas deseables quetuvodesde los tiemposantiguos: miráronlalos enemigos, y escarnecierondesus sábados."],[1,8,"PecadocometióJerusalem; porlo cualella ha sidoremovida: todoslos que lahonrabanlahan menospreciado, porquevieronsuvergüenza; yellasuspira, yse vuelveatrás.","PecadocometióJerusalem; porlo cualella ha sidoremovida: todoslos que lahonrabanlahan menospreciado, porquevieronsuvergüenza; yellasuspira, yse vuelveatrás."],[1,9,"Sus inmundicias en sus faldas; nose acordóde su postrimería: por tanto ella ha descendidomaravillosamente, notiene consolador. Mira, oh Jehová, mi aflicción, porqueel enemigose ha engrandecido.","Sus inmundicias en sus faldas; nose acordóde su postrimería: por tanto ella ha descendidomaravillosamente, notiene consolador. Mira, oh Jehová, mi aflicción, porqueel enemigose ha engrandecido."],[1,10,"Extendiósu manoel enemigoátodassus cosas preciosas; y ella ha vistoentraren su santuariolas gentes, de las cualesmandasteque noentrasenen tu congregación.","Extendiósu manoel enemigoátodassus cosas preciosas; y ella ha vistoentraren su santuariolas gentes, de las cualesmandasteque noentrasenen tu congregación."],[1,11,"Todosu pueblobuscósu pansuspirando; dieronpor la comidatodas sus cosas preciosas, para entretenerla vida. Mira, oh Jehová, y vequeestoyabatida.","Todosu pueblobuscósu pansuspirando; dieronpor la comidatodas sus cosas preciosas, para entretenerla vida. Mira, oh Jehová, y vequeestoyabatida."],[1,12,"¿Noos conmueve ácuantospasáispor el camino? Mirad, y vedsihaydolorcomo mi dolorqueme ha venido; porqueJehováme ha angustiadoen el díade la irade su furor.","¿Noos conmueve ácuantospasáispor el camino? Mirad, y vedsihaydolorcomo mi dolorqueme ha venido; porqueJehováme ha angustiadoen el díade la irade su furor."],[1,13,"Desde lo altoenviófuegoen mis huesos, el cual se enseñoreó: ha extendidoredá mis pies, tornómeatrás, púsomeasolada, y que siempretenga dolor.","Desde lo altoenviófuegoen mis huesos, el cual se enseñoreó: ha extendidoredá mis pies, tornómeatrás, púsomeasolada, y que siempretenga dolor."],[1,14,"El yugode mis rebelionesestá ligadopor su mano, enlazadashan subidosobremi cerviz: ha hecho caermis fuerzas: hame entregadoel Señoren sus manos, contra quienes nopodrélevantarme.","El yugode mis rebelionesestá ligadopor su mano, enlazadashan subidosobremi cerviz: ha hecho caermis fuerzas: hame entregadoel Señoren sus manos, contra quienes nopodrélevantarme."],[1,15,"El Señorha holladotodosmis fuertesen mediode mí; llamócontramí compañíapara quebrantarmis mancebos: como lagarha pisado el Señorá la virgenhijade Judá.","El Señorha holladotodosmis fuertesen mediode mí; llamócontramí compañíapara quebrantarmis mancebos: como lagarha pisado el Señorá la virgenhijade Judá."],[1,16,"Porestacausa yo lloro; misojos, misojosfluyenaguas; porquese alejódemíconsoladorque dé reposoá mialma: mishijossondestruídos, porqueel enemigoprevaleció.","Porestacausa yo lloro; misojos, misojosfluyenaguas; porquese alejódemíconsoladorque dé reposoá mialma: mishijossondestruídos, porqueel enemigoprevaleció."],[1,17,"Siónextendiósus manos, notiene quien la consuele; Jehovádió mandamientocontra Jacob, que sus enemigoslo cercasen: Jerusalemfuéen abominaciónentreellos.","Siónextendiósus manos, notiene quien la consuele; Jehovádió mandamientocontra Jacob, que sus enemigoslo cercasen: Jerusalemfuéen abominaciónentreellos."],[1,18,"Jehováes justo; que yo contrasuboca me rebelé. Oidahora, pueblostodos, y vedmi dolor: mis vírgenesy mis mancebosfueronen cautiverio.","Jehováes justo; que yo contrasuboca me rebelé. Oidahora, pueblostodos, y vedmi dolor: mis vírgenesy mis mancebosfueronen cautiverio."],[1,19,"Dí vocesá mis amadores, mas ellosme han engañado; mis sacerdotesy mis ancianosen la ciudadperecieron, buscandocomidapara sícon que entretenersuvida.","Dí vocesá mis amadores, mas ellosme han engañado; mis sacerdotesy mis ancianosen la ciudadperecieron, buscandocomidapara sícon que entretenersuvida."],[1,20,"Mira, oh Jehová, que estoy atribulada: mis entrañasrugen, mi corazónestá trastornado en medio de mí; porqueme rebelédesaforadamente: de fueradeshijó el cuchillo, de dentroparece una muerte.","Mira, oh Jehová, que estoy atribulada: mis entrañasrugen, mi corazónestá trastornado en medio de mí; porqueme rebelédesaforadamente: de fueradeshijó el cuchillo, de dentroparece una muerte."],[1,21,"Oyeronquegemía, y nohay consoladorpara mí: todosmisenemigoshan oídomimal, se han holgado de quetúlo hiciste. Harás venirel díaquehas anunciado, y seráncomo yo.","Oyeronquegemía, y nohay consoladorpara mí: todosmisenemigoshan oídomimal, se han holgado de quetúlo hiciste. Harás venirel díaquehas anunciado, y seráncomo yo."],[1,22,"Entre delantede ti todasu maldad, y hazcon ellos como hicisteconmigo portodasmis rebeliones: porquemuchosson mis suspiros, y mi corazónestá doloroso.","Entre delantede ti todasu maldad, y hazcon ellos como hicisteconmigo portodasmis rebeliones: porquemuchosson mis suspiros, y mi corazónestá doloroso."],[2,1,"¡CÓMOoscureció el Señoren su furorá la hijade Sión! Derribódel cieloá la tierrala hermosurade Israel, y nose acordódel estradode sus piesen el díade su ira.","¡CÓMOoscureció el Señoren su furorá la hijade Sión! Derribódel cieloá la tierrala hermosurade Israel, y nose acordódel estradode sus piesen el díade su ira."],[2,2,"Destruyóel Señor, y noperdonó; destruyóen su furortodaslas tiendasde Jacob: echópor tierralas fortalezasde la hijade Judá, deslustró el reinoy sus príncipes.","Destruyóel Señor, y noperdonó; destruyóen su furortodaslas tiendasde Jacob: echópor tierralas fortalezasde la hijade Judá, deslustró el reinoy sus príncipes."],[2,3,"Cortócon el furorde su iratodoel cuernode Israel; hizo volver atrássu diestradelante del enemigo; y encendióseen Jacobcomo llamade fuegoque ha devoradoen contorno.","Cortócon el furorde su iratodoel cuernode Israel; hizo volver atrássu diestradelante del enemigo; y encendióseen Jacobcomo llamade fuegoque ha devoradoen contorno."],[2,4,"Entesósu arcocomo enemigo, afirmósu mano derechacomo adversario, y mató toda cosa hermosa á la vista: en la tiendade la hijade Siónderramócomo fuegosu enojo.","Entesósu arcocomo enemigo, afirmósu mano derechacomo adversario, y mató toda cosa hermosa á la vista: en la tiendade la hijade Siónderramócomo fuegosu enojo."],[2,5,"Fué el Señorcomo enemigo, destruyóá Israel; destruyótodossus palacios, disipó sus fortalezas: y multiplicóen la hijade Judála tristezay lamento.","Fué el Señorcomo enemigo, destruyóá Israel; destruyótodossus palacios, disipó sus fortalezas: y multiplicóen la hijade Judála tristezay lamento."],[2,6,"Y quitósu tiendacomo de un huerto, destruyóel lugar de su congregación: Jehováha hecho olvidar en Siónsolemnidadesy sábados, y ha desechadoen el furorde su irareyy sacerdote.","Y quitósu tiendacomo de un huerto, destruyóel lugar de su congregación: Jehováha hecho olvidar en Siónsolemnidadesy sábados, y ha desechadoen el furorde su irareyy sacerdote."],[2,7,"Desechóel Señorsu altar, menospreciósu santuario, ha entregadoen manodel enemigolos murosde sus palacios: dierongritaen la casade Jehovácomo en díade fiesta.","Desechóel Señorsu altar, menospreciósu santuario, ha entregadoen manodel enemigolos murosde sus palacios: dierongritaen la casade Jehovácomo en díade fiesta."],[2,8,"Jehovádeterminódestruirel murode la hijade Sión; extendióel cordel, noretrajosu manode destruir: hizo pues, se lamentarael antemuroy el muro; fueron destruídosjuntamente.","Jehovádeterminódestruirel murode la hijade Sión; extendióel cordel, noretrajosu manode destruir: hizo pues, se lamentarael antemuroy el muro; fueron destruídosjuntamente."],[2,9,"Sus puertasfueron echadaspor tierra, destruyóy quebrantósus cerrojos: su reyy sus príncipesestán entre las gentesdonde nohay ley; sus profetastampocohallaronvisiónde Jehová.","Sus puertasfueron echadaspor tierra, destruyóy quebrantósus cerrojos: su reyy sus príncipesestán entre las gentesdonde nohay ley; sus profetastampocohallaronvisiónde Jehová."],[2,10,"Sentáronseen tierra, callaronlos ancianosde la hijade Sión; echaronpolvosobresus cabezas, ciñéronsede saco; las vírgenesde Jerusalembajaronsus cabezasá tierra.","Sentáronseen tierra, callaronlos ancianosde la hijade Sión; echaronpolvosobresus cabezas, ciñéronsede saco; las vírgenesde Jerusalembajaronsus cabezasá tierra."],[2,11,"Mis ojosdesfallecieronde lágrimas, rugieronmis entrañas, mi hígadose derramópor tierrapor el quebrantamientode la hijade mi pueblo, cuando desfallecíael niñoy el que mamaba, en las plazasde la ciudad.","Mis ojosdesfallecieronde lágrimas, rugieronmis entrañas, mi hígadose derramópor tierrapor el quebrantamientode la hijade mi pueblo, cuando desfallecíael niñoy el que mamaba, en las plazasde la ciudad."],[2,12,"Decíaná sus madres: ¿Dóndeestá el trigoy el vino? Desfallecíancomo heridosen las callesde la ciudad, derramandosus almasenel regazode sus madres.","Decíaná sus madres: ¿Dóndeestá el trigoy el vino? Desfallecíancomo heridosen las callesde la ciudad, derramandosus almasenel regazode sus madres."],[2,13,"¿Quétestigote traeré, ó á quiénte haré semejante, hijade Jerusalem? ¿A quiénte compararépara consolarte, oh virgenhijade Sión? Porquegrandees tu quebrantamientocomo la mar: ¿quiénte medicinará?","¿Quétestigote traeré, ó á quiénte haré semejante, hijade Jerusalem? ¿A quiénte compararépara consolarte, oh virgenhijade Sión? Porquegrandees tu quebrantamientocomo la mar: ¿quiénte medicinará?"],[2,14,"Tus profetasvieronpara ti vanidady locura; y nodescubrierontu pecadopara estorbar tu cautiverio, sino que te predicaronvanasprofecíasy extravíos.","Tus profetasvieronpara ti vanidady locura; y nodescubrierontu pecadopara estorbar tu cautiverio, sino que te predicaronvanasprofecíasy extravíos."],[2,15,"Todoslos que pasabanpor el camino, batieronlas manossobreti; silbaron, y movieronsus cabezassobrela hijade Jerusalem, diciendo: ¿Es éstala ciudadque decíande perfectahermosura, el gozode todala tierra?","Todoslos que pasabanpor el camino, batieronlas manossobreti; silbaron, y movieronsus cabezassobrela hijade Jerusalem, diciendo: ¿Es éstala ciudadque decíande perfectahermosura, el gozode todala tierra?"],[2,16,"Todostus enemigosabrieronsobre ti su boca, silbaron, y rechinaronlos dientes; dijeron: Devoremos: ciertoéstees el díaque esperábamos; lo hemos hallado, vímoslo.","Todostus enemigosabrieronsobre ti su boca, silbaron, y rechinaronlos dientes; dijeron: Devoremos: ciertoéstees el díaque esperábamos; lo hemos hallado, vímoslo."],[2,17,"Jehováha hecholo quetenía determinado, ha cumplidosu palabraqueél había mandadodesde tiempoantiguo: destruyó, y noperdonó; y alegró sobreti al enemigo, y enaltecióel cuernode tus adversarios.","Jehováha hecholo quetenía determinado, ha cumplidosu palabraqueél había mandadodesde tiempoantiguo: destruyó, y noperdonó; y alegró sobreti al enemigo, y enaltecióel cuernode tus adversarios."],[2,18,"El corazónde ellos clamabaalSeñor: Oh muro de la hijade Sión, echa lágrimascomo un arroyodíay noche; nodescanses, nicesenlas niñasde tus ojos.","El corazónde ellos clamabaalSeñor: Oh muro de la hijade Sión, echa lágrimascomo un arroyodíay noche; nodescanses, nicesenlas niñasde tus ojos."],[2,19,"Levántate, da vocesen la noche, en el principiode las velas; derramacomo aguatu corazónantela presenciadel Señor; alzatus manosá él por la vidade tus pequeñitos, que desfallecende hambreen las entradasde todaslas calles.","Levántate, da vocesen la noche, en el principiode las velas; derramacomo aguatu corazónantela presenciadel Señor; alzatus manosá él por la vidade tus pequeñitos, que desfallecende hambreen las entradasde todaslas calles."],[2,20,"Mira, oh Jehová, y consideraá quiénhas hechoasí. ¿Han de comerlas mujeressu fruto, los pequeñitosde sus crías? ¿Hande ser muertosen el santuariodel Señorel sacerdotey el profeta?","Mira, oh Jehová, y consideraá quiénhas hechoasí. ¿Han de comerlas mujeressu fruto, los pequeñitosde sus crías? ¿Hande ser muertosen el santuariodel Señorel sacerdotey el profeta?"],[2,21,"Niñosy viejosyacíanpor tierraen las calles; mis vírgenesy mis manceboscayeroná cuchillo: matasteen el díade tu furor, degollaste, noperdonaste.","Niñosy viejosyacíanpor tierraen las calles; mis vírgenesy mis manceboscayeroná cuchillo: matasteen el díade tu furor, degollaste, noperdonaste."],[2,22,"Has llamado, comoá díade solemnidad, mis temoresde todas partes; y en el díadel furorde Jehovánohuboquien escapaseni quedase vivo: los quecriéy mantuve, mi enemigolos acabó.","Has llamado, comoá díade solemnidad, mis temoresde todas partes; y en el díadel furorde Jehovánohuboquien escapaseni quedase vivo: los quecriéy mantuve, mi enemigolos acabó."],[3,1,"YOsoy el hombreque ha vistoaflicciónen la varade su enojo.","YOsoy el hombreque ha vistoaflicciónen la varade su enojo."],[3,2,"Guiómey llevómeen tinieblas, mas noen luz.","Guiómey llevómeen tinieblas, mas noen luz."],[3,3,"Ciertamentecontra mí volvióy revolviósu manotodoel día.","Ciertamentecontra mí volvióy revolviósu manotodoel día."],[3,4,"Hizo envejecermi carney mi piel; quebrantómis huesos.","Hizo envejecermi carney mi piel; quebrantómis huesos."],[3,5,"Edificócontramí, y cercómede tósigoy de trabajo.","Edificócontramí, y cercómede tósigoy de trabajo."],[3,6,"Asentómeen oscuridades, como los ya muertosde mucho tiempo.","Asentómeen oscuridades, como los ya muertosde mucho tiempo."],[3,7,"Cercómepor todos lados, y nopuedo salir; agravómis grillos.","Cercómepor todos lados, y nopuedo salir; agravómis grillos."],[3,8,"Auncuandoclaméy dí voces, cerro los oídos ámi oración.","Auncuandoclaméy dí voces, cerro los oídos ámi oración."],[3,9,"Cercómis caminoscon piedra tajada, torciómis senderos.","Cercómis caminoscon piedra tajada, torciómis senderos."],[3,10,"Como osoque acechafué para mí, como leónen escondrijos.","Como osoque acechafué para mí, como leónen escondrijos."],[3,11,"Torciómis caminos, y depedazóme; tornómeasolado.","Torciómis caminos, y depedazóme; tornómeasolado."],[3,12,"Su arcoentesó, y púsomecomo blancoá la saeta.","Su arcoentesó, y púsomecomo blancoá la saeta."],[3,13,"Hizo entraren mis riñoneslas saetasde su aljaba.","Hizo entraren mis riñoneslas saetasde su aljaba."],[3,14,"Fuíescarnioá todomi pueblo, canción de ellos todoslos días.","Fuíescarnioá todomi pueblo, canción de ellos todoslos días."],[3,15,"Hartómede amarguras, embriagómede ajenjos.","Hartómede amarguras, embriagómede ajenjos."],[3,16,"Quebrómelos dientescon cascajo, cubriómede ceniza.","Quebrómelos dientescon cascajo, cubriómede ceniza."],[3,17,"Y mi almase alejóde la paz, olvidémedel bien.","Y mi almase alejóde la paz, olvidémedel bien."],[3,18,"Y dije: Pereciómi fortaleza, y mi esperanzade Jehová.","Y dije: Pereciómi fortaleza, y mi esperanzade Jehová."],[3,19,"Acuérdatede mi afliccióny de mi abatimiento, del ajenjoy de la hiel.","Acuérdatede mi afliccióny de mi abatimiento, del ajenjoy de la hiel."],[3,20,"Tendráloaún en memoriami alma, porque en mí está humillada.","Tendráloaún en memoriami alma, porque en mí está humillada."],[3,21,"Estoreduciréá mi corazón, porlo cual esperaré.","Estoreduciréá mi corazón, porlo cual esperaré."],[3,22,"Es porla misericordiade Jehováque nosomos consumidos, porquenuncadecayeronsus misericordias.","Es porla misericordiade Jehováque nosomos consumidos, porquenuncadecayeronsus misericordias."],[3,23,"Nuevasson cada mañana; grandees tu fidelidad.","Nuevasson cada mañana; grandees tu fidelidad."],[3,24,"Mi parte es Jehová, dijomi alma; portantoen él esperaré.","Mi parte es Jehová, dijomi alma; portantoen él esperaré."],[3,25,"Buenoes Jehováá los que en él esperan, al almaque le buscare.","Buenoes Jehováá los que en él esperan, al almaque le buscare."],[3,26,"Buenoes esperarcallandoen la saludde Jehová.","Buenoes esperarcallandoen la saludde Jehová."],[3,27,"Buenoes al hombre, si llevare el yugodesde su mocedad.","Buenoes al hombre, si llevare el yugodesde su mocedad."],[3,28,"Sentaráse solo, y callará, porquelo llevó sobre sí.","Sentaráse solo, y callará, porquelo llevó sobre sí."],[3,29,"Pondrá su bocaen el polvo, por si quizá hayesperanza.","Pondrá su bocaen el polvo, por si quizá hayesperanza."],[3,30,"Dará la mejillaal que le hiriere; hartarásede afrenta.","Dará la mejillaal que le hiriere; hartarásede afrenta."],[3,31,"Porqueel Señornodesecharápara siempre:","Porqueel Señornodesecharápara siempre:"],[3,32,"Antessi afligiere, también se compadecerá según la multitudde sus misericordias.","Antessi afligiere, también se compadecerá según la multitudde sus misericordias."],[3,33,"Porquenoafligeni congoja de su corazón á los hijosde los hombres.","Porquenoafligeni congoja de su corazón á los hijosde los hombres."],[3,34,"Desmenuzarbajode sus piestodoslos encarceladosde la tierra,","Desmenuzarbajode sus piestodoslos encarceladosde la tierra,"],[3,35,"Hacer apartar el derechodel hombreante la presenciadel Altísimo,","Hacer apartar el derechodel hombreante la presenciadel Altísimo,"],[3,36,"Trastornaral hombreen su causa, el Señornolo sabe.","Trastornaral hombreen su causa, el Señornolo sabe."],[3,37,"¿Quiénseráaquelque diga, que vino algoque el Señornomandó?","¿Quiénseráaquelque diga, que vino algoque el Señornomandó?"],[3,38,"¿De la bocadel Altísimonosaldrá maloy bueno?","¿De la bocadel Altísimonosaldrá maloy bueno?"],[3,39,"¿Por quémurmura el hombreviviente, el hombreensu pecado?","¿Por quémurmura el hombreviviente, el hombreensu pecado?"],[3,40,"Escudriñemosnuestroscaminos, y busquemos, y volvámonosáJehová.","Escudriñemosnuestroscaminos, y busquemos, y volvámonosáJehová."],[3,41,"Levantemosnuestroscorazonescon las manosáDiosen los cielos.","Levantemosnuestroscorazonescon las manosáDiosen los cielos."],[3,42,"Nosotrosnoshemos rebelado, y fuimos desleales; túnoperdonaste.","Nosotrosnoshemos rebelado, y fuimos desleales; túnoperdonaste."],[3,43,"Desplegastela ira, y nosperseguiste; mataste, noperdonaste.","Desplegastela ira, y nosperseguiste; mataste, noperdonaste."],[3,44,"Te cubristede nube, porque no pasasela oraciónnuestra.","Te cubristede nube, porque no pasasela oraciónnuestra."],[3,45,"Raedura y abominaciónnostornasteen mediode los pueblos.","Raedura y abominaciónnostornasteen mediode los pueblos."],[3,46,"Todosnuestrosenemigosabrieronsobre nosotrossu boca.","Todosnuestrosenemigosabrieronsobre nosotrossu boca."],[3,47,"Temory lazofué para nosotros, asolamientoy quebrantamiento.","Temory lazofué para nosotros, asolamientoy quebrantamiento."],[3,48,"Ríosde aguasechanmis ojos, porel quebrantamientode la hijade mi pueblo.","Ríosde aguasechanmis ojos, porel quebrantamientode la hijade mi pueblo."],[3,49,"Mis ojosdestilan, y nocesan, porque nohay alivio,","Mis ojosdestilan, y nocesan, porque nohay alivio,"],[3,50,"Hastaque Jehovámirey veadesde los cielos.","Hastaque Jehovámirey veadesde los cielos."],[3,51,"Mis ojoscontristaronmi alma, por todaslas hijasde mi ciudad.","Mis ojoscontristaronmi alma, por todaslas hijasde mi ciudad."],[3,52,"Mis enemigosme dieron cazacomo á ave, sin por qué.","Mis enemigosme dieron cazacomo á ave, sin por qué."],[3,53,"Ataronmi vidaen mazmorra, pusieronpiedrasobre mí.","Ataronmi vidaen mazmorra, pusieronpiedrasobre mí."],[3,54,"Aguasde avenida vinieronsobre mi cabeza; yo dije: Muertosoy.","Aguasde avenida vinieronsobre mi cabeza; yo dije: Muertosoy."],[3,55,"Invoquétu nombre, oh Jehová, desde la cárcelprofunda.","Invoquétu nombre, oh Jehová, desde la cárcelprofunda."],[3,56,"Oistemi voz; noescondastu oídoá mi clamor, para mi respiro.","Oistemi voz; noescondastu oídoá mi clamor, para mi respiro."],[3,57,"Acercástete el díaque te invoqué: dijiste: Notemas.","Acercástete el díaque te invoqué: dijiste: Notemas."],[3,58,"Abogaste, Señor, la causade mi alma; redimistemi vida.","Abogaste, Señor, la causade mi alma; redimistemi vida."],[3,59,"Tú has visto, oh Jehová, mi agravio; defiendemi causa.","Tú has visto, oh Jehová, mi agravio; defiendemi causa."],[3,60,"Tú has vistotodasu venganza; todossus pensamientoscontra mí.","Tú has vistotodasu venganza; todossus pensamientoscontra mí."],[3,61,"Tú has oídoel oprobiode ellos, oh Jehová, todassus maquinacionescontramí;","Tú has oídoel oprobiode ellos, oh Jehová, todassus maquinacionescontramí;"],[3,62,"Los dichosde los que contra mí se levantaron, y su designiocontramí todoel día.","Los dichosde los que contra mí se levantaron, y su designiocontramí todoel día."],[3,63,"Su sentarse, y su levantarsemira: yosoy su canción.","Su sentarse, y su levantarsemira: yosoy su canción."],[3,64,"Dalesel pago, oh Jehová, según la obrade sus manos.","Dalesel pago, oh Jehová, según la obrade sus manos."],[3,65,"Dalesansia de corazón, tu maldicióná ellos.","Dalesansia de corazón, tu maldicióná ellos."],[3,66,"Persíguelosen tu furor, y quebrántalosde debajode los cielos, oh Jehová.","Persíguelosen tu furor, y quebrántalosde debajode los cielos, oh Jehová."],[4,1,"¡CÓMOse ha oscurecidoel oro! ¡Cómoel buen orose ha demudado! Las piedrasdel santuarioestán esparcidaspor las encrucijadasde todaslas calles.","¡CÓMOse ha oscurecidoel oro! ¡Cómoel buen orose ha demudado! Las piedrasdel santuarioestán esparcidaspor las encrucijadasde todaslas calles."],[4,2,"Los hijosde Sión, preciadosy estimadosmás que el oro puro, ¡cómo sontenidospor vasosde barro, obrade manosde alfarero!","Los hijosde Sión, preciadosy estimadosmás que el oro puro, ¡cómo sontenidospor vasosde barro, obrade manosde alfarero!"],[4,3,"Aunlos monstruos marinos sacan la teta, dande mamará sus chiquitos: la hijade mi puebloes cruel, como los avestruces en el desierto.","Aunlos monstruos marinos sacan la teta, dande mamará sus chiquitos: la hijade mi puebloes cruel, como los avestruces en el desierto."],[4,4,"La lenguadel niñode teta, de sedse pegó ásu paladar: los chiquitospidieronpan, y nohubo quien se lopartiese.","La lenguadel niñode teta, de sedse pegó ásu paladar: los chiquitospidieronpan, y nohubo quien se lopartiese."],[4,5,"Los que comíandelicadamente, asoladosfueron en las calles; los que se criaron en carmesí, abrazaronlos estercoleros.","Los que comíandelicadamente, asoladosfueron en las calles; los que se criaron en carmesí, abrazaronlos estercoleros."],[4,6,"Y aumentósela iniquidadde la hijade mi pueblomás que el pecadode Sodoma, que fué trastornada en un momento, y no asentaron sobre ella compañías.","Y aumentósela iniquidadde la hijade mi pueblomás que el pecadode Sodoma, que fué trastornada en un momento, y no asentaron sobre ella compañías."],[4,7,"Sus Nazareosfueron blancosmás que la nieve, más lustrososque la leche, su composturamás rubicundaque los rubíes, más bellos que el zafiro:","Sus Nazareosfueron blancosmás que la nieve, más lustrososque la leche, su composturamás rubicundaque los rubíes, más bellos que el zafiro:"],[4,8,"Oscuramás que la negrura es la formade ellos; nolos conocenpor las calles: su pielestápegadaásus huesos, secacomo un palo.","Oscuramás que la negrura es la formade ellos; nolos conocenpor las calles: su pielestápegadaásus huesos, secacomo un palo."],[4,9,"Más dichososfueronlos muertosá cuchilloque los muertosdel hambre; porque éstosmurieronpoco á pocopor falta de los frutosde la tierra.","Más dichososfueronlos muertosá cuchilloque los muertosdel hambre; porque éstosmurieronpoco á pocopor falta de los frutosde la tierra."],[4,10,"Las manosde las mujerespiadosas cocieroná sus hijos; fuéronlescomidaen el quebrantamientode la hijade mi pueblo.","Las manosde las mujerespiadosas cocieroná sus hijos; fuéronlescomidaen el quebrantamientode la hijade mi pueblo."],[4,11,"CumplióJehovásu enojo, derramóel ardorde su ira; y encendiófuegoen Sión, que consumiósus fundamentos.","CumplióJehovásu enojo, derramóel ardorde su ira; y encendiófuegoen Sión, que consumiósus fundamentos."],[4,12,"Nuncalos reyesde la tierra, ni todoslos que habitanen el mundo, creyeronqueel enemigoy el adversarioentrarapor las puertasde Jerusalem.","Nuncalos reyesde la tierra, ni todoslos que habitanen el mundo, creyeronqueel enemigoy el adversarioentrarapor las puertasde Jerusalem."],[4,13,"Espor los pecadosde sus profetas, por las maldadesde sus sacerdotes, que derramaronen mediode ella la sangrede los justos.","Espor los pecadosde sus profetas, por las maldadesde sus sacerdotes, que derramaronen mediode ella la sangrede los justos."],[4,14,"Titubearoncomo ciegosen las calles, fueron contaminadosen sangre, de modo que nopudiesentocará sus vestiduras.","Titubearoncomo ciegosen las calles, fueron contaminadosen sangre, de modo que nopudiesentocará sus vestiduras."],[4,15,"Apartaos¡inmundos!, les gritaban, Apartaos, apartaos, notoquéis. Cuando huyerony fueron dispersos, dijeronentre las gentes: Nuncamásmoraránaquí.","Apartaos¡inmundos!, les gritaban, Apartaos, apartaos, notoquéis. Cuando huyerony fueron dispersos, dijeronentre las gentes: Nuncamásmoraránaquí."],[4,16,"La irade Jehoválos apartó, nolos mirarámás: norespetaronla fazde los sacerdotes, nituvieron compasiónde los viejos.","La irade Jehoválos apartó, nolos mirarámás: norespetaronla fazde los sacerdotes, nituvieron compasiónde los viejos."],[4,17,"Aunnos han desfallecidonuestrosojostras nuestrovanosocorro: en nuestraesperanzaaguardamosgenteque nopuede salvar.","Aunnos han desfallecidonuestrosojostras nuestrovanosocorro: en nuestraesperanzaaguardamosgenteque nopuede salvar."],[4,18,"Cazaronnuestrospasos, que no anduviésemospor nuestrascalles: acercósenuestrofin, cumpliéronsenuestrosdías; porquenuestrofinvino.","Cazaronnuestrospasos, que no anduviésemospor nuestrascalles: acercósenuestrofin, cumpliéronsenuestrosdías; porquenuestrofinvino."],[4,19,"Ligerosfueronnuestrosperseguidoresmás que las águilasdel cielo: sobrelos montesnospersiguieron, en el desiertonospusieron emboscadas.","Ligerosfueronnuestrosperseguidoresmás que las águilasdel cielo: sobrelos montesnospersiguieron, en el desiertonospusieron emboscadas."],[4,20,"El resuello de nuestrasnarices, el ungidode Jehová, de quienhabíamos dicho: A su sombratendremos vidaentre las gentes: fué preso en sus hoyos.","El resuello de nuestrasnarices, el ungidode Jehová, de quienhabíamos dicho: A su sombratendremos vidaentre las gentes: fué preso en sus hoyos."],[4,21,"Gózatey alégrate, hijade Edom, la que habitasen tierrade Hus: aunhastati pasará el cáliz; embriagarte has, y vomitarás.","Gózatey alégrate, hijade Edom, la que habitasen tierrade Hus: aunhastati pasará el cáliz; embriagarte has, y vomitarás."],[4,22,"Cumplidoes tu castigo, oh hijade Sión: nuncamáste hará trasportar. Visitarátu iniquidad, oh hijade Edom; descubrirátus pecados.","Cumplidoes tu castigo, oh hijade Sión: nuncamáste hará trasportar. Visitarátu iniquidad, oh hijade Edom; descubrirátus pecados."],[5,1,"ACUÉRDATE, oh Jehová, de lo quenos ha sucedido: vey miranuestrooprobio.","ACUÉRDATE, oh Jehová, de lo quenos ha sucedido: vey miranuestrooprobio."],[5,2,"Nuestraheredadse ha vuelto á extraños, nuestrascasasá forasteros.","Nuestraheredadse ha vuelto á extraños, nuestrascasasá forasteros."],[5,3,"Huérfanossomossinpadre, nuestrasmadrescomo viudas.","Huérfanossomossinpadre, nuestrasmadrescomo viudas."],[5,4,"Nuestraaguabebemospor dinero; nuestraleñapor preciocompramos.","Nuestraaguabebemospor dinero; nuestraleñapor preciocompramos."],[5,5,"Persecución padecemos sobrenuestra cerviz: noscansamos, y nohay para nosotrosreposo.","Persecución padecemos sobrenuestra cerviz: noscansamos, y nohay para nosotrosreposo."],[5,6,"Al Egipcioy al Asiriodimos la mano, para saciarnosde pan.","Al Egipcioy al Asiriodimos la mano, para saciarnosde pan."],[5,7,"Nuestrospadrespecaron, y son muertos; y nosotrosllevamossus castigos.","Nuestrospadrespecaron, y son muertos; y nosotrosllevamossus castigos."],[5,8,"Siervosse enseñorearonde nosotros; nohubo quien de su manonos librase.","Siervosse enseñorearonde nosotros; nohubo quien de su manonos librase."],[5,9,"Con peligro de nuestrasvidastraíamosnuestropandelante del cuchillodel desierto.","Con peligro de nuestrasvidastraíamosnuestropandelante del cuchillodel desierto."],[5,10,"Nuestrapielse ennegreciócomo un hornoá causa del ardordel hambre.","Nuestrapielse ennegreciócomo un hornoá causa del ardordel hambre."],[5,11,"Violaroná las mujeresen Sión, á las vírgenesen las ciudadesde Judá.","Violaroná las mujeresen Sión, á las vírgenesen las ciudadesde Judá."],[5,12,"A los príncipescolgaronpor su mano; norespetaronel rostrode los viejos.","A los príncipescolgaronpor su mano; norespetaronel rostrode los viejos."],[5,13,"Llevaronlos mozosá moler, y los muchachosdesfallecieronen la leña.","Llevaronlos mozosá moler, y los muchachosdesfallecieronen la leña."],[5,14,"Los ancianoscesaron de la puerta, los mancebosde sus canciones.","Los ancianoscesaron de la puerta, los mancebosde sus canciones."],[5,15,"Cesóel gozode nuestrocorazón; nuestrocorro se tornóen luto.","Cesóel gozode nuestrocorazón; nuestrocorro se tornóen luto."],[5,16,"Cayóla coronade nuestracabeza: ¡ayahorade nosotros! porquepecamos.","Cayóla coronade nuestracabeza: ¡ayahorade nosotros! porquepecamos."],[5,17,"Porestofuéentristecidonuestrocorazón, porestose entenebrecieronnuestrosojos:","Porestofuéentristecidonuestrocorazón, porestose entenebrecieronnuestrosojos:"],[5,18,"Porel montede Siónque está asolado; zorrasandanen él.","Porel montede Siónque está asolado; zorrasandanen él."],[5,19,"Mas tú, Jehová, permaneceráspara siempre: tutronode generaciónen generación.","Mas tú, Jehová, permaneceráspara siempre: tutronode generaciónen generación."],[5,20,"¿Por quéte olvidaráspara siempre de nosotros, y nosdejaráspor largosdías?","¿Por quéte olvidaráspara siempre de nosotros, y nosdejaráspor largosdías?"],[5,21,"Vuélvenos, oh Jehová, áti, y nos volveremos: renuevanuestrosdíascomo al principio.","Vuélvenos, oh Jehová, áti, y nos volveremos: renuevanuestrosdíascomo al principio."],[5,22,"Porquerepeliendo noshas desechado; te has airadocontranosotrosengranmanera.","Porquerepeliendo noshas desechado; te has airadocontranosotrosengranmanera."]],"rus-synodal":[[1,1,"Как одиноко сидит город, некогда многолюдный! он стал как вдова; великий между народами, князь над областями сделался данником.","Kak odinoko sidit gorod, nekogda mnogolûdnyj! on stal kak vdova; velikij meždu narodami, knâzʹ nad oblastâmi sdelalsâ dannikom."],[1,2,"Горько плачет он ночью, и слезы его на ланитах его. Нет у него утешителя из всех, любивших его; все друзья его изменили ему, сделались врагами ему.","Gorʹko plačet on nočʹû, i slezy ego na lanitah ego. Net u nego utešitelâ iz vseh, lûbivših ego; vse druzʹâ ego izmenili emu, sdelalisʹ vragami emu."],[1,3,"Иуда переселился по причине бедствия и тяжкого рабства, поселился среди язычников и не нашел покоя; все, преследовавшие его, настигли его в тесных местах.","Iuda pereselilsâ po pričine bedstviâ i tâžkogo rabstva, poselilsâ sredi âzyčnikov i ne našel pokoâ; vse, presledovavšie ego, nastigli ego v tesnyh mestah."],[1,4,"Пути Сиона сетуют, потому что нет идущих на праздник; все ворота его опустели; священники его вздыхают, девицы его печальны, горько и ему самому.","Puti Siona setuût, potomu čto net iduŝih na prazdnik; vse vorota ego opusteli; svâŝenniki ego vzdyhaût, devicy ego pečalʹny, gorʹko i emu samomu."],[1,5,"Враги его стали во главе, неприятели его благоденствуют, потому что Господь наслал на него горе за множество беззаконий его; дети его пошли в плен впереди врага.","Vragi ego stali vo glave, nepriâteli ego blagodenstvuût, potomu čto Gospodʹ naslal na nego gore za množestvo bezzakonij ego; deti ego pošli v plen vperedi vraga."],[1,6,"И отошло от дщери Сиона все ее великолепие; князья ее – как олени, не находящие пажити; обессиленные они пошли вперед погонщика.","I otošlo ot dŝeri Siona vse ee velikolepie; knâzʹâ ee – kak oleni, ne nahodâŝie pažiti; obessilennye oni pošli vpered pogonŝika."],[1,7,"Вспомнил Иерусалим, во дни бедствия своего и страданий своих, о всех драгоценностях своих, какие были у него в прежние дни, тогда как народ его пал от руки врага, и никто не помогает ему; неприятели смотрят на него и смеются над его субботами.","Vspomnil Ierusalim, vo dni bedstviâ svoego i stradanij svoih, o vseh dragocennostâh svoih, kakie byli u nego v prežnie dni, togda kak narod ego pal ot ruki vraga, i nikto ne pomogaet emu; nepriâteli smotrât na nego i smeûtsâ nad ego subbotami."],[1,8,"Тяжко согрешил Иерусалим, за то и сделался отвратительным; все, прославлявшие его, смотрят на него с презрением, потому что увидели наготу его; и сам он вздыхает и отворачивается назад.","Tâžko sogrešil Ierusalim, za to i sdelalsâ otvratitelʹnym; vse, proslavlâvšie ego, smotrât na nego s prezreniem, potomu čto uvideli nagotu ego; i sam on vzdyhaet i otvoračivaetsâ nazad."],[1,9,"На подоле у него была нечистота, но он не помышлял о будущности своей и поэтому необыкновенно унизился, и нет у него утешителя. «Воззри, Господи, на бедствие мое, ибо враг возвеличился!»","Na podole u nego byla nečistota, no on ne pomyšlâl o buduŝnosti svoej i poétomu neobyknovenno unizilsâ, i net u nego utešitelâ. «Vozzri, Gospodi, na bedstvie moe, ibo vrag vozveličilsâ!»"],[1,10,"Враг простер руку свою на все самое драгоценное его; он видит, как язычники входят во святилище его, о котором Ты заповедал, чтобы они не вступали в собрание Твое.","Vrag proster ruku svoû na vse samoe dragocennoe ego; on vidit, kak âzyčniki vhodât vo svâtiliŝe ego, o kotorom Ty zapovedal, čtoby oni ne vstupali v sobranie Tvoe."],[1,11,"Весь народ его вздыхает, ища хлеба, отдает драгоценности свои за пищу, чтобы подкрепить душу. «Воззри, Господи, и посмотри, как я унижен!»","Vesʹ narod ego vzdyhaet, iŝa hleba, otdaet dragocennosti svoi za piŝu, čtoby podkrepitʹ dušu. «Vozzri, Gospodi, i posmotri, kak â unižen!»"],[1,12,"Да не будет этого с вами, все проходящие путем! взгляните и посмотрите, есть ли болезнь, как моя болезнь, какая постигла меня, какую наслал на меня Господь в день пламенного гнева Своего?","Da ne budet étogo s vami, vse prohodâŝie putem! vzglânite i posmotrite, estʹ li boleznʹ, kak moâ boleznʹ, kakaâ postigla menâ, kakuû naslal na menâ Gospodʹ v denʹ plamennogo gneva Svoego?"],[1,13,"Свыше послал Он огонь в кости мои, и он овладел ими; раскинул сеть для ног моих, опрокинул меня, сделал меня бедным и томящимся всякий день.","Svyše poslal On ogonʹ v kosti moi, i on ovladel imi; raskinul setʹ dlâ nog moih, oprokinul menâ, sdelal menâ bednym i tomâŝimsâ vsâkij denʹ."],[1,14,"Ярмо беззаконий моих связано в руке Его; они сплетены и поднялись на шею мою; Он ослабил силы мои. Господь отдал меня в руки, из которых не могу подняться.","Ârmo bezzakonij moih svâzano v ruke Ego; oni spleteny i podnâlisʹ na šeû moû; On oslabil sily moi. Gospodʹ otdal menâ v ruki, iz kotoryh ne mogu podnâtʹsâ."],[1,15,"Всех сильных моих Господь низложил среди меня, созвал против меня собрание, чтобы истребить юношей моих; как в точиле, истоптал Господь деву, дочь Иуды.","Vseh silʹnyh moih Gospodʹ nizložil sredi menâ, sozval protiv menâ sobranie, čtoby istrebitʹ ûnošej moih; kak v točile, istoptal Gospodʹ devu, dočʹ Iudy."],[1,16,"Об этом плачу я; око мое, око мое изливает воды, ибо далеко от меня утешитель, который оживил бы душу мою; дети мои разорены, потому что враг превозмог.","Ob étom plaču â; oko moe, oko moe izlivaet vody, ibo daleko ot menâ utešitelʹ, kotoryj oživil by dušu moû; deti moi razoreny, potomu čto vrag prevozmog."],[1,17,"Сион простирает руки свои, но утешителя нет ему. Господь дал повеление о Иакове врагам его окружить его; Иерусалим сделался мерзостью среди них.","Sion prostiraet ruki svoi, no utešitelâ net emu. Gospodʹ dal povelenie o Iakove vragam ego okružitʹ ego; Ierusalim sdelalsâ merzostʹû sredi nih."],[1,18,"Праведен Господь, ибо я непокорен был слову Его. Послушайте, все народы, и взгляните на болезнь мою: девы мои и юноши мои пошли в плен.","Praveden Gospodʹ, ibo â nepokoren byl slovu Ego. Poslušajte, vse narody, i vzglânite na boleznʹ moû: devy moi i ûnoši moi pošli v plen."],[1,19,"Зову друзей моих, но они обманули меня; священники мои и старцы мои издыхают в городе, ища пищи себе, чтобы подкрепить душу свою.","Zovu druzej moih, no oni obmanuli menâ; svâŝenniki moi i starcy moi izdyhaût v gorode, iŝa piŝi sebe, čtoby podkrepitʹ dušu svoû."],[1,20,"Воззри, Господи, ибо мне тесно, волнуется во мне внутренность, сердце мое перевернулось во мне за то, что я упорно противился Тебе; отвне обесчадил меня меч, а дома – как смерть.","Vozzri, Gospodi, ibo mne tesno, volnuetsâ vo mne vnutrennostʹ, serdce moe perevernulosʹ vo mne za to, čto â uporno protivilsâ Tebe; otvne obesčadil menâ meč, a doma – kak smertʹ."],[1,21,"Услышали, что я стенаю, а утешителя у меня нет; услышали все враги мои о бедствии моем и обрадовались, что Ты соделал это: о, если бы Ты повелел наступить дню, предреченному Тобою, и они стали бы подобными мне!","Uslyšali, čto â stenaû, a utešitelâ u menâ net; uslyšali vse vragi moi o bedstvii moem i obradovalisʹ, čto Ty sodelal éto: o, esli by Ty povelel nastupitʹ dnû, predrečennomu Toboû, i oni stali by podobnymi mne!"],[1,22,"Да предстанет пред лицо Твое вся злоба их; и поступи с ними так же, как Ты поступил со мною за все грехи мои, ибо тяжки стоны мои, и сердце мое изнемогает.","Da predstanet pred lico Tvoe vsâ zloba ih; i postupi s nimi tak že, kak Ty postupil so mnoû za vse grehi moi, ibo tâžki stony moi, i serdce moe iznemogaet."],[2,1,"Как помрачил Господь во гневе Своем дщерь Сиона! с небес поверг на землю красу Израиля и не вспомнил о подножии ног Своих в день гнева Своего.","Kak pomračil Gospodʹ vo gneve Svoem dŝerʹ Siona! s nebes poverg na zemlû krasu Izrailâ i ne vspomnil o podnožii nog Svoih v denʹ gneva Svoego."],[2,2,"Погубил Господь все жилища Иакова, не пощадил, разрушил в ярости Своей укрепления дщери Иудиной, поверг на землю, отверг царство и князей его, как нечистых;","Pogubil Gospodʹ vse žiliŝa Iakova, ne poŝadil, razrušil v ârosti Svoej ukrepleniâ dŝeri Iudinoj, poverg na zemlû, otverg carstvo i knâzej ego, kak nečistyh;"],[2,3,"в пылу гнева сломил все роги Израилевы, отвел десницу Свою от неприятеля и воспылал в Иакове, как палящий огонь, пожиравший все вокруг;","v pylu gneva slomil vse rogi Izrailevy, otvel desnicu Svoû ot nepriâtelâ i vospylal v Iakove, kak palâŝij ogonʹ, požiravšij vse vokrug;"],[2,4,"натянул лук Свой, как неприятель, направил десницу Свою, как враг, и убил все, вожделенное для глаз; на скинию дщери Сиона излил ярость Свою, как огонь.","natânul luk Svoj, kak nepriâtelʹ, napravil desnicu Svoû, kak vrag, i ubil vse, voždelennoe dlâ glaz; na skiniû dŝeri Siona izlil ârostʹ Svoû, kak ogonʹ."],[2,5,"Господь стал как неприятель, истребил Израиля, разорил все чертоги его, разрушил укрепления его и распространил у дщери Иудиной сетование и плач.","Gospodʹ stal kak nepriâtelʹ, istrebil Izrailâ, razoril vse čertogi ego, razrušil ukrepleniâ ego i rasprostranil u dŝeri Iudinoj setovanie i plač."],[2,6,"И отнял ограду Свою, как у сада; разорил Свое место собраний, заставил Господь забыть на Сионе празднества и субботы; и в негодовании гнева Своего отверг царя и священника.","I otnâl ogradu Svoû, kak u sada; razoril Svoe mesto sobranij, zastavil Gospodʹ zabytʹ na Sione prazdnestva i subboty; i v negodovanii gneva Svoego otverg carâ i svâŝennika."],[2,7,"Отверг Господь жертвенник Свой, отвратил сердце Свое от святилища Своего, предал в руки врагов стены чертогов его; в доме Господнем они шумели, как в праздничный день.","Otverg Gospodʹ žertvennik Svoj, otvratil serdce Svoe ot svâtiliŝa Svoego, predal v ruki vragov steny čertogov ego; v dome Gospodnem oni šumeli, kak v prazdničnyj denʹ."],[2,8,"Господь определил разрушить стену дщери Сиона, протянул вервь, не отклонил руки Своей от разорения; истребил внешние укрепления, и стены вместе разрушены.","Gospodʹ opredelil razrušitʹ stenu dŝeri Siona, protânul vervʹ, ne otklonil ruki Svoej ot razoreniâ; istrebil vnešnie ukrepleniâ, i steny vmeste razrušeny."],[2,9,"Ворота ее вдались в землю; Он разрушил и сокрушил запоры их; царь ее и князья ее – среди язычников; не стало закона, и пророки ее не сподобляются видений от Господа.","Vorota ee vdalisʹ v zemlû; On razrušil i sokrušil zapory ih; carʹ ee i knâzʹâ ee – sredi âzyčnikov; ne stalo zakona, i proroki ee ne spodoblâûtsâ videnij ot Gospoda."],[2,10,"Сидят на земле безмолвно старцы дщери Сионовой, посыпали пеплом свои головы, препоясались вретищем; опустили к земле головы свои девы Иерусалимские.","Sidât na zemle bezmolvno starcy dŝeri Sionovoj, posypali peplom svoi golovy, prepoâsalisʹ vretiŝem; opustili k zemle golovy svoi devy Ierusalimskie."],[2,11,"Истощились от слез глаза мои, волнуется во мне внутренность моя, изливается на землю печень моя от гибели дщери народа моего, когда дети и грудные младенцы умирают от голода среди городских улиц.","Istoŝilisʹ ot slez glaza moi, volnuetsâ vo mne vnutrennostʹ moâ, izlivaetsâ na zemlû pečenʹ moâ ot gibeli dŝeri naroda moego, kogda deti i grudnye mladency umiraût ot goloda sredi gorodskih ulic."],[2,12,"Матерям своим говорят они: «где хлеб и вино?», умирая, подобно раненым, на улицах городских, изливая души свои в лоно матерей своих.","Materâm svoim govorât oni: «gde hleb i vino?», umiraâ, podobno ranenym, na ulicah gorodskih, izlivaâ duši svoi v lono materej svoih."],[2,13,"Что мне сказать тебе, с чем сравнить тебя, дщерь Иерусалима? чему уподобить тебя, чтобы утешить тебя, дева, дщерь Сиона? ибо рана твоя велика, как море; кто может исцелить тебя?","Čto mne skazatʹ tebe, s čem sravnitʹ tebâ, dŝerʹ Ierusalima? čemu upodobitʹ tebâ, čtoby utešitʹ tebâ, deva, dŝerʹ Siona? ibo rana tvoâ velika, kak more; kto možet iscelitʹ tebâ?"],[2,14,"Пророки твои провещали тебе пустое и ложное и не раскрывали твоего беззакония, чтобы отвратить твое пленение, и изрекали тебе откровения ложные и приведшие тебя к изгнанию.","Proroki tvoi proveŝali tebe pustoe i ložnoe i ne raskryvali tvoego bezzakoniâ, čtoby otvratitʹ tvoe plenenie, i izrekali tebe otkroveniâ ložnye i privedšie tebâ k izgnaniû."],[2,15,"Руками всплескивают о тебе все, проходящие путем, свищут и качают головою своею о дщери Иерусалима, говоря: «это ли город, который называли совершенством красоты, радостью всей земли?»","Rukami vspleskivaût o tebe vse, prohodâŝie putem, sviŝut i kačaût golovoû svoeû o dŝeri Ierusalima, govorâ: «éto li gorod, kotoryj nazyvali soveršenstvom krasoty, radostʹû vsej zemli?»"],[2,16,"Разинули на тебя пасть свою все враги твои, свищут и скрежещут зубами, говорят: «поглотили мы его, только этого дня и ждали мы, дождались, увидели!»","Razinuli na tebâ pastʹ svoû vse vragi tvoi, sviŝut i skrežeŝut zubami, govorât: «poglotili my ego, tolʹko étogo dnâ i ždali my, doždalisʹ, uvideli!»"],[2,17,"Совершил Господь, что определил, исполнил слово Свое, изреченное в древние дни, разорил без пощады и дал врагу порадоваться над тобою, вознес рог неприятелей твоих.","Soveršil Gospodʹ, čto opredelil, ispolnil slovo Svoe, izrečennoe v drevnie dni, razoril bez poŝady i dal vragu poradovatʹsâ nad toboû, voznes rog nepriâtelej tvoih."],[2,18,"Сердце их вопиет к Господу. Стена дщери Сиона! лей ручьем слезы день и ночь, не давай себе покоя, не спускай зениц очей твоих.","Serdce ih vopiet k Gospodu. Stena dŝeri Siona! lej ručʹem slezy denʹ i nočʹ, ne davaj sebe pokoâ, ne spuskaj zenic očej tvoih."],[2,19,"Вставай, взывай ночью, при начале каждой стражи; изливай, как воду, сердце твое пред лицом Господа; простирай к Нему руки твои о душе детей твоих, издыхающих от голода на углах всех улиц.","Vstavaj, vzyvaj nočʹû, pri načale každoj straži; izlivaj, kak vodu, serdce tvoe pred licom Gospoda; prostiraj k Nemu ruki tvoi o duše detej tvoih, izdyhaûŝih ot goloda na uglah vseh ulic."],[2,20,"«Воззри, Господи, и посмотри: кому Ты сделал так, чтобы женщины ели плод свой, младенцев, вскормленных ими? чтобы убиваемы были в святилище Господнем священник и пророк?","«Vozzri, Gospodi, i posmotri: komu Ty sdelal tak, čtoby ženŝiny eli plod svoj, mladencev, vskormlennyh imi? čtoby ubivaemy byli v svâtiliŝe Gospodnem svâŝennik i prorok?"],[2,21,"Дети и старцы лежат на земле по улицам; девы мои и юноши мои пали от меча; Ты убивал их в день гнева Твоего, закалал без пощады.","Deti i starcy ležat na zemle po ulicam; devy moi i ûnoši moi pali ot meča; Ty ubival ih v denʹ gneva Tvoego, zakalal bez poŝady."],[2,22,"Ты созвал отовсюду, как на праздник, ужасы мои, и в день гнева Господня никто не спасся, никто не уцелел; тех, которые были мною вскормлены и выращены, враг мой истребил».","Ty sozval otovsûdu, kak na prazdnik, užasy moi, i v denʹ gneva Gospodnâ nikto ne spassâ, nikto ne ucelel; teh, kotorye byli mnoû vskormleny i vyraŝeny, vrag moj istrebil»."],[3,1,"Я – человек, испытавший горе от жезла гнева Его.","Â – čelovek, ispytavšij gore ot žezla gneva Ego."],[3,2,"Он повел меня и ввел во тьму, а не во свет.","On povel menâ i vvel vo tʹmu, a ne vo svet."],[3,3,"Так, Он обратился на меня и весь день обращает руку Свою;","Tak, On obratilsâ na menâ i vesʹ denʹ obraŝaet ruku Svoû;"],[3,4,"измождил плоть мою и кожу мою, сокрушил кости мои;","izmoždil plotʹ moû i kožu moû, sokrušil kosti moi;"],[3,5,"огородил меня и обложил горечью и тяготою;","ogorodil menâ i obložil gorečʹû i tâgotoû;"],[3,6,"посадил меня в темное место, как давно умерших;","posadil menâ v temnoe mesto, kak davno umerših;"],[3,7,"окружил меня стеною, чтобы я не вышел, отяготил оковы мои,","okružil menâ stenoû, čtoby â ne vyšel, otâgotil okovy moi,"],[3,8,"и когда я взывал и вопиял, задерживал молитву мою;","i kogda â vzyval i vopiâl, zaderžival molitvu moû;"],[3,9,"каменьями преградил дороги мои, извратил стези мои.","kamenʹâmi pregradil dorogi moi, izvratil stezi moi."],[3,10,"Он стал для меня как бы медведь в засаде, как бы лев в скрытном месте;","On stal dlâ menâ kak by medvedʹ v zasade, kak by lev v skrytnom meste;"],[3,11,"извратил пути мои и растерзал меня, привел меня в ничто;","izvratil puti moi i rasterzal menâ, privel menâ v ničto;"],[3,12,"натянул лук Свой и поставил меня как бы целью для стрел;","natânul luk Svoj i postavil menâ kak by celʹû dlâ strel;"],[3,13,"послал в почки мои стрелы из колчана Своего.","poslal v počki moi strely iz kolčana Svoego."],[3,14,"Я стал посмешищем для всего народа моего, вседневною песнью их.","Â stal posmešiŝem dlâ vsego naroda moego, vsednevnoû pesnʹû ih."],[3,15,"Он пресытил меня горечью, напоил меня полынью.","On presytil menâ gorečʹû, napoil menâ polynʹû."],[3,16,"Сокрушил камнями зубы мои, покрыл меня пеплом.","Sokrušil kamnâmi zuby moi, pokryl menâ peplom."],[3,17,"И удалился мир от души моей; я забыл о благоденствии,","I udalilsâ mir ot duši moej; â zabyl o blagodenstvii,"],[3,18,"и сказал я: погибла сила моя и надежда моя на Господа.","i skazal â: pogibla sila moâ i nadežda moâ na Gospoda."],[3,19,"Помысли о моем страдании и бедствии моем, о полыни и желчи.","Pomysli o moem stradanii i bedstvii moem, o polyni i želči."],[3,20,"Твердо помнит это душа моя и падает во мне.","Tverdo pomnit éto duša moâ i padaet vo mne."],[3,21,"Вот что я отвечаю сердцу моему и потому уповаю:","Vot čto â otvečaû serdcu moemu i potomu upovaû:"],[3,22,"по милости Господа мы не исчезли, ибо милосердие Его не истощилось.","po milosti Gospoda my ne isčezli, ibo miloserdie Ego ne istoŝilosʹ."],[3,23,"Оно обновляется каждое утро; велика верность Твоя!","Ono obnovlâetsâ každoe utro; velika vernostʹ Tvoâ!"],[3,24,"Господь – часть моя, говорит душа моя, итак буду надеяться на Него.","Gospodʹ – častʹ moâ, govorit duša moâ, itak budu nadeâtʹsâ na Nego."],[3,25,"Благ Господь к надеющимся на Него, к душе, ищущей Его.","Blag Gospodʹ k nadeûŝimsâ na Nego, k duše, iŝuŝej Ego."],[3,26,"Благо тому, кто терпеливо ожидает спасения от Господа.","Blago tomu, kto terpelivo ožidaet spaseniâ ot Gospoda."],[3,27,"Благо человеку, когда он несет иго в юности своей;","Blago čeloveku, kogda on neset igo v ûnosti svoej;"],[3,28,"сидит уединенно и молчит, ибо Он наложил его на него;","sidit uedinenno i molčit, ibo On naložil ego na nego;"],[3,29,"полагает уста свои в прах, помышляя: «может быть, еще есть надежда»;","polagaet usta svoi v prah, pomyšlââ: «možet bytʹ, eŝe estʹ nadežda»;"],[3,30,"подставляет ланиту свою биющему его, пресыщается поношением,","podstavlâet lanitu svoû biûŝemu ego, presyŝaetsâ ponošeniem,"],[3,31,"ибо не навек оставляет Господь.","ibo ne navek ostavlâet Gospodʹ."],[3,32,"Но послал горе, и помилует по великой благости Своей.","No poslal gore, i pomiluet po velikoj blagosti Svoej."],[3,33,"Ибо Он не по изволению сердца Своего наказывает и огорчает сынов человеческих.","Ibo On ne po izvoleniû serdca Svoego nakazyvaet i ogorčaet synov čelovečeskih."],[3,34,"Но, когда попирают ногами своими всех узников земли,","No, kogda popiraût nogami svoimi vseh uznikov zemli,"],[3,35,"когда неправедно судят человека пред лицом Всевышнего,","kogda nepravedno sudât čeloveka pred licom Vsevyšnego,"],[3,36,"когда притесняют человека в деле его: разве не видит Господь?","kogda pritesnâût čeloveka v dele ego: razve ne vidit Gospodʹ?"],[3,37,"Кто это говорит: «и то бывает, чему Господь не повелел быть»?","Kto éto govorit: «i to byvaet, čemu Gospodʹ ne povelel bytʹ»?"],[3,38,"Не от уст ли Всевышнего происходит бедствие и благополучие?","Ne ot ust li Vsevyšnego proishodit bedstvie i blagopolučie?"],[3,39,"Зачем сетует человек живущий? всякий сетуй на грехи свои.","Začem setuet čelovek živuŝij? vsâkij setuj na grehi svoi."],[3,40,"Испытаем и исследуем пути свои и обратимся к Господу.","Ispytaem i issleduem puti svoi i obratimsâ k Gospodu."],[3,41,"Вознесем сердце наше и руки к Богу, сущему на небесах:","Voznesem serdce naše i ruki k Bogu, suŝemu na nebesah:"],[3,42,"мы отпали и упорствовали; Ты не пощадил.","my otpali i uporstvovali; Ty ne poŝadil."],[3,43,"Ты покрыл Себя гневом и преследовал нас, умерщвлял, не щадил;","Ty pokryl Sebâ gnevom i presledoval nas, umerŝvlâl, ne ŝadil;"],[3,44,"Ты закрыл Себя облаком, чтобы не доходила молитва наша;","Ty zakryl Sebâ oblakom, čtoby ne dohodila molitva naša;"],[3,45,"сором и мерзостью Ты сделал нас среди народов.","sorom i merzostʹû Ty sdelal nas sredi narodov."],[3,46,"Разинули на нас пасть свою все враги наши.","Razinuli na nas pastʹ svoû vse vragi naši."],[3,47,"Ужас и яма, опустошение и разорение – доля наша.","Užas i âma, opustošenie i razorenie – dolâ naša."],[3,48,"Потоки вод изливает око мое о гибели дщери народа моего.","Potoki vod izlivaet oko moe o gibeli dŝeri naroda moego."],[3,49,"Око мое изливается и не перестает, ибо нет облегчения,","Oko moe izlivaetsâ i ne perestaet, ibo net oblegčeniâ,"],[3,50,"доколе не призрит и не увидит Господь с небес.","dokole ne prizrit i ne uvidit Gospodʹ s nebes."],[3,51,"Око мое опечаливает душу мою ради всех дщерей моего города.","Oko moe opečalivaet dušu moû radi vseh dŝerej moego goroda."],[3,52,"Всячески усиливались уловить меня, как птичку, враги мои, без всякой причины;","Vsâčeski usilivalisʹ ulovitʹ menâ, kak ptičku, vragi moi, bez vsâkoj pričiny;"],[3,53,"повергли жизнь мою в яму и закидали меня камнями.","povergli žiznʹ moû v âmu i zakidali menâ kamnâmi."],[3,54,"Воды поднялись до головы моей; я сказал: «погиб я».","Vody podnâlisʹ do golovy moej; â skazal: «pogib â»."],[3,55,"Я призывал имя Твое, Господи, из ямы глубокой.","Â prizyval imâ Tvoe, Gospodi, iz âmy glubokoj."],[3,56,"Ты слышал голос мой; не закрой уха Твоего от воздыхания моего, от вопля моего.","Ty slyšal golos moj; ne zakroj uha Tvoego ot vozdyhaniâ moego, ot voplâ moego."],[3,57,"Ты приближался, когда я взывал к Тебе, и говорил: «не бойся».","Ty približalsâ, kogda â vzyval k Tebe, i govoril: «ne bojsâ»."],[3,58,"Ты защищал, Господи, дело души моей; искуплял жизнь мою.","Ty zaŝiŝal, Gospodi, delo duši moej; iskuplâl žiznʹ moû."],[3,59,"Ты видишь, Господи, обиду мою; рассуди дело мое.","Ty vidišʹ, Gospodi, obidu moû; rassudi delo moe."],[3,60,"Ты видишь всю мстительность их, все замыслы их против меня.","Ty vidišʹ vsû mstitelʹnostʹ ih, vse zamysly ih protiv menâ."],[3,61,"Ты слышишь, Господи, ругательство их, все замыслы их против меня,","Ty slyšišʹ, Gospodi, rugatelʹstvo ih, vse zamysly ih protiv menâ,"],[3,62,"речи восстающих на меня и их ухищрения против меня всякий день.","reči vosstaûŝih na menâ i ih uhiŝreniâ protiv menâ vsâkij denʹ."],[3,63,"Воззри, сидят ли они, встают ли, я для них – песнь.","Vozzri, sidât li oni, vstaût li, â dlâ nih – pesnʹ."],[3,64,"Воздай им, Господи, по делам рук их;","Vozdaj im, Gospodi, po delam ruk ih;"],[3,65,"пошли им помрачение сердца и проклятие Твое на них;","pošli im pomračenie serdca i proklâtie Tvoe na nih;"],[3,66,"преследуй их, Господи, гневом, и истреби их из поднебесной.","presleduj ih, Gospodi, gnevom, i istrebi ih iz podnebesnoj."],[4,1,"Как потускло золото, изменилось золото наилучшее! камни святилища раскиданы по всем перекресткам.","Kak potusklo zoloto, izmenilosʹ zoloto nailučšee! kamni svâtiliŝa raskidany po vsem perekrestkam."],[4,2,"Сыны Сиона драгоценные, равноценные чистейшему золоту, как они сравнены с глиняною посудою, изделием рук горшечника!","Syny Siona dragocennye, ravnocennye čistejšemu zolotu, kak oni sravneny s glinânoû posudoû, izdeliem ruk goršečnika!"],[4,3,"И чудовища подают сосцы и кормят своих детенышей, а дщерь народа моего стала жестока, подобно страусам в пустыне.","I čudoviŝa podaût soscy i kormât svoih detenyšej, a dŝerʹ naroda moego stala žestoka, podobno strausam v pustyne."],[4,4,"Язык грудного младенца прилипает к гортани его от жажды; дети просят хлеба, и никто не подает им.","Âzyk grudnogo mladenca prilipaet k gortani ego ot žaždy; deti prosât hleba, i nikto ne podaet im."],[4,5,"Евшие сладкое истаевают на улицах; воспитанные на багрянице жмутся к навозу.","Evšie sladkoe istaevaût na ulicah; vospitannye na bagrânice žmutsâ k navozu."],[4,6,"Наказание нечестия дщери народа моего превышает казнь за грехи Содома: тот низринут мгновенно, и руки человеческие не касались его.","Nakazanie nečestiâ dŝeri naroda moego prevyšaet kaznʹ za grehi Sodoma: tot nizrinut mgnovenno, i ruki čelovečeskie ne kasalisʹ ego."],[4,7,"Князья ее были в ней чище снега, белее молока; они были телом краше коралла, вид их был как сапфир;","Knâzʹâ ee byli v nej čiŝe snega, belee moloka; oni byli telom kraše koralla, vid ih byl kak sapfir;"],[4,8,"а теперь темнее всего черного лицо их; не узнают их на улицах; кожа их прилипла к костям их, стала суха, как дерево.","a teperʹ temnee vsego černogo lico ih; ne uznaût ih na ulicah; koža ih prilipla k kostâm ih, stala suha, kak derevo."],[4,9,"Умерщвляемые мечом счастливее умерщвляемых голодом, потому что сии истаевают, поражаемые недостатком плодов полевых.","Umerŝvlâemye mečom sčastlivee umerŝvlâemyh golodom, potomu čto sii istaevaût, poražaemye nedostatkom plodov polevyh."],[4,10,"Руки мягкосердых женщин варили детей своих, чтобы они были для них пищею во время гибели дщери народа моего.","Ruki mâgkoserdyh ženŝin varili detej svoih, čtoby oni byli dlâ nih piŝeû vo vremâ gibeli dŝeri naroda moego."],[4,11,"Совершил Господь гнев Свой, излил ярость гнева Своего и зажег на Сионе огонь, который пожрал основания его.","Soveršil Gospodʹ gnev Svoj, izlil ârostʹ gneva Svoego i zažeg na Sione ogonʹ, kotoryj požral osnovaniâ ego."],[4,12,"Не верили цари земли и все живущие во вселенной, чтобы враг и неприятель вошел во врата Иерусалима.","Ne verili cari zemli i vse živuŝie vo vselennoj, čtoby vrag i nepriâtelʹ vošel vo vrata Ierusalima."],[4,13,"Все это – за грехи лжепророков его, за беззакония священников его, которые среди него проливали кровь праведников;","Vse éto – za grehi lžeprorokov ego, za bezzakoniâ svâŝennikov ego, kotorye sredi nego prolivali krovʹ pravednikov;"],[4,14,"бродили как слепые по улицам, осквернялись кровью, так что невозможно было прикоснуться к одеждам их.","brodili kak slepye po ulicam, oskvernâlisʹ krovʹû, tak čto nevozmožno bylo prikosnutʹsâ k odeždam ih."],[4,15,"«Сторонитесь! нечистый!» – кричали им; «сторонитесь, сторонитесь, не прикасайтесь»; и они уходили в смущении; а между народом говорили: «их более не будет!","«Storonitesʹ! nečistyj!» – kričali im; «storonitesʹ, storonitesʹ, ne prikasajtesʹ»; i oni uhodili v smuŝenii; a meždu narodom govorili: «ih bolee ne budet!"],[4,16,"Лицо Господне рассеет их; Он уже не призрит на них», потому что они лица священников не уважают, старцев не милуют.","Lico Gospodne rasseet ih; On uže ne prizrit na nih», potomu čto oni lica svâŝennikov ne uvažaût, starcev ne miluût."],[4,17,"Наши глаза истомлены в напрасном ожидании помощи; со сторожевой башни нашей мы ожидали народ, который не мог спасти нас.","Naši glaza istomleny v naprasnom ožidanii pomoŝi; so storoževoj bašni našej my ožidali narod, kotoryj ne mog spasti nas."],[4,18,"А они подстерегали шаги наши, чтобы мы не могли ходить по улицам нашим; приблизился конец наш, дни наши исполнились; пришел конец наш.","A oni podsteregali šagi naši, čtoby my ne mogli hoditʹ po ulicam našim; priblizilsâ konec naš, dni naši ispolnilisʹ; prišel konec naš."],[4,19,"Преследовавшие нас были быстрее орлов небесных; гонялись за нами по горам, ставили засаду для нас в пустыне.","Presledovavšie nas byli bystree orlov nebesnyh; gonâlisʹ za nami po goram, stavili zasadu dlâ nas v pustyne."],[4,20,"Дыхание жизни нашей, помазанник Господень пойман в ямы их, тот, о котором мы говорили: «под тенью его будем жить среди народов».","Dyhanie žizni našej, pomazannik Gospodenʹ pojman v âmy ih, tot, o kotorom my govorili: «pod tenʹû ego budem žitʹ sredi narodov»."],[4,21,"Радуйся и веселись, дочь Едома, обитательница земли Уц! И до тебя дойдет чаша; напьешься допьяна и обнажишься.","Radujsâ i veselisʹ, dočʹ Edoma, obitatelʹnica zemli Uc! I do tebâ dojdet čaša; napʹešʹsâ dopʹâna i obnažišʹsâ."],[4,22,"Дщерь Сиона! наказание за беззаконие твое кончилось; Он не будет более изгонять тебя; но твое беззаконие, дочь Едома, Он посетит и обнаружит грехи твои.","Dŝerʹ Siona! nakazanie za bezzakonie tvoe končilosʹ; On ne budet bolee izgonâtʹ tebâ; no tvoe bezzakonie, dočʹ Edoma, On posetit i obnaružit grehi tvoi."],[5,1,"Вспомни, Господи, что над нами совершилось; призри и посмотри на поругание наше.","Vspomni, Gospodi, čto nad nami soveršilosʹ; prizri i posmotri na poruganie naše."],[5,2,"Наследие наше перешло к чужим, домы наши – к иноплеменным;","Nasledie naše perešlo k čužim, domy naši – k inoplemennym;"],[5,3,"мы сделались сиротами, без отца; матери наши – как вдовы.","my sdelalisʹ sirotami, bez otca; materi naši – kak vdovy."],[5,4,"Воду свою пьем за серебро, дрова наши достаются нам за деньги.","Vodu svoû pʹem za serebro, drova naši dostaûtsâ nam za denʹgi."],[5,5,"Нас погоняют в шею, мы работаем и не имеем отдыха.","Nas pogonâût v šeû, my rabotaem i ne imeem otdyha."],[5,6,"Протягиваем руку к Египтянам, к Ассириянам, чтобы насытиться хлебом.","Protâgivaem ruku k Egiptânam, k Assiriânam, čtoby nasytitʹsâ hlebom."],[5,7,"Отцы наши грешили; их уже нет, а мы несем наказание за беззакония их.","Otcy naši grešili; ih uže net, a my nesem nakazanie za bezzakoniâ ih."],[5,8,"Рабы господствуют над нами, и некому избавить от руки их.","Raby gospodstvuût nad nami, i nekomu izbavitʹ ot ruki ih."],[5,9,"С опасностью жизни от меча, в пустыне достаем хлеб себе.","S opasnostʹû žizni ot meča, v pustyne dostaem hleb sebe."],[5,10,"Кожа наша почернела, как печь, от жгучего голода.","Koža naša počernela, kak pečʹ, ot žgučego goloda."],[5,11,"Жен бесчестят на Сионе, девиц – в городах Иудейских.","Žen besčestât na Sione, devic – v gorodah Iudejskih."],[5,12,"Князья повешены руками их, лица старцев не уважены.","Knâzʹâ povešeny rukami ih, lica starcev ne uvaženy."],[5,13,"Юношей берут к жерновам, и отроки падают под ношами дров.","Ûnošej berut k žernovam, i otroki padaût pod nošami drov."],[5,14,"Старцы уже не сидят у ворот; юноши не поют.","Starcy uže ne sidât u vorot; ûnoši ne poût."],[5,15,"Прекратилась радость сердца нашего; хороводы наши обратились в сетование.","Prekratilasʹ radostʹ serdca našego; horovody naši obratilisʹ v setovanie."],[5,16,"Упал венец с головы нашей; горе нам, что мы согрешили!","Upal venec s golovy našej; gore nam, čto my sogrešili!"],[5,17,"От сего-то изнывает сердце наше; от сего померкли глаза наши.","Ot sego-to iznyvaet serdce naše; ot sego pomerkli glaza naši."],[5,18,"Оттого, что опустела гора Сион, лисицы ходят по ней.","Ottogo, čto opustela gora Sion, lisicy hodât po nej."],[5,19,"Ты, Господи, пребываешь вовеки; престол Твой – в род и род.","Ty, Gospodi, prebyvaešʹ voveki; prestol Tvoj – v rod i rod."],[5,20,"Для чего совсем забываешь нас, оставляешь нас на долгое время?","Dlâ čego sovsem zabyvaešʹ nas, ostavlâešʹ nas na dolgoe vremâ?"],[5,21,"Обрати нас к Тебе, Господи, и мы обратимся; обнови дни наши, как древле.","Obrati nas k Tebe, Gospodi, i my obratimsâ; obnovi dni naši, kak drevle."],[5,22,"Неужели Ты совсем отверг нас, прогневался на нас безмерно?","Neuželi Ty sovsem otverg nas, prognevalsâ na nas bezmerno?"]],"cmn-cuv-hant":[[1,1,"先前滿有人民的城， 現在何竟獨坐！ 先前在列國中為大的， 現在竟如寡婦； 先前在諸省中為王后的， 現在成為進貢的。","xiān qián mǎn yǒu rén mín de chéng， xiàn zài hé jìng dú zuò！ xiān qián zài liè guó zhōng wèi dà de， xiàn zài jìng rú guǎ fù； xiān qián zài zhū shěng zhōng wèi wáng hòu de， xiàn zài chéng wèi jìn gòng de."],[1,2,"她夜間痛哭，淚流滿腮； 在一切所親愛的中間沒有一個安慰她的。 她的朋友都以詭詐待她， 成為她的仇敵。","tā yè jiān tòng kū， lèi liú mǎn sāi； zài yī qiè suǒ qīn ài de zhōng jiān méi yǒu yī gè ān wèi tā de. tā de péng yǒu dōu yǐ guǐ zhà dài tā， chéng wèi tā de chóu dí."],[1,3,"猶大因遭遇苦難， 又因多服勞苦就遷到 外邦。 她住在列國中，尋不着安息； 追逼她的都在狹窄之地將她追上。","yóu dà yīn zāo yù kǔ nán， yòu yīn duō fú láo kǔ jiù qiān dào wài bāng. tā zhù zài liè guó zhōng， xún bù zhe ān xī； zhuī bī tā de dōu zài xiá zhǎi zhī de jiāng tā zhuī shàng."],[1,4,"錫安的路徑因無人來守聖節就悲傷； 她的城門淒涼； 她的祭司歎息； 她的處女受艱難，自己也愁苦。","xī ān de lù jìng yīn wú rén lái shǒu shèng jié jiù bēi shāng； tā de chéng mén qī liáng； tā de jì sī tàn xī； tā de chù nǚ shòu jiān nán， zì jǐ yě chóu kǔ."],[1,5,"她的敵人為首； 她的仇敵亨通； 因耶和華為她許多的罪過使她受苦； 她的孩童被敵人擄去。","tā de dí rén wèi shǒu； tā de chóu dí hēng tōng； yīn yé hé huá wèi tā xǔ duō de zuì guò shǐ tā shòu kǔ； tā de hái tóng bèi dí rén lǔ qù."],[1,6,"錫安城的威榮全都失去。 她的首領像找不着草場的鹿； 在追趕的人前無力行走。","xī ān chéng de wēi róng quán dōu shī qù. tā de shǒu lǐng xiàng zhǎo bù zhe cǎo chǎng de lù； zài zhuī gǎn de rén qián wú lì xíng zǒu."],[1,7,"耶路撒冷在困苦窘迫之時， 就追想古時一切的樂境。 她百姓落在敵人手中，無人救濟； 敵人看見，就因她的荒涼嗤笑。","yé lù sā lěng zài kùn kǔ jiǒng pò zhī shí， jiù zhuī xiǎng gǔ shí yī qiè de lè jìng. tā bǎi xìng luò zài dí rén shǒu zhōng， wú rén jiù jì； dí rén kàn jiàn， jiù yīn tā de huāng liáng chī xiào."],[1,8,"耶路撒冷大大犯罪， 所以成為不潔之物； 素來尊敬她的，見她赤露就都藐視她； 她自己也歎息退後。","yé lù sā lěng dà dà fàn zuì， suǒ yǐ chéng wèi bù jié zhī wù； sù lái zūn jìng tā de， jiàn tā chì lù jiù dōu miǎo shì tā； tā zì jǐ yě tàn xī tuì hòu."],[1,9,"她的污穢是在衣襟上； 她不思想自己的結局， 所以非常地敗落， 無人安慰她。 她說：耶和華啊，求你看我的苦難， 因為仇敵誇大。","tā de wū huì shì zài yī jīn shàng； tā bù sī xiǎng zì jǐ de jié jú， suǒ yǐ fēi cháng de bài luò， wú rén ān wèi tā. tā shuō： yé hé huá a， qiú nǐ kàn wǒ de kǔ nán， yīn wèi chóu dí kuā dà."],[1,10,"敵人伸手，奪取她的美物； 她眼見外邦人進入她的聖所－ 論這外邦人，你曾吩咐不可入你的會中。","dí rén shēn shǒu， duó qǔ tā de měi wù； tā yǎn jiàn wài bāng rén jìn rù tā de shèng suǒ－ lùn zhè wài bāng rén， nǐ céng fēn fù bù kě rù nǐ de huì zhōng."],[1,11,"她的民都歎息，尋求食物； 他們用美物換糧食，要救性命。 他們說：耶和華啊，求你觀看， 因為我甚是卑賤。","tā de mín dōu tàn xī， xún qiú shí wù； tā men yòng měi wù huàn liáng shí， yào jiù xìng mìng. tā men shuō： yé hé huá a， qiú nǐ guān kàn， yīn wèi wǒ shèn shì bēi jiàn."],[1,12,"你們一切過路的人哪，這事你們不介意嗎？ 你們要觀看： 有像這臨到我的痛苦沒有－ 就是耶和華在他發烈怒的日子使我所受的苦？","nǐ men yī qiè guò lù de rén nǎ， zhè shì nǐ men bù jiè yì ma？ nǐ men yào guān kàn： yǒu xiàng zhè lín dào wǒ de tòng kǔ méi yǒu－ jiù shì yé hé huá zài tā fā liè nù de rì zǐ shǐ wǒ suǒ shòu de kǔ？"],[1,13,"他從高天使火進入我的骨頭， 剋制了我； 他鋪下網羅，絆我的腳， 使我轉回； 他使我終日淒涼發昏。","tā cóng gāo tiān shǐ huǒ jìn rù wǒ de gǔ tóu， kēi zhì le wǒ； tā pù xià wǎng luó， bàn wǒ de jiǎo， shǐ wǒ zhuǎn huí； tā shǐ wǒ zhōng rì qī liáng fā hūn."],[1,14,"我罪過的軛是他手所綁的， 猶如軛繩縛在我頸項上； 他使我的力量衰敗。 主將我交在我所不能敵擋的人手中。","wǒ zuì guò de è shì tā shǒu suǒ bǎng de， yóu rú è shéng fù zài wǒ jǐng xiàng shàng； tā shǐ wǒ de lì liàng shuāi bài. zhǔ jiāng wǒ jiāo zài wǒ suǒ bù néng dí dǎng de rén shǒu zhōng."],[1,15,"主輕棄我中間的一切勇士， 招聚多人攻擊我， 要壓碎我的少年人。 主將 猶大居民踹下， 像在酒醡中一樣。","zhǔ qīng qì wǒ zhōng jiān de yī qiè yǒng shì， zhāo jù duō rén gōng jī wǒ， yào yā suì wǒ de shǎo nián rén. zhǔ jiāng yóu dà jū mín chuài xià， xiàng zài jiǔ zhà zhōng yī yàng."],[1,16,"我因這些事哭泣； 我眼淚汪汪； 因為那當安慰我、救我性命的， 離我甚遠。 我的兒女孤苦， 因為仇敵得了勝。","wǒ yīn zhè xiē shì kū qì； wǒ yǎn lèi wāng wāng； yīn wèi nà dāng ān wèi wǒ, jiù wǒ xìng mìng de， lí wǒ shèn yuǎn. wǒ de ér nǚ gū kǔ， yīn wèi chóu dí dé le shèng."],[1,17,"錫安舉手，無人安慰。 耶和華論 雅各已經出令， 使四圍的人作他仇敵； 耶路撒冷在他們中間像不潔之物。","xī ān jǔ shǒu， wú rén ān wèi. yé hé huá lùn yǎ gè yǐ jīng chū lìng， shǐ sì wéi de rén zuò tā chóu dí； yé lù sā lěng zài tā men zhōng jiān xiàng bù jié zhī wù."],[1,18,"耶和華是公義的！ 他這樣待我，是因我違背他的命令。 眾民哪，請聽我的話， 看我的痛苦； 我的處女和少年人都被擄去。","yé hé huá shì gōng yì de！ tā zhè yàng dài wǒ， shì yīn wǒ wéi bèi tā de mìng lìng. zhòng mín nǎ， qǐng tīng wǒ de huà， kàn wǒ de tòng kǔ； wǒ de chù nǚ hé shǎo nián rén dōu bèi lǔ qù."],[1,19,"我招呼我所親愛的， 他們卻愚弄我。 我的祭司和長老正尋求食物、救性命的時候， 就在城中絕氣。","wǒ zhāo hū wǒ suǒ qīn ài de， tā men què yú nòng wǒ. wǒ de jì sī hé zhǎng lǎo zhèng xún qiú shí wù, jiù xìng mìng de shí hòu， jiù zài chéng zhōng jué qì."],[1,20,"耶和華啊，求你觀看， 因為我在急難中。 我心腸擾亂； 我心在我裏面翻轉， 因我大大悖逆。 在外，刀劍使人喪子； 在家，猶如死亡。","yé hé huá a， qiú nǐ guān kàn， yīn wèi wǒ zài jí nán zhōng. wǒ xīn cháng rǎo luàn； wǒ xīn zài wǒ lǐ miàn fān zhuǎn， yīn wǒ dà dà bèi nì. zài wài， dāo jiàn shǐ rén sàng zǐ； zài jiā， yóu rú sǐ wáng."],[1,21,"聽見我歎息的有人； 安慰我的卻無人！ 我的仇敵都聽見我所遭的患難； 因你做這事，他們都喜樂。 你必使你報告的日子來到， 他們就像我一樣。","tīng jiàn wǒ tàn xī de yǒu rén； ān wèi wǒ de què wú rén！ wǒ de chóu dí dōu tīng jiàn wǒ suǒ zāo de huàn nán； yīn nǐ zuò zhè shì， tā men dōu xǐ lè. nǐ bì shǐ nǐ bào gào de rì zǐ lái dào， tā men jiù xiàng wǒ yī yàng."],[1,22,"願他們的惡行都呈在你面前； 你怎樣因我的一切罪過待我， 求你照樣待他們； 因我歎息甚多，心中發昏。","yuàn tā men de è xíng dōu chéng zài nǐ miàn qián； nǐ zěn yàng yīn wǒ de yī qiè zuì guò dài wǒ， qiú nǐ zhào yàng dài tā men； yīn wǒ tàn xī shèn duō， xīn zhōng fā hūn."],[2,1,"主何竟發怒，使黑雲遮蔽 錫安城！ 他將 以色列的華美從天扔在地上； 在他發怒的日子並不記念自己的腳凳。","zhǔ hé jìng fā nù， shǐ hēi yún zhē bì xī ān chéng！ tā jiāng yǐ sè liè de huá měi cóng tiān rēng zài de shàng； zài tā fā nù de rì zǐ bìng bù jì niàn zì jǐ de jiǎo dèng."],[2,2,"主吞滅 雅各一切的住處，並不顧惜。 他發怒傾覆 猶大民的保障， 使這保障坍倒在地； 他辱沒這國和其中的首領。","zhǔ tūn miè yǎ gè yī qiè de zhù chù， bìng bù gù xī. tā fā nù qīng fù yóu dà mín de bǎo zhàng， shǐ zhè bǎo zhàng tān dào zài de； tā rǔ méi zhè guó hé qí zhōng de shǒu lǐng."],[2,3,"他發烈怒，把 以色列的角全然砍斷， 在仇敵面前收回右手。 他像火焰四圍吞滅，將 雅各燒毀。","tā fā liè nù， bǎ yǐ sè liè de jiǎo quán rán kǎn duàn， zài chóu dí miàn qián shōu huí yòu shǒu. tā xiàng huǒ yàn sì wéi tūn miè， jiāng yǎ gè shāo huǐ."],[2,4,"他張弓好像仇敵； 他站着舉起右手， 如同敵人將悅人眼目的，盡行殺戮。 在 錫安百姓的帳棚上 倒出他的忿怒，像火一樣。","tā zhāng gōng hǎo xiàng chóu dí； tā zhàn zhe jǔ qǐ yòu shǒu， rú tóng dí rén jiāng yuè rén yǎn mù de， jǐn xíng shā lù. zài xī ān bǎi xìng de zhàng péng shàng dào chū tā de fèn nù， xiàng huǒ yī yàng."],[2,5,"主如仇敵吞滅 以色列和 錫安的一切宮殿， 拆毀百姓的保障； 在 猶大民中加增悲傷哭號。","zhǔ rú chóu dí tūn miè yǐ sè liè hé xī ān de yī qiè gōng diàn， chāi huǐ bǎi xìng de bǎo zhàng； zài yóu dà mín zhōng jiā zēng bēi shāng kū hào."],[2,6,"他強取自己的帳幕，好像是園中的 窩棚， 毀壞他的聚會之處。 耶和華使聖節和安息日在 錫安都被忘記， 又在怒氣的憤恨中藐視君王和祭司。","tā qiáng qǔ zì jǐ de zhàng mù， hǎo xiàng shì yuán zhōng de wō péng， huǐ huài tā de jù huì zhī chù. yé hé huá shǐ shèng jié hé ān xī rì zài xī ān dōu bèi wàng jì， yòu zài nù qì de fèn hèn zhōng miǎo shì jūn wáng hé jì sī."],[2,7,"耶和華丟棄自己的祭壇， 憎惡自己的聖所， 將宮殿的牆垣交付仇敵。 他們在耶和華的殿中喧嚷， 像在聖會之日一樣。","yé hé huá diū qì zì jǐ de jì tán， zēng è zì jǐ de shèng suǒ， jiāng gōng diàn de qiáng yuán jiāo fù chóu dí. tā men zài yé hé huá de diàn zhōng xuān rǎng， xiàng zài shèng huì zhī rì yī yàng."],[2,8,"耶和華定意拆毀 錫安的城牆； 他拉了準繩， 不將手收回，定要毀滅。 他使外郭和城牆都悲哀， 一同衰敗。","yé hé huá dìng yì chāi huǐ xī ān de chéng qiáng； tā lā le zhǔn shéng， bù jiāng shǒu shōu huí， dìng yào huǐ miè. tā shǐ wài guō hé chéng qiáng dōu bēi āi， yī tóng shuāi bài."],[2,9,"錫安的門都陷入地內； 主將她的門閂毀壞，折斷。 她的君王和首領落在沒有律法的列國中； 她的先知不得見耶和華的異象。","xī ān de mén dōu xiàn rù de nèi； zhǔ jiāng tā de mén shuān huǐ huài， zhé duàn. tā de jūn wáng hé shǒu lǐng luò zài méi yǒu lǜ fǎ de liè guó zhōng； tā de xiān zhī bù dé jiàn yé hé huá de yì xiàng."],[2,10,"錫安城的長老坐在地上默默無聲； 他們揚起塵土落在頭上，腰束麻布； 耶路撒冷的處女垂頭至地。","xī ān chéng de zhǎng lǎo zuò zài de shàng mò mò wú shēng； tā men yáng qǐ chén tǔ luò zài tóu shàng， yāo shù má bù； yé lù sā lěng de chù nǚ chuí tóu zhì de."],[2,11,"我眼中流淚，以致失明； 我的心腸擾亂，肝 膽塗地， 都因我眾民遭毀滅， 又因孩童和吃奶的在城內街上發昏。","wǒ yǎn zhōng liú lèi， yǐ zhì shī míng； wǒ de xīn cháng rǎo luàn， gān dǎn tú de， dōu yīn wǒ zhòng mín zāo huǐ miè， yòu yīn hái tóng hé chī nǎi de zài chéng nèi jiē shàng fā hūn."],[2,12,"那時，他們在城內街上發昏，好像受傷的， 在母親的懷裏，將要喪命； 對母親說：穀、酒在哪裏呢？","nà shí， tā men zài chéng nèi jiē shàng fā hūn， hǎo xiàng shòu shāng de， zài mǔ qīn de huái lǐ， jiāng yào sàng mìng； duì mǔ qīn shuō： gǔ, jiǔ zài nǎ lǐ ne？"],[2,13,"耶路撒冷的民哪，我可用甚麼向你證明呢？ 我可用甚麼與你相比呢？ 錫安的民哪，我可拿甚麼和你比較，好安慰你呢？ 因為你的裂口大如海， 誰能醫治你呢？","yé lù sā lěng de mín nǎ， wǒ kě yòng shèn me xiàng nǐ zhèng míng ne？ wǒ kě yòng shèn me yǔ nǐ xiāng bǐ ne？ xī ān de mín nǎ， wǒ kě ná shèn me hé nǐ bǐ jiào， hǎo ān wèi nǐ ne？ yīn wèi nǐ de liè kǒu dà rú hǎi， shuí néng yī zhì nǐ ne？"],[2,14,"你的先知為你見虛假和愚昧的異象， 並沒有顯露你的罪孽， 使你被擄的歸回； 卻為你見虛假的默示 和使你被趕出本境的緣故。","nǐ de xiān zhī wèi nǐ jiàn xū jiǎ hé yú mèi de yì xiàng， bìng méi yǒu xiǎn lù nǐ de zuì niè， shǐ nǐ bèi lǔ de guī huí； què wèi nǐ jiàn xū jiǎ de mò shì hé shǐ nǐ bèi gǎn chū běn jìng de yuán gù."],[2,15,"凡過路的都向你拍掌。 他們向 耶路撒冷城嗤笑，搖頭， 說： 難道人所稱為全美的， 稱為全地所喜悅的，就是這城嗎？","fán guò lù de dōu xiàng nǐ pāi zhǎng. tā men xiàng yé lù sā lěng chéng chī xiào， yáo tóu， shuō： nán dào rén suǒ chēng wèi quán měi de， chēng wèi quán de suǒ xǐ yuè de， jiù shì zhè chéng ma？"],[2,16,"你的仇敵都向你大大張口； 他們嗤笑，又切齒說： 我們吞滅她。 這真是我們所盼望的日子臨到了！ 我們親眼看見了！","nǐ de chóu dí dōu xiàng nǐ dà dà zhāng kǒu； tā men chī xiào， yòu qiè chǐ shuō： wǒ men tūn miè tā. zhè zhēn shì wǒ men suǒ pàn wàng de rì zǐ lín dào le！ wǒ men qīn yǎn kàn jiàn le！"],[2,17,"耶和華成就了他所定的， 應驗了他古時所命定的。 他傾覆了，並不顧惜， 使你的仇敵向你誇耀； 使你敵人的角也被高舉。","yé hé huá chéng jiù le tā suǒ dìng de， yīng yàn le tā gǔ shí suǒ mìng dìng de. tā qīng fù le， bìng bù gù xī， shǐ nǐ de chóu dí xiàng nǐ kuā yào； shǐ nǐ dí rén de jiǎo yě bèi gāo jǔ."],[2,18,"錫安民的心哀求主。 錫安的城牆啊，願你流淚如河， 晝夜不息； 願你眼中的瞳人淚流不止。","xī ān mín de xīn āi qiú zhǔ. xī ān de chéng qiáng a， yuàn nǐ liú lèi rú hé， zhòu yè bù xī； yuàn nǐ yǎn zhōng de tóng rén lèi liú bù zhǐ."],[2,19,"夜間，每逢交更的時候要起來呼喊， 在主面前傾心如水。 你的孩童在各市口上受餓發昏； 你要為他們的性命向主舉手禱告。","yè jiān， měi féng jiāo gèng de shí hòu yào qǐ lái hū hǎn， zài zhǔ miàn qián qīng xīn rú shuǐ. nǐ de hái tóng zài gè shì kǒu shàng shòu è fā hūn； nǐ yào wèi tā men de xìng mìng xiàng zhǔ jǔ shǒu dǎo gào."],[2,20,"耶和華啊，求你觀看！ 見你向誰這樣行？ 婦人豈可吃自己所生育手裏所搖弄的嬰孩嗎？ 祭司和先知豈可在主的聖所中被殺戮嗎？","yé hé huá a， qiú nǐ guān kàn！ jiàn nǐ xiàng shuí zhè yàng xíng？ fù rén qǐ kě chī zì jǐ suǒ shēng yù shǒu lǐ suǒ yáo nòng de yīng hái ma？ jì sī hé xiān zhī qǐ kě zài zhǔ de shèng suǒ zhōng bèi shā lù ma？"],[2,21,"少年人和老年人都在街上躺臥； 我的處女和壯丁都倒在刀下； 你發怒的日子殺死他們。 你殺了，並不顧惜。","shǎo nián rén hé lǎo nián rén dōu zài jiē shàng tǎng wò； wǒ de chù nǚ hé zhuàng dīng dōu dào zài dāo xià； nǐ fā nù de rì zǐ shā sǐ tā men. nǐ shā le， bìng bù gù xī."],[2,22,"你招聚四圍驚嚇我的， 像在大會的日子招聚 人一樣。 耶和華發怒的日子， 無人逃脫，無人存留。 我所搖弄所養育的嬰孩， 仇敵都殺淨了。","nǐ zhāo jù sì wéi jīng xià wǒ de， xiàng zài dà huì de rì zǐ zhāo jù rén yī yàng. yé hé huá fā nù de rì zǐ， wú rén táo tuō， wú rén cún liú. wǒ suǒ yáo nòng suǒ yǎng yù de yīng hái， chóu dí dōu shā jìng le."],[3,1,"我是因耶和華忿怒的杖， 遭遇困苦的人。","wǒ shì yīn yé hé huá fèn nù de zhàng， zāo yù kùn kǔ de rén."],[3,2,"他引導我，使我行在黑暗中， 不行在光明裏。","tā yǐn dǎo wǒ， shǐ wǒ xíng zài hēi àn zhōng， bù xíng zài guāng míng lǐ."],[3,3,"他真是終日再三反手攻擊我。","tā zhēn shì zhōng rì zài sān fǎn shǒu gōng jī wǒ."],[3,4,"他使我的皮肉枯乾； 他折斷我的骨頭。","tā shǐ wǒ de pí ròu kū qián； tā zhé duàn wǒ de gǔ tóu."],[3,5,"他築壘攻擊我， 用苦楚和艱難圍困我。","tā zhú lěi gōng jī wǒ， yòng kǔ chǔ hé jiān nán wéi kùn wǒ."],[3,6,"他使我住在幽暗之處， 像死了許久的人一樣。","tā shǐ wǒ zhù zài yōu àn zhī chù， xiàng sǐ le xǔ jiǔ de rén yī yàng."],[3,7,"他用籬笆圍住我，使我不能出去； 他使我的銅鍊沉重。","tā yòng lí bā wéi zhù wǒ， shǐ wǒ bù néng chū qù； tā shǐ wǒ de tóng liàn chén zhòng."],[3,8,"我哀號求救； 他使我的禱告不得上達。","wǒ āi hào qiú jiù； tā shǐ wǒ de dǎo gào bù dé shàng dá."],[3,9,"他用鑿過的石頭擋住我的道； 他使我的路彎曲。","tā yòng záo guò de shí tóu dǎng zhù wǒ de dào； tā shǐ wǒ de lù wān qū."],[3,10,"他向我如熊埋伏， 如獅子在隱密處。","tā xiàng wǒ rú xióng mái fú， rú shī zǐ zài yǐn mì chù."],[3,11,"他使我轉離正路， 將我撕碎，使我淒涼。","tā shǐ wǒ zhuǎn lí zhèng lù， jiāng wǒ sī suì， shǐ wǒ qī liáng."],[3,12,"他張弓將我當作箭靶子。","tā zhāng gōng jiāng wǒ dāng zuò jiàn bǎ zǐ."],[3,13,"他把箭袋中的箭射入我的肺腑。","tā bǎ jiàn dài zhōng de jiàn shè rù wǒ de fèi fǔ."],[3,14,"我成了眾民的笑話； 他們終日以我為歌曲。","wǒ chéng le zhòng mín de xiào huà； tā men zhōng rì yǐ wǒ wèi gē qū."],[3,15,"他用苦楚充滿我，使我飽用茵蔯。","tā yòng kǔ chǔ chōng mǎn wǒ， shǐ wǒ bǎo yòng yīn chén."],[3,16,"他又用沙石磣斷我的牙， 用灰塵將我蒙蔽。","tā yòu yòng shā shí chěn duàn wǒ de yá， yòng huī chén jiāng wǒ méng bì."],[3,17,"你使我遠離平安， 我忘記好處。","nǐ shǐ wǒ yuǎn lí píng ān， wǒ wàng jì hǎo chù."],[3,18,"我就說：我的力量衰敗； 我在耶和華那裏毫無指望！","wǒ jiù shuō： wǒ de lì liàng shuāi bài； wǒ zài yé hé huá nà lǐ háo wú zhǐ wàng！"],[3,19,"耶和華啊，求你記念我 如茵蔯和苦膽的困苦窘迫。","yé hé huá a， qiú nǐ jì niàn wǒ rú yīn chén hé kǔ dǎn de kùn kǔ jiǒng pò."],[3,20,"我心想念這些， 就在裏面憂悶。","wǒ xīn xiǎng niàn zhè xiē， jiù zài lǐ miàn yōu mèn."],[3,21,"我想起這事， 心裏就有指望。","wǒ xiǎng qǐ zhè shì， xīn lǐ jiù yǒu zhǐ wàng."],[3,22,"我們不致消滅， 是出於耶和華諸般的慈愛； 是因他的憐憫不致斷絕。","wǒ men bù zhì xiāo miè， shì chū yú yé hé huá zhū bān de cí ài； shì yīn tā de lián mǐn bù zhì duàn jué."],[3,23,"每早晨，這都是新的； 你的誠實極其廣大！","měi zǎo chén， zhè dōu shì xīn de； nǐ de chéng shí jí qí guǎng dà！"],[3,24,"我心裏說：耶和華是我的分， 因此，我要仰望他。","wǒ xīn lǐ shuō： yé hé huá shì wǒ de fēn， yīn cǐ， wǒ yào yǎng wàng tā."],[3,25,"凡等候耶和華，心裏尋求他的， 耶和華必施恩給他。","fán děng hòu yé hé huá， xīn lǐ xún qiú tā de， yé hé huá bì shī ēn gěi tā."],[3,26,"人仰望耶和華， 靜默等候他的救恩， 這原是好的。","rén yǎng wàng yé hé huá， jìng mò děng hòu tā de jiù ēn， zhè yuán shì hǎo de."],[3,27,"人在幼年負軛， 這原是好的。","rén zài yòu nián fù è， zhè yuán shì hǎo de."],[3,28,"他當獨坐無言， 因為這是耶和華加在他身上的。","tā dāng dú zuò wú yán， yīn wèi zhè shì yé hé huá jiā zài tā shēn shàng de."],[3,29,"他當口貼塵埃， 或者有指望。","tā dāng kǒu tiē chén āi， huò zhě yǒu zhǐ wàng."],[3,30,"他當由人打他的腮頰， 要滿受凌辱。","tā dāng yóu rén dǎ tā de sāi jiá， yào mǎn shòu líng rǔ."],[3,31,"因為主必不永遠丟棄人。","yīn wèi zhǔ bì bù yǒng yuǎn diū qì rén."],[3,32,"主雖使人憂愁， 還要照他諸般的慈愛發憐憫。","zhǔ suī shǐ rén yōu chóu， hái yào zhào tā zhū bān de cí ài fā lián mǐn."],[3,33,"因他並不甘心使人受苦， 使人憂愁。","yīn tā bìng bù gān xīn shǐ rén shòu kǔ， shǐ rén yōu chóu."],[3,34,"人將世上被囚的踹在腳下，","rén jiāng shì shàng bèi qiú de chuài zài jiǎo xià，"],[3,35,"或在至高者面前屈枉人，","huò zài zhì gāo zhě miàn qián qū wǎng rén，"],[3,36,"或在人的訟事上顛倒是非， 這都是主看不上的。","huò zài rén de sòng shì shàng diān dào shì fēi， zhè dōu shì zhǔ kàn bù shàng de."],[3,37,"除非主命定， 誰能說成就成呢？","chú fēi zhǔ mìng dìng， shuí néng shuō chéng jiù chéng ne？"],[3,38,"禍福不都出於至高者的口嗎？","huò fú bù dōu chū yú zhì gāo zhě de kǒu ma？"],[3,39,"活人因自己的罪受罰， 為何發怨言呢？","huó rén yīn zì jǐ de zuì shòu fá， wèi hé fā yuàn yán ne？"],[3,40,"我們當深深考察自己的行為， 再歸向耶和華。","wǒ men dāng shēn shēn kǎo chá zì jǐ de xíng wèi， zài guī xiàng yé hé huá."],[3,41,"我們當誠心向天上的神舉手禱告。","wǒ men dāng chéng xīn xiàng tiān shàng de shén jǔ shǒu dǎo gào."],[3,42,"我們犯罪背逆， 你並不赦免。","wǒ men fàn zuì bèi nì， nǐ bìng bù shè miǎn."],[3,43,"你自被怒氣遮蔽，追趕我們； 你施行殺戮，並不顧惜。","nǐ zì bèi nù qì zhē bì， zhuī gǎn wǒ men； nǐ shī xíng shā lù， bìng bù gù xī."],[3,44,"你以黑雲遮蔽自己， 以致禱告不得透入。","nǐ yǐ hēi yún zhē bì zì jǐ， yǐ zhì dǎo gào bù dé tòu rù."],[3,45,"你使我們在萬民中成為污穢和渣滓。","nǐ shǐ wǒ men zài wàn mín zhōng chéng wèi wū huì hé zhā zǐ."],[3,46,"我們的仇敵都向我們大大張口。","wǒ men de chóu dí dōu xiàng wǒ men dà dà zhāng kǒu."],[3,47,"恐懼和陷坑，殘害和毀滅， 都臨近我們。","kǒng jù hé xiàn kēng， cán hài hé huǐ miè， dōu lín jìn wǒ men."],[3,48,"因我眾民遭的毀滅， 我就眼淚下流如河。","yīn wǒ zhòng mín zāo de huǐ miè， wǒ jiù yǎn lèi xià liú rú hé."],[3,49,"我的眼多多流淚， 總不止息，","wǒ de yǎn duō duō liú lèi， zǒng bù zhǐ xī，"],[3,50,"直等耶和華垂顧， 從天觀看。","zhí děng yé hé huá chuí gù， cóng tiān guān kàn."],[3,51,"因我本城的眾民， 我的眼，使我的心傷痛。","yīn wǒ běn chéng de zhòng mín， wǒ de yǎn， shǐ wǒ de xīn shāng tòng."],[3,52,"無故與我為仇的追逼我， 像追雀鳥一樣。","wú gù yǔ wǒ wèi chóu de zhuī bī wǒ， xiàng zhuī què niǎo yī yàng."],[3,53,"他們使我的命在牢獄中斷絕， 並將一塊石頭拋在我身上。","tā men shǐ wǒ de mìng zài láo yù zhōng duàn jué， bìng jiāng yī kuài shí tóu pāo zài wǒ shēn shàng."],[3,54,"眾水流過我頭， 我說：我 命斷絕了！","zhòng shuǐ liú guò wǒ tóu， wǒ shuō： wǒ mìng duàn jué le！"],[3,55,"耶和華啊， 我從深牢中求告你的名。","yé hé huá a， wǒ cóng shēn láo zhōng qiú gào nǐ de míng."],[3,56,"你曾聽見我的聲音； 我求你解救， 你不要掩耳不聽。","nǐ céng tīng jiàn wǒ de shēng yīn； wǒ qiú nǐ jiě jiù， nǐ bù yào yǎn ěr bù tīng."],[3,57,"我求告你的日子，你臨近我， 說：不要懼怕！","wǒ qiú gào nǐ de rì zǐ， nǐ lín jìn wǒ， shuō： bù yào jù pà！"],[3,58,"主啊，你伸明了我的冤； 你救贖了我的命。","zhǔ a， nǐ shēn míng le wǒ de yuān； nǐ jiù shú le wǒ de mìng."],[3,59,"耶和華啊，你見了我受的委屈； 求你為我伸冤。","yé hé huá a， nǐ jiàn le wǒ shòu de wěi qū； qiú nǐ wèi wǒ shēn yuān."],[3,60,"他們仇恨我，謀害我， 你都看見了。","tā men chóu hèn wǒ， móu hài wǒ， nǐ dōu kàn jiàn le."],[3,61,"耶和華啊，你聽見他們辱罵我的話， 知道他們向我所設的計，","yé hé huá a， nǐ tīng jiàn tā men rǔ mà wǒ de huà， zhī dào tā men xiàng wǒ suǒ shè de jì，"],[3,62,"並那些起來攻擊我的人口中所說的話， 以及終日向我所設的計謀。","bìng nà xiē qǐ lái gōng jī wǒ de rén kǒu zhōng suǒ shuō de huà， yǐ jí zhōng rì xiàng wǒ suǒ shè de jì móu."],[3,63,"求你觀看， 他們坐下，起來，都以我為歌曲。","qiú nǐ guān kàn， tā men zuò xià， qǐ lái， dōu yǐ wǒ wèi gē qū."],[3,64,"耶和華啊，你要按着他們手所做的 向他們施行報應。","yé hé huá a， nǐ yào àn zhe tā men shǒu suǒ zuò de xiàng tā men shī xíng bào yīng."],[3,65,"你要使他們心裏剛硬， 使你的咒詛臨到他們。","nǐ yào shǐ tā men xīn lǐ gāng yìng， shǐ nǐ de zhòu zǔ lín dào tā men."],[3,66,"你要發怒追趕他們， 從耶和華的天下除滅他們。","nǐ yào fā nù zhuī gǎn tā men， cóng yé hé huá de tiān xià chú miè tā men."],[4,1,"黃金何其失光！ 純金何其變色！ 聖所的石頭倒在各市口上。","huáng jīn hé qí shī guāng！ chún jīn hé qí biàn sè！ shèng suǒ de shí tóu dào zài gè shì kǒu shàng."],[4,2,"錫安寶貴的眾子好比精金， 現在何竟算為窯匠手所做的瓦瓶？","xī ān bǎo guì de zhòng zǐ hǎo bǐ jīng jīn， xiàn zài hé jìng suàn wèi yáo jiàng shǒu suǒ zuò de wǎ píng？"],[4,3,"野狗尚且把奶乳哺其子， 我民的婦人倒成為殘忍， 好像曠野的鴕鳥一般。","yě gǒu shàng qiě bǎ nǎi rǔ bǔ qí zǐ， wǒ mín de fù rén dào chéng wèi cán rěn， hǎo xiàng kuàng yě de tuó niǎo yī bān."],[4,4,"吃奶孩子的舌頭因乾渴貼住上膛； 孩童求餅，無人擘給他們。","chī nǎi hái zǐ de shé tóu yīn qián kě tiē zhù shàng táng； hái tóng qiú bǐng， wú rén bò gěi tā men."],[4,5,"素來吃美好食物的， 現今在街上變為孤寒； 素來臥朱紅褥子的， 現今躺臥糞堆。","sù lái chī měi hǎo shí wù de， xiàn jīn zài jiē shàng biàn wèi gū hán； sù lái wò zhū hóng rù zǐ de， xiàn jīn tǎng wò fèn duī."],[4,6,"都因我眾民的罪孽比 所多瑪的罪還大； 所多瑪雖然無人加手於她， 還是轉眼之間被傾覆。","dōu yīn wǒ zhòng mín de zuì niè bǐ suǒ duō mǎ de zuì hái dà； suǒ duō mǎ suī rán wú rén jiā shǒu yú tā， hái shì zhuǎn yǎn zhī jiān bèi qīng fù."],[4,7,"錫安的貴冑素來比雪純淨， 比奶更白； 他們的身體比紅寶玉更紅， 像光潤的藍寶石一樣。","xī ān de guì zhòu sù lái bǐ xuě chún jìng， bǐ nǎi gèng bái； tā men de shēn tǐ bǐ hóng bǎo yù gèng hóng， xiàng guāng rùn de lán bǎo shí yī yàng."],[4,8,"現在他們的面貌比煤炭更黑， 以致在街上無人認識； 他們的皮膚緊貼骨頭， 枯乾如同槁木。","xiàn zài tā men de miàn mào bǐ méi tàn gèng hēi， yǐ zhì zài jiē shàng wú rén rèn shí； tā men de pí fū jǐn tiē gǔ tóu， kū qián rú tóng gǎo mù."],[4,9,"餓死的不如被刀殺的， 因為這是缺了田間的土產， 就身體衰弱，漸漸消滅。","è sǐ de bù rú bèi dāo shā de， yīn wèi zhè shì quē le tián jiān de tǔ chǎn， jiù shēn tǐ shuāi ruò， jiàn jiàn xiāo miè."],[4,10,"慈心的婦人，當我眾民被毀滅的時候， 親手煮自己的兒女作為食物。","cí xīn de fù rén， dāng wǒ zhòng mín bèi huǐ miè de shí hòu， qīn shǒu zhǔ zì jǐ de ér nǚ zuò wèi shí wù."],[4,11,"耶和華發怒成就他所定的， 倒出他的烈怒； 在 錫安使火着起， 燒毀 錫安的根基。","yé hé huá fā nù chéng jiù tā suǒ dìng de， dào chū tā de liè nù； zài xī ān shǐ huǒ zhe qǐ， shāo huǐ xī ān de gēn jī."],[4,12,"地上的君王和世上的居民都不信 敵人和仇敵能進 耶路撒冷的城門。","de shàng de jūn wáng hé shì shàng de jū mín dōu bù xìn dí rén hé chóu dí néng jìn yé lù sā lěng de chéng mén."],[4,13,"這都因她先知的罪惡和祭司的罪孽； 他們在城中流了義人的血。","zhè dōu yīn tā xiān zhī de zuì è hé jì sī de zuì niè； tā men zài chéng zhōng liú le yì rén de xuè."],[4,14,"他們在街上如瞎子亂走， 又被血玷污， 以致人不能摸他們的衣服。","tā men zài jiē shàng rú xiā zǐ luàn zǒu， yòu bèi xuè diàn wū， yǐ zhì rén bù néng mō tā men de yī fú."],[4,15,"人向他們喊着說： 不潔淨的，躲開，躲開！ 不要挨近我！ 他們逃走飄流的時候， 列國中有人說： 他們不可仍 在這裏寄居。","rén xiàng tā men hǎn zhe shuō： bù jié jìng de， duǒ kāi， duǒ kāi！ bù yào āi jìn wǒ！ tā men táo zǒu piāo liú de shí hòu， liè guó zhōng yǒu rén shuō： tā men bù kě réng zài zhè lǐ jì jū."],[4,16,"耶和華發怒，將他們分散， 不再眷顧他們； 人不重看祭司，也不厚待長老。","yé hé huá fā nù， jiāng tā men fēn sàn， bù zài juàn gù tā men； rén bù zhòng kàn jì sī， yě bù hòu dài zhǎng lǎo."],[4,17,"我們 仰望人來幫助， 以致眼目失明，還是枉然； 我們所盼望的，竟盼望一個不能救人的國！","wǒ men yǎng wàng rén lái bāng zhù， yǐ zhì yǎn mù shī míng， hái shì wǎng rán； wǒ men suǒ pàn wàng de， jìng pàn wàng yī gè bù néng jiù rén de guó！"],[4,18,"仇敵追趕我們的腳步像打獵的， 以致我們不敢在自己的街上行走。 我們的結局臨近； 我們的日子滿足； 我們的結局來到了。","chóu dí zhuī gǎn wǒ men de jiǎo bù xiàng dǎ liè de， yǐ zhì wǒ men bù gǎn zài zì jǐ de jiē shàng xíng zǒu. wǒ men de jié jú lín jìn； wǒ men de rì zǐ mǎn zú； wǒ men de jié jú lái dào le."],[4,19,"追趕我們的比空中的鷹更快； 他們在山上追逼我們， 在曠野埋伏，等候我們。","zhuī gǎn wǒ men de bǐ kōng zhōng de yīng gèng kuài； tā men zài shān shàng zhuī bī wǒ men， zài kuàng yě mái fú， děng hòu wǒ men."],[4,20,"耶和華的受膏者好比我們鼻中的氣， 在他們的坑中被捉住； 我們曾論到他說： 我們必在他蔭下， 在列國中存活。","yé hé huá de shòu gāo zhě hǎo bǐ wǒ men bí zhōng de qì， zài tā men de kēng zhōng bèi zhuō zhù； wǒ men céng lùn dào tā shuō： wǒ men bì zài tā yīn xià， zài liè guó zhōng cún huó."],[4,21,"住 烏斯地的 以東民哪，只管歡喜快樂； 苦杯也必傳到你那裏； 你必喝醉，以致露體。","zhù wū sī de de yǐ dōng mín nǎ， zhǐ guǎn huān xǐ kuài lè； kǔ bēi yě bì chuán dào nǐ nà lǐ； nǐ bì hē zuì， yǐ zhì lù tǐ."],[4,22,"錫安的民哪，你罪孽的刑罰受足了， 耶和華必不使你再被擄去。 以東的民哪，他必追討你的罪孽， 顯露你的罪惡。","xī ān de mín nǎ， nǐ zuì niè de xíng fá shòu zú le， yé hé huá bì bù shǐ nǐ zài bèi lǔ qù. yǐ dōng de mín nǎ， tā bì zhuī tǎo nǐ de zuì niè， xiǎn lù nǐ de zuì è."],[5,1,"耶和華啊，求你記念我們所遭遇的事， 觀看我們所受的凌辱。","yé hé huá a， qiú nǐ jì niàn wǒ men suǒ zāo yù de shì， guān kàn wǒ men suǒ shòu de líng rǔ."],[5,2,"我們的產業歸與外邦人； 我們的房屋歸與外路人。","wǒ men de chǎn yè guī yǔ wài bāng rén； wǒ men de fáng wū guī yǔ wài lù rén."],[5,3,"我們是無父的孤兒； 我們的母親好像寡婦。","wǒ men shì wú fù de gū ér； wǒ men de mǔ qīn hǎo xiàng guǎ fù."],[5,4,"我們出錢才得水喝； 我們的柴是人賣給我們的。","wǒ men chū qián cái dé shuǐ hē； wǒ men de chái shì rén mài gěi wǒ men de."],[5,5,"追趕我們的，到了我們的頸項上； 我們疲乏不得歇息。","zhuī gǎn wǒ men de， dào le wǒ men de jǐng xiàng shàng； wǒ men pí fá bù dé xiē xī."],[5,6,"我們投降 埃及人和 亞述人， 為要得糧吃飽。","wǒ men tóu jiàng āi jí rén hé yà shù rén， wèi yào dé liáng chī bǎo."],[5,7,"我們列祖犯罪，而今不在了； 我們擔當他們的罪孽。","wǒ men liè zǔ fàn zuì， ér jīn bù zài le； wǒ men dān dāng tā men de zuì niè."],[5,8,"奴僕轄制我們， 無人救我們脫離他們的手。","nú pú xiá zhì wǒ men， wú rén jiù wǒ men tuō lí tā men de shǒu."],[5,9,"因為曠野的刀劍， 我們冒着險才得糧食。","yīn wèi kuàng yě de dāo jiàn， wǒ men mào zhe xiǎn cái dé liáng shí."],[5,10,"因飢餓燥熱， 我們的皮膚就黑如爐。","yīn jī è zào rè， wǒ men de pí fū jiù hēi rú lú."],[5,11,"敵人在 錫安玷污婦人， 在 猶大的城邑玷污處女。","dí rén zài xī ān diàn wū fù rén， zài yóu dà de chéng yì diàn wū chù nǚ."],[5,12,"他們吊起首領的手， 也不尊敬老人的面。","tā men diào qǐ shǒu lǐng de shǒu， yě bù zūn jìng lǎo rén de miàn."],[5,13,"少年人扛磨石， 孩童背木柴，都絆跌了。","shǎo nián rén káng mó shí， hái tóng bèi mù chái， dōu bàn diē le."],[5,14,"老年人在城門口斷絕； 少年人不再作樂。","lǎo nián rén zài chéng mén kǒu duàn jué； shǎo nián rén bù zài zuò lè."],[5,15,"我們心中的快樂止息， 跳舞變為悲哀。","wǒ men xīn zhōng de kuài lè zhǐ xī， tiào wǔ biàn wèi bēi āi."],[5,16,"冠冕從我們的頭上落下； 我們犯罪了，我們有禍了！","guān miǎn cóng wǒ men de tóu shàng luò xià； wǒ men fàn zuì le， wǒ men yǒu huò le！"],[5,17,"這些事我們心裏發昏， 我們的眼睛昏花。","zhè xiē shì wǒ men xīn lǐ fā hūn， wǒ men de yǎn jīng hūn huā."],[5,18,"錫安山荒涼， 野狗行在其上。","xī ān shān huāng liáng， yě gǒu xíng zài qí shàng."],[5,19,"耶和華啊，你存到永遠； 你的寶座存到萬代。","yé hé huá a， nǐ cún dào yǒng yuǎn； nǐ de bǎo zuò cún dào wàn dài."],[5,20,"你為何永遠忘記我們？ 為何許久離棄我們？","nǐ wèi hé yǒng yuǎn wàng jì wǒ men？ wèi hé xǔ jiǔ lí qì wǒ men？"],[5,21,"耶和華啊，求你使我們向你回轉， 我們便得回轉。 求你復新我們的日子，像古時一樣。","yé hé huá a， qiú nǐ shǐ wǒ men xiàng nǐ huí zhuǎn， wǒ men biàn dé huí zhuǎn. qiú nǐ fù xīn wǒ men de rì zǐ， xiàng gǔ shí yī yàng."],[5,22,"你竟全然棄絕我們， 向我們大發烈怒？","nǐ jìng quán rán qì jué wǒ men， xiàng wǒ men dà fā liè nù？"]],"arb-vandyck":[[1,1,"كَيْفَ جَلَسَتْ وَحْدَهَا ٱلْمَدِينَةُ ٱلْكَثِيرَةُ ٱلشَّعْبِ! كَيْفَ صَارَتْ كَأَرْمَلَةٍ ٱلْعَظِيمَةُ فِي ٱلْأُمَمِ. ٱلسَّيِّدَةُ في ٱلْبُلْدَانِ صَارَتْ تَحْتَ ٱلْجِزْيَةِ!","kaẙfa jalasat̊ waḥ̊dahā ٱl̊madīnaẗu ٱl̊katẖīraẗu ٱlsẖãʿ̊bi! kaẙfa ṣārat̊ kāảr̊malaẗiⁿ ٱl̊ʿaẓīmaẗu fī ٱl̊ạủmami. ٱlsãyĩdaẗu fy ٱl̊bul̊dāni ṣārat̊ taḥ̊ta ٱl̊jiz̊yaẗi!"],[1,2,"تَبْكِي في ٱللَّيْلِ بُكَاءً، وَدُمُوعُهَا علَى خَدَّيْهَا. لَيْسَ لَهَا مُعَزٍّ مِنْ كُلِّ مُحِبِّيهَا. كُلُّ أَصْحَابِهَا غَدَرُوا بِهَا، صَارُوا لهَا أَعْدَاءً.","tab̊kī fy ٱllãẙli bukāʾaⁿ, wadumūʿuhā ʿlay̱ kẖadãẙhā. laẙsa lahā muʿaziⁿ̃ min̊ kulĩ muḥibĩyhā. kulũ ạảṣ̊ḥābihā gẖadarūạ bihā, ṣārūạ lhā ạảʿ̊dāʾaⁿ."],[1,3,"قَد سُبِيَتْ يَهُوذَا مِنَ ٱلْمَذَلَّةِ وَمِنْ كَثْرَةِ ٱلْعُبُودِيَّةِ. هِيَ تَسْكُنُ بَيْنَ ٱلْأُمَمِ. لَا تَجِدُ رَاحَةً. قَدْ أَدْرَكَهَا كُلُّ طَارِدِيهَا بَيْنَ ٱلضِّيقَاتِ.","qad subīat̊ yahūdẖā mina ٱl̊madẖalãẗi wamin̊ katẖ̊raẗi ٱl̊ʿubūdīãẗi. hīa tas̊kunu baẙna ٱl̊ạủmami. lā tajidu rāḥaẗaⁿ. qad̊ ạảd̊rakahā kulũ ṭāridīhā baẙna ٱlḍĩyqāti."],[1,4,"طُرُقُ صِهْيَوْنَ نَائِحَةٌ لِعَدَمِ ٱلْآتِينَ إِلَى ٱلْعِيدِ. كُلُّ أَبْوَابِهَا خَرِبَةٌ. كَهَنَتُهَا يَتَنَهَّدُونَ. عَذَارَاهَا مُذَلَّلَةٌ وَهِيَ فِي مَرَارَةٍ.","ṭuruqu ṣih̊yaẘna nāyỉḥaẗuⁿ liʿadami ٱl̊ậtīna ại̹lay̱ ٱl̊ʿīdi. kulũ ạảb̊wābihā kẖaribaẗuⁿ. kahanatuhā yatanahãdūna. ʿadẖārāhā mudẖalãlaẗuⁿ wahīa fī marāraẗiⁿ."],[1,5,"صَارَ مُضَايِقُوهَا رَأْسًا. نَجَحَ أَعْدَاؤُهَا لِأَنَّ ٱلرَّبَّ قَدْ أَذَلَّهَا لِأَجْلِ كَثْرَةِ ذُنُوبِهَا. ذَهَبَ أَوْلَادُهَا إِلَى ٱلسَّبْيِ قُدَّامَ ٱلْعَدُوِّ.","ṣāra muḍāyiqūhā rā̊̉saⁿạ. najaḥa ạảʿ̊dāwủhā liạảnã ٱlrãbã qad̊ ạảdẖalãhā liạảj̊li katẖ̊raẗi dẖunūbihā. dẖahaba ạảẘlāduhā ại̹lay̱ ٱlsãb̊yi qudãạma ٱl̊ʿadūĩ."],[1,6,"وَقَدْ خَرَجَ مِنْ بِنْتِ صِهْيَوْنَ كُلُّ بَهَائِهَا. صَارَتْ رُؤَسَاؤُهَا كَأَيَائِلَ لَا تَجِدُ مَرْعًى، فَيَسِيرُونَ بِلَا قُوَّةٍ أَمَامَ ٱلطَّارِدِ.","waqad̊ kẖaraja min̊ bin̊ti ṣih̊yaẘna kulũ bahāyỉhā. ṣārat̊ rūảsāwủhā kāảyāyỉla lā tajidu mar̊ʿaⁿy̱, fayasīrūna bilā qūãẗiⁿ ạảmāma ٱlṭãạridi."],[1,7,"قَدْ ذَكَرَتْ أُورُشَلِيمُ فِي أَيَّامِ مَذَلَّتِهَا وَتَطَوُّحِهَا كُلَّ مُشْتَهَيَاتِهَا ٱلَّتِي كَانَتْ فِي أَيَّامِ ٱلْقِدَمِ. عِنْدَ سُقُوطِ شَعْبِهَا بِيَدِ ٱلْعَدُوِّ وَلَيْسَ مَنْ يُسَاعِدُهَا. رَأَتْهَا ٱلْأَعْدَاءُ. ضَحِكُوا عَلَى هَلَاكِهَا.","qad̊ dẖakarat̊ ạủwrusẖalīmu fī ạảyãạmi madẖalãtihā wataṭawũḥihā kulã musẖ̊tahayātihā ٱlãtī kānat̊ fī ạảyãạmi ٱl̊qidami. ʿin̊da suqūṭi sẖaʿ̊bihā bīadi ٱl̊ʿadūĩ walaẙsa man̊ yusāʿiduhā. rāảt̊hā ٱl̊ạảʿ̊dāʾu. ḍaḥikūạ ʿalay̱ halākihā."],[1,8,"قَدْ أَخْطَأَتْ أُورُشَلِيمُ خَطِيَّةً، مِنْ أَجْلِ ذَلِكَ صَارَتْ رَجِسَةً. كُلُّ مُكَرِّمِيهَا يَحْتَقِرُونَهَا لِأَنَّهُمْ رَأَوْا عَوْرَتَهَا، وَهِيَ أَيْضًا تَتَنَهَّدُ وَتَرْجِعُ إِلَى ٱلْوَرَاءِ.","qad̊ ạảkẖ̊ṭāảt̊ ạủwrusẖalīmu kẖaṭīãẗaⁿ, min̊ ạảj̊li dẖalika ṣārat̊ rajisaẗaⁿ. kulũ mukarĩmīhā yaḥ̊taqirūnahā liạảnãhum̊ rāảẘạ ʿaẘratahā, wahīa ạảẙḍaⁿạ tatanahãdu watar̊jiʿu ại̹lay̱ ٱl̊warāʾi."],[1,9,"نَجَاسَتُهَا فِي أَذْيَالِهَا. لَمْ تَذْكُرْ آخِرَتَهَا وَقَدِ ٱنْحَطَّتِ ٱنْحِطَاطًا عَجِيبًا. لَيْسَ لَهَا مُعَزٍّ. «ٱنْظُرْ يَارَبُّ إِلَى مَذَلَّتِي لِأَنَّ ٱلْعَدُوَّ قَدْ تَعَظَّمَ».","najāsatuhā fī ạảdẖ̊yālihā. lam̊ tadẖ̊kur̊ ậkẖiratahā waqadi ٱn̊ḥaṭãti ٱn̊ḥiṭāṭaⁿạ ʿajībaⁿạ. laẙsa lahā muʿaziⁿ̃. «ٱn̊ẓur̊ yārabũ ại̹lay̱ madẖalãtī liạảnã ٱl̊ʿadūã qad̊ taʿaẓãma»."],[1,10,"بَسَطَ ٱلْعَدُوُّ يَدَهُ عَلَى كُلِّ مُشْتَهَيَاتِهَا، فَإِنَّهَا رَأَتِ ٱلْأُمَمَ دَخَلُوا مَقْدِسَهَا، ٱلَّذِينَ أَمَرْتَ أَنْ لَا يَدْخُلُوا فِي جَمَاعَتِكَ.","basaṭa ٱl̊ʿadūũ yadahu ʿalay̱ kulĩ musẖ̊tahayātihā, fāi̹nãhā rāảti ٱl̊ạủmama dakẖalūạ maq̊disahā, ٱlãdẖīna ạảmar̊ta ạản̊ lā yad̊kẖulūạ fī jamāʿatika."],[1,11,"كُلُّ شَعْبِهَا يَتَنَهَّدُونَ، يَطْلُبُونَ خُبْزًا. دَفَعُوا مُشْتَهَيَاتِهِمْ لِلْأَكْلِ لِأَجْلِ رَدِّ ٱلنَّفْسِ. «ٱنْظُرْ يَارَبُّ وَتَطَلَّعْ لِأَنِّي قَدْ صِرْتُ مُحْتَقَرَةً».","kulũ sẖaʿ̊bihā yatanahãdūna, yaṭ̊lubūna kẖub̊zaⁿạ. dafaʿūạ musẖ̊tahayātihim̊ lil̊ạảk̊li liạảj̊li radĩ ٱlnãf̊si. «ٱn̊ẓur̊ yārabũ wataṭalãʿ̊ liạảnĩy qad̊ ṣir̊tu muḥ̊taqaraẗaⁿ»."],[1,12,"«أَمَا إِلَيْكُمْ يَا جَمِيعَ عَابِرِي ٱلطَّرِيقِ؟ تَطَلَّعُوا وَٱنْظُرُوا إِنْ كَانَ حُزْنٌ مِثْلُ حُزْنِي ٱلَّذِي صُنِعَ بِي، ٱلَّذِي أَذَلَّنِي بِهِ ٱلرَّبُّ يَوْمَ حُمُوِّ غَضَبِهِ؟","«ạảmā ại̹laẙkum̊ yā jamīʿa ʿābirī ٱlṭãrīqi? taṭalãʿūạ waٱn̊ẓurūạ ại̹n̊ kāna ḥuz̊nuⁿ mitẖ̊lu ḥuz̊nī ٱlãdẖī ṣuniʿa bī, ٱlãdẖī ạảdẖalãnī bihi ٱlrãbũ yaẘma ḥumūĩ gẖaḍabihi?"],[1,13,"مِنَ ٱلْعَلَاءِ أَرْسَلَ نَارًا إِلَى عِظَامِي فَسَرَتْ فِيهَا. بَسَطَ شَبَكَةً لِرِجْلَيَّ. رَدَّنِي إِلَى ٱلْوَرَاءِ. جَعَلَنِي خَرِبَةً. ٱلْيَوْمَ كُلَّهُ مَغْمُومَةً.","mina ٱl̊ʿalāʾi ạảr̊sala nāraⁿạ ại̹lay̱ ʿiẓāmī fasarat̊ fīhā. basaṭa sẖabakaẗaⁿ lirij̊layã. radãnī ại̹lay̱ ٱl̊warāʾi. jaʿalanī kẖaribaẗaⁿ. ٱl̊yaẘma kulãhu magẖ̊mūmaẗaⁿ."],[1,14,"شَدَّ نِيرَ ذُنُوبِي بِيَدِهِ، ضُفِرَتْ، صَعِدَتْ عَلَى عُنُقِي. نَزَعَ قُوَّتِي. دَفَعَنِي ٱلسَّيِّدُ إِلَى أَيْدٍ لَا أَسْتَطِيعُ ٱلْقِيَامَ مِنْهَا.","sẖadã nīra dẖunūbī bīadihi, ḍufirat̊, ṣaʿidat̊ ʿalay̱ ʿunuqī. nazaʿa qūãtī. dafaʿanī ٱlsãyĩdu ại̹lay̱ ạảẙdiⁿ lā ạảs̊taṭīʿu ٱl̊qīāma min̊hā."],[1,15,"رَذَلَ ٱلسَّيِّدُ كُلَّ مُقْتَدِرِيَّ فِي وَسَطِي. دَعَا عَلَيَّ جَمَاعَةً لِحَطْمِ شُبَّانِي. دَاسَ ٱلسَّيِّدُ ٱلْعَذْرَاءَ بِنْتَ يَهُوذَا مِعْصَرَةً.","radẖala ٱlsãyĩdu kulã muq̊tadirīã fī wasaṭī. daʿā ʿalayã jamāʿaẗaⁿ liḥaṭ̊mi sẖubãạnī. dāsa ٱlsãyĩdu ٱl̊ʿadẖ̊rāʾa bin̊ta yahūdẖā miʿ̊ṣaraẗaⁿ."],[1,16,"عَلَى هَذِهِ أَنَا بَاكِيَةٌ. عَيْنِي، عَيْنِي تَسْكُبُ مِيَاهًا لِأَنَّهُ قَدِ ٱبْتَعَدَ عَنِّي ٱلْمُعَزِّي، رَادُّ نَفْسِي. صَارَ بَنِيَّ هَالِكِينَ لِأَنَّهُ قَدْ تَجَبَّرَ ٱلْعَدُوُّ».","ʿalay̱ hadẖihi ạảnā bākīaẗuⁿ. ʿaẙnī, ʿaẙnī tas̊kubu mīāhaⁿạ liạảnãhu qadi ٱb̊taʿada ʿanĩy ٱl̊muʿazĩy, rādũ naf̊sī. ṣāra banīã hālikīna liạảnãhu qad̊ tajabãra ٱl̊ʿadūũ»."],[1,17,"بَسَطَتْ صِهْيَوْنُ يَدَيْهَا. لَا مُعَزِّيَ لَهَا. أَمَرَ ٱلرَّبُّ عَلَى يَعْقُوبَ أَنْ يَكُونَ مُضَايِقُوهُ حَوَالَيْهِ. صَارَتْ أُورُشَلِيمُ نَجِسَةً بَيْنَهُمْ.","basaṭat̊ ṣih̊yaẘnu yadaẙhā. lā muʿazĩya lahā. ạảmara ٱlrãbũ ʿalay̱ yaʿ̊qūba ạản̊ yakūna muḍāyiqūhu ḥawālaẙhi. ṣārat̊ ạủwrusẖalīmu najisaẗaⁿ baẙnahum̊."],[1,18,"«بَارٌّ هُوَ ٱلرَّبُّ لِأَنِّي قَدْ عَصَيْتُ أَمْرَهُ. ٱسْمَعُوا يَا جَمِيعَ ٱلشُّعُوبِ وَٱنْظُرُوا إِلَى حُزْنِي. عَذَارَايَ وَشُبَّانِي ذَهَبُوا إِلَى ٱلسَّبْيِ.","«bāruⁿ̃ hūa ٱlrãbũ liạảnĩy qad̊ ʿaṣaẙtu ạảm̊rahu. ٱs̊maʿūạ yā jamīʿa ٱlsẖũʿūbi waٱn̊ẓurūạ ại̹lay̱ ḥuz̊nī. ʿadẖārāya wasẖubãạnī dẖahabūạ ại̹lay̱ ٱlsãb̊yi."],[1,19,"نَادَيْتُ مُحِبِّيَّ. هُمْ خَدَعُونِي. كَهَنَتِي وَشُيُوخِي فِي ٱلْمَدِينَةِ مَاتُوا، إِذْ طَلَبُوا لِذَوَاتِهِمْ طَعَامًا لِيَرُدُّوا أَنْفُسَهُمْ.","nādaẙtu muḥibĩyã. hum̊ kẖadaʿūnī. kahanatī wasẖuyūkẖī fī ٱl̊madīnaẗi mātūạ, ại̹dẖ̊ ṭalabūạ lidẖawātihim̊ ṭaʿāmaⁿạ līarudũwạ ạản̊fusahum̊."],[1,20,"ٱنْظُرْ يَارَبُّ، فَإِنِّي فِي ضِيقٍ! أَحْشَائِي غَلَتْ. ٱرْتَدَّ قَلْبِي فِي بَاطِنِي لِأَنِّي قَدْ عَصَيْتُ مُتَمَرِّدَةً. فِي ٱلْخَارِجِ يَثْكُلُ ٱلسَّيْفُ، وَفِي ٱلْبَيْتِ مِثْلُ ٱلْمَوْتِ.","ٱn̊ẓur̊ yārabũ, fāi̹nĩy fī ḍīqiⁿ! ạảḥ̊sẖāyỉy gẖalat̊. ٱr̊tadã qal̊bī fī bāṭinī liạảnĩy qad̊ ʿaṣaẙtu mutamarĩdaẗaⁿ. fī ٱl̊kẖāriji yatẖ̊kulu ٱlsãẙfu, wafī ٱl̊baẙti mitẖ̊lu ٱl̊maẘti."],[1,21,"سَمِعُوا أَنِّي تَنَهَّدْتُ. لَا مُعَزِّيَ لِي. كُلُّ أَعْدَائِي سَمِعُوا بِبَلِيَّتِي. فَرِحُوا لِأَنَّكَ فَعَلْتَ. تَأْتِي بِٱلْيَوْمِ ٱلَّذِي نَادَيْتَ بِهِ فَيَصِيرُونَ مِثْلِي.","samiʿūạ ạảnĩy tanahãd̊tu. lā muʿazĩya lī. kulũ ạảʿ̊dāyỉy samiʿūạ bibalīãtī. fariḥūạ liạảnãka faʿal̊ta. tā̊̉tī biٱl̊yaẘmi ٱlãdẖī nādaẙta bihi fayaṣīrūna mitẖ̊lī."],[1,22,"لِيَأْتِ كُلُّ شَرِّهِمْ أَمَامَكَ. وَٱفْعَلْ بِهِمْ كَمَا فَعَلْتَ بِي مِنْ أَجْلِ كُلِّ ذُنُوبِي، لِأَنَّ تَنَهُّدَاتِي كَثِيرَةٌ وَقَلْبِي مَغْشِيٌّ عَلَيْهِ».","līā̊̉ti kulũ sẖarĩhim̊ ạảmāmaka. waٱf̊ʿal̊ bihim̊ kamā faʿal̊ta bī min̊ ạảj̊li kulĩ dẖunūbī, liạảnã tanahũdātī katẖīraẗuⁿ waqal̊bī magẖ̊sẖīuⁿ̃ ʿalaẙhi»."],[2,1,"كَيْفَ غَطَّى ٱلسَّيِّدُ بِغَضَبِهِ ٱبْنَةَ صِهْيَوْنَ بِٱلظَّلَامِ! أَلْقَى مِنَ ٱلسَّمَاءِ إِلَى ٱلْأَرْضِ فَخْرَ إِسْرَائِيلَ، وَلَمْ يَذْكُرْ مَوْطِئَ قَدَمَيْهِ فِي يَوْمِ غَضَبِهِ.","kaẙfa gẖaṭãy̱ ٱlsãyĩdu bigẖaḍabihi ٱb̊naẗa ṣih̊yaẘna biٱlẓãlāmi! ạảl̊qay̱ mina ٱlsãmāʾi ại̹lay̱ ٱl̊ạảr̊ḍi fakẖ̊ra ại̹s̊rāyỉyla, walam̊ yadẖ̊kur̊ maẘṭīả qadamaẙhi fī yaẘmi gẖaḍabihi."],[2,2,"ٱبْتَلَعَ ٱلسَّيِّدُ وَلَمْ يَشْفِقْ كُلَّ مَسَاكِنِ يَعْقُوبَ. نَقَضَ بِسَخَطِهِ حُصُونَ بِنْتِ يَهُوذَا. أَوْصَلَهَا إِلَى ٱلْأَرْضِ. نَجَّسَ ٱلْمَمْلَكَةَ وَرُؤَسَاءَهَا.","ٱb̊talaʿa ٱlsãyĩdu walam̊ yasẖ̊fiq̊ kulã masākini yaʿ̊qūba. naqaḍa bisakẖaṭihi ḥuṣūna bin̊ti yahūdẖā. ạảẘṣalahā ại̹lay̱ ٱl̊ạảr̊ḍi. najãsa ٱl̊mam̊lakaẗa warūảsāʾahā."],[2,3,"عَضَبَ بِحُمُوِّ غَضَبِهِ كُلَّ قَرْنٍ لِإِسْرَائِيلَ. رَدَّ إِلَى ٱلْوَرَاءِ يَمِينَهُ أَمَامَ ٱلْعَدُوِّ، وَٱشْتَعَلَ فِي يَعْقُوبَ مِثْلَ نَارٍ مُلْتَهِبَةٍ تَأْكُلُ مَا حَوَالَيْهَا.","ʿaḍaba biḥumūĩ gẖaḍabihi kulã qar̊niⁿ liại̹s̊rāyỉyla. radã ại̹lay̱ ٱl̊warāʾi yamīnahu ạảmāma ٱl̊ʿadūĩ, waٱsẖ̊taʿala fī yaʿ̊qūba mitẖ̊la nāriⁿ mul̊tahibaẗiⁿ tā̊̉kulu mā ḥawālaẙhā."],[2,4,"مَدَّ قَوْسَهُ كَعَدُوٍّ. نَصَبَ يَمِينَهُ كَمُبْغِضٍ وَقَتَلَ كُلَّ مُشْتَهَيَاتِ ٱلْعَيْنِ فِي خِبَاءِ بِنْتِ صِهْيَوْنَ. سَكَبَ كَنَارٍ غَيْظَهُ.","madã qaẘsahu kaʿadūiⁿ̃. naṣaba yamīnahu kamub̊gẖiḍiⁿ waqatala kulã musẖ̊tahayāti ٱl̊ʿaẙni fī kẖibāʾi bin̊ti ṣih̊yaẘna. sakaba kanāriⁿ gẖaẙẓahu."],[2,5,"صَارَ ٱلسَّيِّدُ كَعَدُوٍّ. ٱبْتَلَعَ إِسْرَائِيلَ. ٱبْتَلَعَ كُلَّ قُصُورِهِ. أَهْلَكَ حُصُونَهُ، وَأَكْثَرَ فِي بِنْتِ يَهُوذَا ٱلنَّوْحَ وَٱلْحُزْنَ.","ṣāra ٱlsãyĩdu kaʿadūiⁿ̃. ٱb̊talaʿa ại̹s̊rāyỉyla. ٱb̊talaʿa kulã quṣūrihi. ạảh̊laka ḥuṣūnahu, wāảk̊tẖara fī bin̊ti yahūdẖā ٱlnãẘḥa waٱl̊ḥuz̊na."],[2,6,"وَنَزَعَ كَمَا مِنْ جَنَّةٍ مَظَلَّتَهُ. أَهْلَكَ مُجْتَمَعَهُ. أَنْسَى ٱلرَّبُّ فِي صِهْيَوْنَ ٱلْمَوْسِمَ وَٱلسَّبْتَ، وَرَذَلَ بِسَخَطِ غَضَبِهِ ٱلْمَلِكَ وَٱلْكَاهِنَ.","wanazaʿa kamā min̊ janãẗiⁿ maẓalãtahu. ạảh̊laka muj̊tamaʿahu. ạản̊say̱ ٱlrãbũ fī ṣih̊yaẘna ٱl̊maẘsima waٱlsãb̊ta, waradẖala bisakẖaṭi gẖaḍabihi ٱl̊malika waٱl̊kāhina."],[2,7,"كَرِهَ ٱلسَّيِّدُ مَذْبَحَهُ. رَذَلَ مَقْدِسَهُ. حَصَرَ فِي يَدِ ٱلْعَدُوِّ أَسْوَارَ قُصُورِهَا. أَطْلَقُوا ٱلصَّوْتَ فِي بَيْتِ ٱلرَّبِّ كَمَا فِي يَوْمِ ٱلْمَوْسِمِ.","kariha ٱlsãyĩdu madẖ̊baḥahu. radẖala maq̊disahu. ḥaṣara fī yadi ٱl̊ʿadūĩ ạảs̊wāra quṣūrihā. ạảṭ̊laqūạ ٱlṣãẘta fī baẙti ٱlrãbĩ kamā fī yaẘmi ٱl̊maẘsimi."],[2,8,"قَصَدَ ٱلرَّبُّ أَنْ يُهْلِكَ سُورَ بِنْتِ صِهْيَوْنَ. مَدَّ ٱلْمِطْمَارَ. لَمْ يَرْدُدْ يَدَهُ عَنِ ٱلْإِهْلَاكِ، وَجَعَلَ ٱلْمِتْرَسَةَ وَٱلسُّورَ يَنُوحَانِ. قَدْ حَزِنَا مَعًا.","qaṣada ٱlrãbũ ạản̊ yuh̊lika sūra bin̊ti ṣih̊yaẘna. madã ٱl̊miṭ̊māra. lam̊ yar̊dud̊ yadahu ʿani ٱl̊ại̹h̊lāki, wajaʿala ٱl̊mit̊rasaẗa waٱlsũwra yanūḥāni. qad̊ ḥazinā maʿaⁿạ."],[2,9,"تَاخَتْ فِي ٱلْأَرْضِ أَبْوَابُهَا. أَهْلَكَ وَحَطَّمَ عَوَارِضَهَا. مَلِكُهَا وَرُؤَسَاؤُهَا بَيْنَ ٱلْأُمَمِ. لَا شَرِيعَةَ. أَنْبِيَاؤُهَا أَيْضًا لَا يَجِدُونَ رُؤْيَا مِنْ قِبَلِ ٱلرَّبِّ.","tākẖat̊ fī ٱl̊ạảr̊ḍi ạảb̊wābuhā. ạảh̊laka waḥaṭãma ʿawāriḍahā. malikuhā warūảsāwủhā baẙna ٱl̊ạủmami. lā sẖarīʿaẗa. ạản̊bīāwủhā ạảẙḍaⁿạ lā yajidūna rū̊̉yā min̊ qibali ٱlrãbĩ."],[2,10,"شُيُوخُ بِنْتِ صِهْيَوْنَ يَجْلِسُونَ عَلَى ٱلْأَرْضِ سَاكِتِينَ. يَرْفَعُونَ ٱلتُّرَابَ عَلَى رُؤُوسِهِمْ. يَتَنَطَّقُونَ بِٱلْمُسُوحِ. تَحْنِي عَذَارَى أُورُشَلِيمَ رُؤُوسَهُنَّ إِلَى ٱلْأَرْضِ.","sẖuyūkẖu bin̊ti ṣih̊yaẘna yaj̊lisūna ʿalay̱ ٱl̊ạảr̊ḍi sākitīna. yar̊faʿūna ٱltũrāba ʿalay̱ rūủwsihim̊. yatanaṭãqūna biٱl̊musūḥi. taḥ̊nī ʿadẖāray̱ ạủwrusẖalīma rūủwsahunã ại̹lay̱ ٱl̊ạảr̊ḍi."],[2,11,"كَلَّتْ مِنَ ٱلدُّمُوعِ عَيْنَايَ. غَلَتْ أَحْشَائِي. ٱنْسَكَبَتْ عَلَى ٱلْأَرْضِ كَبِدِي عَلَى سَحْقِ بِنْتِ شَعْبِي، لِأَجْلِ غَشَيَانِ ٱلْأَطْفَالِ وَٱلرُّضَّعِ فِي سَاحَاتِ ٱلْقَرْيَةِ.","kalãt̊ mina ٱldũmūʿi ʿaẙnāya. gẖalat̊ ạảḥ̊sẖāyỉy. ٱn̊sakabat̊ ʿalay̱ ٱl̊ạảr̊ḍi kabidī ʿalay̱ saḥ̊qi bin̊ti sẖaʿ̊bī, liạảj̊li gẖasẖayāni ٱl̊ạảṭ̊fāli waٱlrũḍãʿi fī sāḥāti ٱl̊qar̊yaẗi."],[2,12,"يَقُولُونَ لِأُمَّهَاتِهِمْ: «أَيْنَ ٱلْحِنْطَةُ وَٱلْخَمْرُ؟» إِذْ يُغْشَى عَلَيْهِمْ كَجَرِيحٍ فِي سَاحَاتِ ٱلْمَدِينَةِ، إِذْ تُسْكَبُ نَفْسُهُمْ فِي أَحْضَانِ أُمَّهَاتِهِمْ.","yaqūlūna liạủmãhātihim̊: «ạảẙna ٱl̊ḥin̊ṭaẗu waٱl̊kẖam̊ru?» ại̹dẖ̊ yugẖ̊sẖay̱ ʿalaẙhim̊ kajarīḥiⁿ fī sāḥāti ٱl̊madīnaẗi, ại̹dẖ̊ tus̊kabu naf̊suhum̊ fī ạảḥ̊ḍāni ạủmãhātihim̊."],[2,13,"بِمَاذَا أُنْذِرُكِ؟ بِمَاذَا أُحَذِّرُكِ؟ بِمَاذَا أُشَبِّهُكِ يَا ٱبْنَةَ أُورُشَلِيمَ؟ بِمَاذَا أُقَايِسُكِ فَأُعَزِّيكِ أَيَّتُهَا ٱلْعَذْرَاءُ بِنْتَ صِهْيَوْنَ؟ لِأَنَّ سَحْقَكِ عَظِيمٌ كَٱلْبَحْرِ. مَنْ يَشْفِيكِ؟","bimādẖā ạủn̊dẖiruki? bimādẖā ạủḥadẖĩruki? bimādẖā ạủsẖabĩhuki yā ٱb̊naẗa ạủwrusẖalīma? bimādẖā ạủqāyisuki fāủʿazĩyki ạảyãtuhā ٱl̊ʿadẖ̊rāʾu bin̊ta ṣih̊yaẘna? liạảnã saḥ̊qaki ʿaẓīmuⁿ kaٱl̊baḥ̊ri. man̊ yasẖ̊fīki?"],[2,14,"أَنْبِيَاؤُكِ رَأَوْا لَكِ كَذِبًا وَبَاطِلًا، وَلَمْ يُعْلِنُوا إِثْمَكِ لِيَرُدُّوا سَبْيَكِ، بَلْ رَأَوْا لَكِ وَحْيًا كَاذِبًا وَطَوَائِحَ.","ạản̊bīāwủki rāảẘạ laki kadẖibaⁿạ wabāṭilaⁿạ, walam̊ yuʿ̊linūạ ại̹tẖ̊maki līarudũwạ sab̊yaki, bal̊ rāảẘạ laki waḥ̊yaⁿạ kādẖibaⁿạ waṭawāyỉḥa."],[2,15,"يُصَفِّقُ عَلَيْكِ بِٱلْأَيَادِي كُلُّ عَابِرِي ٱلطَّرِيقِ. يَصْفِرُونَ وَيَنْغُضُونَ رُؤُوسَهُمْ عَلَى بِنْتِ أُورُشَلِيمَ قَائِلِينَ: «أَهَذِهِ هِيَ ٱلْمَدِينَةُ ٱلَّتِي يَقُولُونَ إِنَّهَا كَمَالُ ٱلْجَمَالِ، بَهْجَةُ كُلِّ ٱلْأَرْضِ؟»","yuṣafĩqu ʿalaẙki biٱl̊ạảyādī kulũ ʿābirī ٱlṭãrīqi. yaṣ̊firūna wayan̊gẖuḍūna rūủwsahum̊ ʿalay̱ bin̊ti ạủwrusẖalīma qāyỉlīna: «ạảhadẖihi hīa ٱl̊madīnaẗu ٱlãtī yaqūlūna ại̹nãhā kamālu ٱl̊jamāli, bah̊jaẗu kulĩ ٱl̊ạảr̊ḍi?»"],[2,16,"يَفْتَحُ عَلَيْكِ أَفْوَاهَهُمْ كُلُّ أَعْدَائِكِ. يَصْفِرُونَ وَيَحْرِقُونَ ٱلْأَسْنَانَ. يَقُولُونَ: «قَدْ أَهْلَكْنَاهَا. حَقًّا إِنَّ هَذَا ٱلْيَوْمَ ٱلَّذِي رَجَوْنَاهُ. قَدْ وَجَدْنَاهُ! قَدْ رَأَيْنَاهُ».","yaf̊taḥu ʿalaẙki ạảf̊wāhahum̊ kulũ ạảʿ̊dāyỉki. yaṣ̊firūna wayaḥ̊riqūna ٱl̊ạảs̊nāna. yaqūlūna: «qad̊ ạảh̊lak̊nāhā. ḥaqaⁿ̃ạ ại̹nã hadẖā ٱl̊yaẘma ٱlãdẖī rajaẘnāhu. qad̊ wajad̊nāhu! qad̊ rāảẙnāhu»."],[2,17,"فَعَلَ ٱلرَّبُّ مَا قَصَدَ. تَمَّمَ قَوْلَهُ ٱلَّذِي أَوْعَدَ بِهِ مُنْذُ أَيَّامِ ٱلْقِدَمِ. قَدْ هَدَمَ وَلَمْ يَشْفِقْ وَأَشْمَتَ بِكِ ٱلْعَدُوَّ. نَصَبَ قَرْنَ أَعْدَائِكِ.","faʿala ٱlrãbũ mā qaṣada. tamãma qaẘlahu ٱlãdẖī ạảẘʿada bihi mun̊dẖu ạảyãạmi ٱl̊qidami. qad̊ hadama walam̊ yasẖ̊fiq̊ wāảsẖ̊mata biki ٱl̊ʿadūã. naṣaba qar̊na ạảʿ̊dāyỉki."],[2,18,"صَرَخَ قَلْبُهُمْ إِلَى ٱلسَّيِّدِ. يَا سُورَ بِنْتِ صِهْيَوْنَ ٱسْكُبِي ٱلدَّمْعَ كَنَهْرٍ نَهَارًا وَلَيْلًا. لَا تُعْطِي ذَاتَكِ رَاحَةً. لَا تَكُفَّ حَدَقَةُ عَيْنِكِ.","ṣarakẖa qal̊buhum̊ ại̹lay̱ ٱlsãyĩdi. yā sūra bin̊ti ṣih̊yaẘna ٱs̊kubī ٱldãm̊ʿa kanah̊riⁿ nahāraⁿạ walaẙlaⁿạ. lā tuʿ̊ṭī dẖātaki rāḥaẗaⁿ. lā takufã ḥadaqaẗu ʿaẙniki."],[2,19,"قُومِي ٱهْتِفِي فِي ٱللَّيْلِ فِي أَوَّلِ ٱلْهُزُعِ. ٱسْكُبِي كَمِيَاهٍ قَلْبَكِ قُبَالَةَ وَجْهِ ٱلسَّيِّدِ. ٱرْفَعِي إِلَيْهِ يَدَيْكِ لِأَجْلِ نَفْسِ أَطْفَالِكِ ٱلْمَغْشِيِّ عَلَيْهِمْ مِنَ ٱلْجُوعِ فِي رَأْسِ كُلِّ شَارِعٍ.","qūmī ٱh̊tifī fī ٱllãẙli fī ạảwãli ٱl̊huzuʿi. ٱs̊kubī kamīāhiⁿ qal̊baki qubālaẗa waj̊hi ٱlsãyĩdi. ٱr̊faʿī ại̹laẙhi yadaẙki liạảj̊li naf̊si ạảṭ̊fāliki ٱl̊magẖ̊sẖīĩ ʿalaẙhim̊ mina ٱl̊jūʿi fī rā̊̉si kulĩ sẖāriʿiⁿ."],[2,20,"«اُنْظُرْ يَارَبُّ وَتَطَلَّعْ بِمَنْ فَعَلْتَ هَكَذَا؟ أَتَأْكُلُ ٱلنِّسَاءُ ثَمَرَهُنَّ، أَطْفَالَ ٱلْحَضَانَةِ؟ أَيُقْتَلُ فِي مَقْدِسِ ٱلسَّيِّدِ ٱلْكَاهِنُ وَٱلنَّبِيُّ؟","«ạun̊ẓur̊ yārabũ wataṭalãʿ̊ biman̊ faʿal̊ta hakadẖā? ạảtā̊̉kulu ٱlnĩsāʾu tẖamarahunã, ạảṭ̊fāla ٱl̊ḥaḍānaẗi? ạảyuq̊talu fī maq̊disi ٱlsãyĩdi ٱl̊kāhinu waٱlnãbīũ?"],[2,21,"ٱضْطَجَعَتْ عَلَى ٱلْأَرْضِ فِي ٱلشَّوَارِعِ ٱلصِّبْيَانُ وَٱلشُّيُوخُ. عَذَارَايَ وَشُبَّانِي سَقَطُوا بِٱلسَّيْفِ. قَدْ قَتَلْتَ فِي يَوْمِ غَضَبِكَ. ذَبَحْتَ وَلَمْ تَشْفِقْ.","ٱḍ̊ṭajaʿat̊ ʿalay̱ ٱl̊ạảr̊ḍi fī ٱlsẖãwāriʿi ٱlṣĩb̊yānu waٱlsẖũyūkẖu. ʿadẖārāya wasẖubãạnī saqaṭūạ biٱlsãẙfi. qad̊ qatal̊ta fī yaẘmi gẖaḍabika. dẖabaḥ̊ta walam̊ tasẖ̊fiq̊."],[2,22,"قَدْ دَعَوْتَ كَمَا فِي يَوْمِ مَوْسِمٍ مَخَاوِفِي حَوَالَيَّ، فَلَمْ يَكُنْ فِي يَوْمِ غَضَبِ ٱلرَّبِّ نَاجٍ وَلَا بَاقٍ. اَلَّذِينَ حَضَنْتُهُمْ وَرَبَّيْتُهُمْ أَفْنَاهُمْ عَدُوِّي».","qad̊ daʿaẘta kamā fī yaẘmi maẘsimiⁿ makẖāwifī ḥawālayã, falam̊ yakun̊ fī yaẘmi gẖaḍabi ٱlrãbĩ nājiⁿ walā bāqiⁿ. ạalãdẖīna ḥaḍan̊tuhum̊ warabãẙtuhum̊ ạảf̊nāhum̊ ʿadūĩy»."],[3,1,"أَنَا هُوَ ٱلرَّجُلُ ٱلَّذِي رأَى مَذَلَّةً بِقَضِيبِ سَخَطِهِ.","ạảnā hūa ٱlrãjulu ٱlãdẖī rạảy̱ madẖalãẗaⁿ biqaḍībi sakẖaṭihi."],[3,2,"قَادَنِي وَسَيَّرَنِي فِي ٱلظَّلَامِ وَلَا نُورَ.","qādanī wasayãranī fī ٱlẓãlāmi walā nūra."],[3,3,"حَقًّا إِنَّهُ يَعُودُ وَيَرُدُّ عَلَيَّ يَدَهُ ٱلْيَوْمَ كُلَّهُ.","ḥaqaⁿ̃ạ ại̹nãhu yaʿūdu wayarudũ ʿalayã yadahu ٱl̊yaẘma kulãhu."],[3,4,"أَبْلَى لَحْمِي وَجِلْدِي. كَسَّرَ عِظَامِي.","ạảb̊lay̱ laḥ̊mī wajil̊dī. kasãra ʿiẓāmī."],[3,5,"بَنَى عَلَيَّ وَأَحَاطَنِي بِعَلْقَمٍ وَمَشَقَّةٍ.","banay̱ ʿalayã wāảḥāṭanī biʿal̊qamiⁿ wamasẖaqãẗiⁿ."],[3,6,"أَسْكَنَنِي فِي ظُلُمَاتٍ كَمَوْتَى ٱلْقِدَمِ.","ạảs̊kananī fī ẓulumātiⁿ kamaẘtay̱ ٱl̊qidami."],[3,7,"سَيَّجَ عَلَيَّ فَلَا أَسْتَطِيعُ ٱلْخُرُوجَ. ثَقَّلَ سِلْسِلَتِي.","sayãja ʿalayã falā ạảs̊taṭīʿu ٱl̊kẖurūja. tẖaqãla sil̊silatī."],[3,8,"أَيْضًا حِينَ أَصْرُخُ وَأَسْتَغِيثُ يَصُدُّ صَلَاتِي.","ạảẙḍaⁿạ ḥīna ạảṣ̊rukẖu wāảs̊tagẖītẖu yaṣudũ ṣalātī."],[3,9,"سَيَّجَ طُرُقِي بِحِجَارَةٍ مَنْحُوتَةٍ. قَلَبَ سُبُلِي.","sayãja ṭuruqī biḥijāraẗiⁿ man̊ḥūtaẗiⁿ. qalaba subulī."],[3,10,"هُوَ لِي دُبٌّ كَامِنٌ، أَسَدٌ فِي مَخَابِىءَ.","hūa lī dubuⁿ̃ kāminuⁿ, ạảsaduⁿ fī makẖābiy̱ʾa."],[3,11,"مَيَّلَ طُرُقِي وَمَزَّقَنِي. جَعَلَنِي خَرَابًا.","mayãla ṭuruqī wamazãqanī. jaʿalanī kẖarābaⁿạ."],[3,12,"مَدَّ قَوْسَهُ وَنَصَبَنِي كَغَرَضٍ لِلسَّهْمِ.","madã qaẘsahu wanaṣabanī kagẖaraḍiⁿ lilsãh̊mi."],[3,13,"أَدْخَلَ فِي كُلْيَتَيَّ نِبَالَ جُعْبَتِهِ.","ạảd̊kẖala fī kul̊yatayã nibāla juʿ̊batihi."],[3,14,"صِرْتُ ضُحْكَةً لِكُلِّ شَعْبِي، وَأُغْنِيَةً لَهُمُ ٱلْيَوْمَ كُلَّهُ.","ṣir̊tu ḍuḥ̊kaẗaⁿ likulĩ sẖaʿ̊bī, wāủgẖ̊nīaẗaⁿ lahumu ٱl̊yaẘma kulãhu."],[3,15,"أَشْبَعَنِي مَرَائِرَ وَأَرْوَانِي أَفْسَنْتِينًا،","ạảsẖ̊baʿanī marāyỉra wāảr̊wānī ạảf̊san̊tīnaⁿạ,"],[3,16,"وَجَرَشَ بِٱلْحَصَى أَسْنَانِي. كَبَسَنِي بِٱلرَّمَادِ.","wajarasẖa biٱl̊ḥaṣay̱ ạảs̊nānī. kabasanī biٱlrãmādi."],[3,17,"وَقَدْ أَبْعَدْتَ عَنِ ٱلسَّلَامِ نَفْسِي. نَسِيتُ ٱلْخَيْرَ.","waqad̊ ạảb̊ʿad̊ta ʿani ٱlsãlāmi naf̊sī. nasītu ٱl̊kẖaẙra."],[3,18,"وَقُلْتُ: «بَادَتْ ثِقَتِي وَرَجَائِي مِنَ ٱلرَّبِّ».","waqul̊tu: «bādat̊ tẖiqatī warajāyỉy mina ٱlrãbĩ»."],[3,19,"ذِكْرُ مَذَلَّتِي وَتَيَهَانِي أَفْسَنْتِينٌ وَعَلْقَمٌ.","dẖik̊ru madẖalãtī watayahānī ạảf̊san̊tīnuⁿ waʿal̊qamuⁿ."],[3,20,"ذِكْرًا تَذْكُرُ نَفْسِي وَتَنْحَنِي فِيَّ.","dẖik̊raⁿạ tadẖ̊kuru naf̊sī watan̊ḥanī fīã."],[3,21,"أُرَدِّدُ هَذَا فِي قَلْبِي، مِنْ أَجْلِ ذَلِكَ أَرْجُو:","ạủradĩdu hadẖā fī qal̊bī, min̊ ạảj̊li dẖalika ạảr̊jū:"],[3,22,"إِنَّهُ مِنْ إِحْسَانَاتِ ٱلرَّبِّ أَنَّنَا لَمْ نَفْنَ، لِأَنَّ مَرَاحِمَهُ لَا تَزُولُ.","ại̹nãhu min̊ ại̹ḥ̊sānāti ٱlrãbĩ ạảnãnā lam̊ naf̊na, liạảnã marāḥimahu lā tazūlu."],[3,23,"هِيَ جَدِيدَةٌ فِي كُلِّ صَبَاحٍ. كَثِيرَةٌ أَمَانَتُكَ.","hīa jadīdaẗuⁿ fī kulĩ ṣabāḥiⁿ. katẖīraẗuⁿ ạảmānatuka."],[3,24,"نَصِيبِي هُوَ ٱلرَّبُّ، قَالَتْ نَفْسِي، مِنْ أَجْلِ ذَلِكَ أَرْجُوهُ.","naṣībī hūa ٱlrãbũ, qālat̊ naf̊sī, min̊ ạảj̊li dẖalika ạảr̊jūhu."],[3,25,"طَيِّبٌ هُوَ ٱلرَّبُّ لِلَّذِينَ يَتَرَجَّوْنَهُ، لِلنَّفْسِ ٱلَّتِي تَطْلُبُهُ.","ṭayĩbuⁿ hūa ٱlrãbũ lilãdẖīna yatarajãẘnahu, lilnãf̊si ٱlãtī taṭ̊lubuhu."],[3,26,"جَيِّدٌ أَنْ يَنْتَظِرَ ٱلْإِنْسَانُ وَيَتَوَقَّعَ بِسُكُوتٍ خَلَاصَ ٱلرَّبِّ.","jayĩduⁿ ạản̊ yan̊taẓira ٱl̊ại̹n̊sānu wayatawaqãʿa bisukūtiⁿ kẖalāṣa ٱlrãbĩ."],[3,27,"جَيِّدٌ لِلرَّجُلِ أَنْ يَحْمِلَ ٱلنِّيرَ فِي صِبَاهُ.","jayĩduⁿ lilrãjuli ạản̊ yaḥ̊mila ٱlnĩyra fī ṣibāhu."],[3,28,"يَجْلِسُ وَحْدَهُ وَيَسْكُتُ، لِأَنَّهُ قَدْ وَضَعَهُ عَلَيْهِ.","yaj̊lisu waḥ̊dahu wayas̊kutu, liạảnãhu qad̊ waḍaʿahu ʿalaẙhi."],[3,29,"يَجْعَلُ فِي ٱلتُّرَابِ فَمَهُ لَعَلَّهُ يُوجَدُ رَجَاءٌ.","yaj̊ʿalu fī ٱltũrābi famahu laʿalãhu yūjadu rajāʾuⁿ."],[3,30,"يُعْطِي خَدَّهُ لِضَارِبِهِ. يَشْبَعُ عَارًا.","yuʿ̊ṭī kẖadãhu liḍāribihi. yasẖ̊baʿu ʿāraⁿạ."],[3,31,"لِأَنَّ ٱلسَّيِّدَ لَا يَرْفُضُ إِلَى ٱلْأَبَدِ.","liạảnã ٱlsãyĩda lā yar̊fuḍu ại̹lay̱ ٱl̊ạảbadi."],[3,32,"فَإِنَّهُ وَلَوْ أَحْزَنَ يَرْحَمُ حَسَبَ كَثْرَةِ مَرَاحِمِهِ.","fāi̹nãhu walaẘ ạảḥ̊zana yar̊ḥamu ḥasaba katẖ̊raẗi marāḥimihi."],[3,33,"لِأَنَّهُ لَا يُذِلُّ مِنْ قَلْبِهِ، وَلَا يُحْزِنُ بَنِي ٱلْإِنْسَانِ.","liạảnãhu lā yudẖilũ min̊ qal̊bihi, walā yuḥ̊zinu banī ٱl̊ại̹n̊sāni."],[3,34,"أَنْ يَدُوسَ أَحَدٌ تَحْتَ رِجْلَيْهِ كُلَّ أَسْرَى ٱلْأَرْضِ،","ạản̊ yadūsa ạảḥaduⁿ taḥ̊ta rij̊laẙhi kulã ạảs̊ray̱ ٱl̊ạảr̊ḍi,"],[3,35,"أَنْ يُحَرِّفَ حَقَّ ٱلرَّجُلِ أَمَامَ وَجْهِ ٱلْعَلِيِّ،","ạản̊ yuḥarĩfa ḥaqã ٱlrãjuli ạảmāma waj̊hi ٱl̊ʿalīĩ,"],[3,36,"أَنْ يَقْلِبَ ٱلْإِنْسَانَ فِي دَعْوَاهُ. ٱلسَّيِّدُ لَا يَرَى!","ạản̊ yaq̊liba ٱl̊ại̹n̊sāna fī daʿ̊wāhu. ٱlsãyĩdu lā yaray̱!"],[3,37,"مَنْ ذَا ٱلَّذِي يَقُولُ فَيَكُونَ وَٱلرَّبُّ لَمْ يَأْمُرْ؟","man̊ dẖā ٱlãdẖī yaqūlu fayakūna waٱlrãbũ lam̊ yā̊̉mur̊?"],[3,38,"مِنْ فَمِ ٱلْعَلِيِّ أَلَا تَخْرُجُ ٱلشُّرُورُ وَٱلْخَيْرُ؟","min̊ fami ٱl̊ʿalīĩ ạảlā takẖ̊ruju ٱlsẖũrūru waٱl̊kẖaẙru?"],[3,39,"لِمَاذَا يَشْتَكِي ٱلْإِنْسَانُ ٱلْحَيُّ، ٱلرَّجُلُ مِنْ قِصَاصِ خَطَايَاهُ؟","limādẖā yasẖ̊takī ٱl̊ại̹n̊sānu ٱl̊ḥayũ, ٱlrãjulu min̊ qiṣāṣi kẖaṭāyāhu?"],[3,40,"لِنَفْحَصْ طُرُقَنَا وَنَمْتَحِنْهَا وَنَرْجِعْ إِلَى ٱلرَّبِّ.","linaf̊ḥaṣ̊ ṭuruqanā wanam̊taḥin̊hā wanar̊jiʿ̊ ại̹lay̱ ٱlrãbĩ."],[3,41,"لِنَرْفَعْ قُلُوبَنَا وَأَيْدِيَنَا إِلَى ٱللهِ فِي ٱلسَّمَاوَاتِ:","linar̊faʿ̊ qulūbanā wāảẙdīanā ại̹lay̱ ٱllhi fī ٱlsãmāwāti:"],[3,42,"«نَحْنُ أَذْنَبْنَا وَعَصَيْنَا. أَنْتَ لَمْ تَغْفِرْ.","«naḥ̊nu ạảdẖ̊nab̊nā waʿaṣaẙnā. ạản̊ta lam̊ tagẖ̊fir̊."],[3,43,"ٱلْتَحَفْتَ بِٱلْغَضَبِ وَطَرَدْتَنَا. قَتَلْتَ وَلَمْ تَشْفِقْ.","ٱl̊taḥaf̊ta biٱl̊gẖaḍabi waṭarad̊tanā. qatal̊ta walam̊ tasẖ̊fiq̊."],[3,44,"ٱلْتَحَفْتَ بِٱلسَّحَابِ حَتَّى لَا تَنْفُذَ ٱلصَّلَاةُ.","ٱl̊taḥaf̊ta biٱlsãḥābi ḥatãy̱ lā tan̊fudẖa ٱlṣãlāẗu."],[3,45,"جَعَلْتَنَا وَسَخًا وَكَرْهًا فِي وَسَطِ ٱلشُّعُوبِ.","jaʿal̊tanā wasakẖaⁿạ wakar̊haⁿạ fī wasaṭi ٱlsẖũʿūbi."],[3,46,"فَتَحَ كُلُّ أَعْدَائِنَا أَفْوَاهَهُمْ عَلَيْنَا.","fataḥa kulũ ạảʿ̊dāyỉnā ạảf̊wāhahum̊ ʿalaẙnā."],[3,47,"صَارَ عَلَيْنَا خَوْفٌ وَرُعْبٌ، هَلَاكٌ وَسَحْقٌ».","ṣāra ʿalaẙnā kẖaẘfuⁿ waruʿ̊buⁿ, halākuⁿ wasaḥ̊quⁿ»."],[3,48,"سَكَبَتْ عَيْنَايَ يَنَابِيعَ مَاءٍ عَلَى سَحْقِ بِنْتِ شَعْبِي.","sakabat̊ ʿaẙnāya yanābīʿa māʾiⁿ ʿalay̱ saḥ̊qi bin̊ti sẖaʿ̊bī."],[3,49,"عَيْنِي تَسْكُبُ وَلَا تَكُفُّ بِلَا ٱنْقِطَاعٍ","ʿaẙnī tas̊kubu walā takufũ bilā ٱn̊qiṭāʿiⁿ"],[3,50,"حَتَّى يُشْرِفَ وَيَنْظُرَ ٱلرَّبُّ مِنَ ٱلسَّمَاءِ.","ḥatãy̱ yusẖ̊rifa wayan̊ẓura ٱlrãbũ mina ٱlsãmāʾi."],[3,51,"عَيْنِي تُؤَثِّرُ فِي نَفْسِي لِأَجْلِ كُلِّ بَنَاتِ مَدِينَتِي.","ʿaẙnī tūảtẖĩru fī naf̊sī liạảj̊li kulĩ banāti madīnatī."],[3,52,"قَدِ ٱصْطَادَتْنِي أَعْدَائِي كَعُصْفُورٍ بِلَا سَبَبٍ.","qadi ٱṣ̊ṭādat̊nī ạảʿ̊dāyỉy kaʿuṣ̊fūriⁿ bilā sababiⁿ."],[3,53,"قَرَضُوا فِي ٱلْجُبِّ حَيَاتِي وَأَلْقَوْا عَلَيَّ حِجَارَةً.","qaraḍūạ fī ٱl̊jubĩ ḥayātī wāảl̊qaẘạ ʿalayã ḥijāraẗaⁿ."],[3,54,"طَفَتِ ٱلْمِيَاهُ فَوْقَ رَأْسِي. قُلْتُ: «قَدْ قُرِضْتُ!».","ṭafati ٱl̊mīāhu faẘqa rā̊̉sī. qul̊tu: «qad̊ quriḍ̊tu!»."],[3,55,"دَعَوْتُ بِٱسْمِكَ يَارَبُّ مِنَ ٱلْجُبِّ ٱلْأَسْفَلِ.","daʿaẘtu biٱs̊mika yārabũ mina ٱl̊jubĩ ٱl̊ạảs̊fali."],[3,56,"لِصَوْتِي سَمِعْتَ: «لَا تَسْتُرْ أُذُنَكَ عَنْ زَفْرَتِي، عَنْ صِيَاحِي».","liṣaẘtī samiʿ̊ta: «lā tas̊tur̊ ạủdẖunaka ʿan̊ zaf̊ratī, ʿan̊ ṣīāḥī»."],[3,57,"دَنَوْتَ يَوْمَ دَعَوْتُكَ. قُلْتَ: «لَا تَخَفْ!».","danaẘta yaẘma daʿaẘtuka. qul̊ta: «lā takẖaf̊!»."],[3,58,"خَاصَمْتَ يَا سَيِّدُ خُصُومَاتِ نَفْسِي. فَكَكْتَ حَيَاتِي.","kẖāṣam̊ta yā sayĩdu kẖuṣūmāti naf̊sī. fakak̊ta ḥayātī."],[3,59,"رَأَيْتَ يَارَبُّ ظُلْمِي. أَقِمْ دَعْوَايَ.","rāảẙta yārabũ ẓul̊mī. ạảqim̊ daʿ̊wāya."],[3,60,"رَأَيْتَ كُلَّ نَقْمَتِهِمْ، كُلَّ أَفْكَارِهِمْ عَلَيَّ.","rāảẙta kulã naq̊matihim̊, kulã ạảf̊kārihim̊ ʿalayã."],[3,61,"سَمِعْتَ تَعْيِيرَهُمْ يَارَبُّ، كُلَّ أَفْكَارِهِمْ عَلَيَّ.","samiʿ̊ta taʿ̊yīrahum̊ yārabũ, kulã ạảf̊kārihim̊ ʿalayã."],[3,62,"كَلَامُ مُقَاوِمِيَّ وَمُؤَامَرَتُهُمْ عَلَيَّ ٱلْيَوْمَ كُلَّهُ.","kalāmu muqāwimīã wamūảạmaratuhum̊ ʿalayã ٱl̊yaẘma kulãhu."],[3,63,"اُنْظُرْ إِلَى جُلُوسِهِمْ وَوُقُوفِهِمْ، أَنَا أُغْنِيَتُهُمْ!","ạun̊ẓur̊ ại̹lay̱ julūsihim̊ wawuqūfihim̊, ạảnā ạủgẖ̊nīatuhum̊!"],[3,64,"رُدَّ لَهُمْ جَزَاءً يَارَبُّ حَسَبَ عَمَلِ أَيَادِيهِمْ.","rudã lahum̊ jazāʾaⁿ yārabũ ḥasaba ʿamali ạảyādīhim̊."],[3,65,"أَعْطِهِمْ غِشَاوَةَ قَلْبٍ، لَعْنَتَكَ لَهُمْ.","ạảʿ̊ṭihim̊ gẖisẖāwaẗa qal̊biⁿ, laʿ̊nataka lahum̊."],[3,66,"اِتْبَعْ بِٱلْغَضَبِ وَأَهْلِكْهُمْ مِنْ تَحْتِ سَمَاوَاتِ ٱلرَّبِّ.","ạit̊baʿ̊ biٱl̊gẖaḍabi wāảh̊lik̊hum̊ min̊ taḥ̊ti samāwāti ٱlrãbĩ."],[4,1,"كَيْفَ ٱكْدَرَّ ٱلذَّهَبُ، تَغَيَّرَ ٱلْإِبْرِيزُ ٱلْجَيِّدُ! ٱنْهَالَتْ حِجَارَةُ ٱلْقُدْسِ فِي رَأْسِ كُلِّ شَارِعٍ.","kaẙfa ٱk̊darã ٱldẖãhabu, tagẖayãra ٱl̊ại̹b̊rīzu ٱl̊jayĩdu! ٱn̊hālat̊ ḥijāraẗu ٱl̊qud̊si fī rā̊̉si kulĩ sẖāriʿiⁿ."],[4,2,"بَنُو صِهْيَوْنَ ٱلْكُرَمَاءُ ٱلْمَوْزُونُونَ بِٱلذَّهَبِ ٱلنَّقِيِّ، كَيْفَ حُسِبُوا أَبَارِيقَ خَزَفٍ عَمَلَ يَدَيْ فَخَّارِيٍّ!","banū ṣih̊yaẘna ٱl̊kuramāʾu ٱl̊maẘzūnūna biٱldẖãhabi ٱlnãqīĩ, kaẙfa ḥusibūạ ạảbārīqa kẖazafiⁿ ʿamala yadaẙ fakẖãạrīiⁿ̃!"],[4,3,"بَنَاتُ آوَى أَيْضًا أَخْرَجَتْ أَطْبَاءَهَا، أَرْضَعَتْ أَجْرَاءَهَا. أَمَّا بِنْتُ شَعْبِي فَجَافِيَةٌ كَٱلنَّعَامِ فِي ٱلْبَرِّيَّةِ.","banātu ậway̱ ạảẙḍaⁿạ ạảkẖ̊rajat̊ ạảṭ̊bāʾahā, ạảr̊ḍaʿat̊ ạảj̊rāʾahā. ạảmãạ bin̊tu sẖaʿ̊bī fajāfīaẗuⁿ kaٱlnãʿāmi fī ٱl̊barĩyãẗi."],[4,4,"لَصِقَ لِسَانُ ٱلرَّاضِعِ بِحَنَكِهِ مِنَ ٱلْعَطَشِ. اَلْأَطْفَالُ يَسْأَلُونَ خُبْزًا وَلَيْسَ مَنْ يَكْسِرُهُ لَهُمْ.","laṣiqa lisānu ٱlrãạḍiʿi biḥanakihi mina ٱl̊ʿaṭasẖi. ạal̊ạảṭ̊fālu yas̊ạảlūna kẖub̊zaⁿạ walaẙsa man̊ yak̊siruhu lahum̊."],[4,5,"اَلَّذِينَ كَانُوا يَأْكُلُونَ ٱلْمَآكِلَ ٱلْفَاخِرَةَ قَدْ هَلِكُوا فِي ٱلشَّوَارِعِ. ٱلَّذِينَ كَانُوا يَتَرَبَّوْنَ عَلَى ٱلْقِرْمِزِ ٱحْتَضَنُوا ٱلْمَزَابِلَ.","ạalãdẖīna kānūạ yā̊̉kulūna ٱl̊mā̂kila ٱl̊fākẖiraẗa qad̊ halikūạ fī ٱlsẖãwāriʿi. ٱlãdẖīna kānūạ yatarabãẘna ʿalay̱ ٱl̊qir̊mizi ٱḥ̊taḍanūạ ٱl̊mazābila."],[4,6,"وَقَدْ صَارَ عِقَابُ بِنْتِ شَعْبِي أَعْظَمَ مِنْ قِصَاصِ خَطِيَّةِ سَدُومَ ٱلَّتِي ٱنْقَلَبَتْ كَأَنَّهُ فِي لَحْظَةٍ، وَلَمْ تُلْقَ عَلَيْهَا أَيَادٍ.","waqad̊ ṣāra ʿiqābu bin̊ti sẖaʿ̊bī ạảʿ̊ẓama min̊ qiṣāṣi kẖaṭīãẗi sadūma ٱlãtī ٱn̊qalabat̊ kāảnãhu fī laḥ̊ẓaẗiⁿ, walam̊ tul̊qa ʿalaẙhā ạảyādiⁿ."],[4,7,"كَانَ نُذُرُهَا أَنْقَى مِنَ ٱلثَّلْجِ وَأَكْثَرَ بَيَاضًا مِنَ ٱللَّبَنِ، وَأَجْسَامُهُمْ أَشَدَّ حُمْرَةً مِنَ ٱلْمَرْجَانِ. جَرَزُهُمْ كَٱلْيَاقُوتِ ٱلْأَزْرَقِ.","kāna nudẖuruhā ạản̊qay̱ mina ٱltẖãl̊ji wāảk̊tẖara bayāḍaⁿạ mina ٱllãbani, wāảj̊sāmuhum̊ ạảsẖadã ḥum̊raẗaⁿ mina ٱl̊mar̊jāni. jarazuhum̊ kaٱl̊yāqūti ٱl̊ạảz̊raqi."],[4,8,"صَارَتْ صُورَتُهُمْ أَشَدَّ ظَلَامًا مِنَ ٱلسَّوَادِ. لَمْ يُعْرَفُوا فِي ٱلشَّوَارِعِ. لَصِقَ جِلْدُهُمْ بِعَظْمِهِمْ. صَارَ يَابِسًا كَٱلْخَشَبِ.","ṣārat̊ ṣūratuhum̊ ạảsẖadã ẓalāmaⁿạ mina ٱlsãwādi. lam̊ yuʿ̊rafūạ fī ٱlsẖãwāriʿi. laṣiqa jil̊duhum̊ biʿaẓ̊mihim̊. ṣāra yābisaⁿạ kaٱl̊kẖasẖabi."],[4,9,"كَانَتْ قَتْلَى ٱلسَّيْفِ خَيْرًا مِنْ قَتْلَى ٱلْجُوعِ. لِأَنَّ هَؤُلَاءِ يَذُوبُونَ مَطْعُونِينَ لِعَدَمِ أَثْمَارِ ٱلْحَقْلِ.","kānat̊ qat̊lay̱ ٱlsãẙfi kẖaẙraⁿạ min̊ qat̊lay̱ ٱl̊jūʿi. liạảnã hawủlāʾi yadẖūbūna maṭ̊ʿūnīna liʿadami ạảtẖ̊māri ٱl̊ḥaq̊li."],[4,10,"أَيَادِي ٱلنِّسَاءِ ٱلْحَنَائِنِ طَبَخَتْ أَوْلَادَهُنَّ. صَارُوا طَعَامًا لَهُنَّ فِي سَحْقِ بِنْتِ شَعْبِي.","ạảyādī ٱlnĩsāʾi ٱl̊ḥanāyỉni ṭabakẖat̊ ạảẘlādahunã. ṣārūạ ṭaʿāmaⁿạ lahunã fī saḥ̊qi bin̊ti sẖaʿ̊bī."],[4,11,"أَتَمَّ ٱلرَّبُّ غَيْظَهُ. سَكَبَ حُمُوَّ غَضَبِهِ وَأَشْعَلَ نَارًا فِي صِهْيَوْنَ فَأَكَلَتْ أُسُسَهَا.","ạảtamã ٱlrãbũ gẖaẙẓahu. sakaba ḥumūã gẖaḍabihi wāảsẖ̊ʿala nāraⁿạ fī ṣih̊yaẘna fāảkalat̊ ạủsusahā."],[4,12,"لَمْ تُصَدِّقْ مُلُوكُ ٱلْأَرْضِ وَكُلُّ سُكَّانِ ٱلْمَسْكُونَةِ أَنَّ ٱلْعَدُوَّ وَٱلْمُبْغِضَ يَدْخُلَانِ أَبْوَابَ أُورُشَلِيمَ.","lam̊ tuṣadĩq̊ mulūku ٱl̊ạảr̊ḍi wakulũ sukãạni ٱl̊mas̊kūnaẗi ạảnã ٱl̊ʿadūã waٱl̊mub̊gẖiḍa yad̊kẖulāni ạảb̊wāba ạủwrusẖalīma."],[4,13,"مِنْ أَجْلِ خَطَايَا أَنْبِيَائِهَا، وَآثَامِ كَهَنَتِهَا ٱلسَّافِكِينَ فِي وَسَطِهَا دَمَ ٱلصِّدِّيقِينَ،","min̊ ạảj̊li kẖaṭāyā ạản̊bīāyỉhā, wā̂tẖāmi kahanatihā ٱlsãạfikīna fī wasaṭihā dama ٱlṣĩdĩyqīna,"],[4,14,"تَاهُوا كَعُمْيٍ فِي ٱلشَّوَارِعِ، وَتَلَطَّخُوا بِٱلدَّمِ حَتَّى لَمْ يَسْتَطِعْ أَحَدٌ أَنْ يَمَسَّ مَلَابِسَهُمْ.","tāhūạ kaʿum̊yiⁿ fī ٱlsẖãwāriʿi, watalaṭãkẖūạ biٱldãmi ḥatãy̱ lam̊ yas̊taṭiʿ̊ ạảḥaduⁿ ạản̊ yamasã malābisahum̊."],[4,15,"«حِيدُوا! نَجِسٌ!» يُنَادُونَ إِلَيْهِمْ. «حِيدُوا! حِيدُوا لَا تَمَسُّوا!». إِذْ هَرَبُوا تَاهُوا أَيْضًا. قَالُوا بَيْنَ ٱلْأُمَمِ: «إِنَّهُمْ لَا يَعُودُونَ يَسْكُنُونَ».","«ḥīdūạ! najisuⁿ!» yunādūna ại̹laẙhim̊. «ḥīdūạ! ḥīdūạ lā tamasũwạ!». ại̹dẖ̊ harabūạ tāhūạ ạảẙḍaⁿạ. qālūạ baẙna ٱl̊ạủmami: «ại̹nãhum̊ lā yaʿūdūna yas̊kunūna»."],[4,16,"وَجْهُ ٱلرَّبِّ قَسَمَهُمْ. لَا يَعُودُ يَنْظُرُ إِلَيْهِمْ. لَمْ يَرْفَعُوا وُجُوهَ ٱلْكَهَنَةِ، وَلَمْ يَتَرَأَّفُوا عَلَى ٱلشُّيُوخِ.","waj̊hu ٱlrãbĩ qasamahum̊. lā yaʿūdu yan̊ẓuru ại̹laẙhim̊. lam̊ yar̊faʿūạ wujūha ٱl̊kahanaẗi, walam̊ yatarāã̉fūạ ʿalay̱ ٱlsẖũyūkẖi."],[4,17,"أَمَّا نَحْنُ فَقَدْ كَلَّتْ أَعْيُنُنَا مِنَ ٱلنَّظَرِ إِلَى عَوْنِنَا ٱلْبَاطِلِ. فِي بُرْجِنَا ٱنْتَظَرْنَا أُمَّةً لَا تُخَلِّصُ.","ạảmãạ naḥ̊nu faqad̊ kalãt̊ ạảʿ̊yununā mina ٱlnãẓari ại̹lay̱ ʿaẘninā ٱl̊bāṭili. fī bur̊jinā ٱn̊taẓar̊nā ạủmãẗaⁿ lā tukẖalĩṣu."],[4,18,"نَصَبُوا فِخَاخًا لِخَطَوَاتِنَا حَتَّى لَا نَمْشِيَ فِي سَاحَاتِنَا. قَرُبَتْ نِهَايَتُنَا. كَمُلَتْ أَيَّامُنَا لِأَنَّ نِهَايَتَنَا قَدْ أَتَتْ.","naṣabūạ fikẖākẖaⁿạ likẖaṭawātinā ḥatãy̱ lā nam̊sẖīa fī sāḥātinā. qarubat̊ nihāyatunā. kamulat̊ ạảyãạmunā liạảnã nihāyatanā qad̊ ạảtat̊."],[4,19,"صَارَ طَارِدُونَا أَخَفَّ مِنْ نُسُورِ ٱلسَّمَاءِ. عَلَى ٱلْجِبَالِ جَدُّوا فِي أَثَرِنَا. فِي ٱلْبَرِّيَّةِ كَمَنُوا لَنَا.","ṣāra ṭāridūnā ạảkẖafã min̊ nusūri ٱlsãmāʾi. ʿalay̱ ٱl̊jibāli jadũwạ fī ạảtẖarinā. fī ٱl̊barĩyãẗi kamanūạ lanā."],[4,20,"نَفَسُ أُنُوفِنَا، مَسِيحُ ٱلرَّبِّ، أُخِذَ فِي حُفَرِهِمِ. ٱلَّذِي قُلْنَا عَنْهُ: «فِي ظِلِّهِ نَعِيشُ بَيْنَ ٱلْأُمَمِ».","nafasu ạủnūfinā, masīḥu ٱlrãbĩ, ạủkẖidẖa fī ḥufarihimi. ٱlãdẖī qul̊nā ʿan̊hu: «fī ẓilĩhi naʿīsẖu baẙna ٱl̊ạủmami»."],[4,21,"اِطْرَبِي وَٱفْرَحِي يَا بِنْتَ أَدُومَ، يَا سَاكِنَةَ عَوْصٍ. عَلَيْكِ أَيْضًا تَمُرُّ ٱلْكَأْسُ. تَسْكَرِينَ وَتَتَعَرَّينَ.","ạiṭ̊rabī waٱf̊raḥī yā bin̊ta ạảdūma, yā sākinaẗa ʿaẘṣiⁿ. ʿalaẙki ạảẙḍaⁿạ tamurũ ٱl̊kā̊̉su. tas̊karīna watataʿarãyna."],[4,22,"قَدْ تَمَّ إِثْمُكِ يَا بِنْتَ صِهْيَوْنَ. لَا يَعُودُ يَسْبِيكِ. سَيُعَاقِبُ إِثْمَكِ يَا بِنْتَ أَدُومَ وَيُعْلِنُ خَطَايَاكِ.","qad̊ tamã ại̹tẖ̊muki yā bin̊ta ṣih̊yaẘna. lā yaʿūdu yas̊bīki. sayuʿāqibu ại̹tẖ̊maki yā bin̊ta ạảdūma wayuʿ̊linu kẖaṭāyāki."],[5,1,"اُذْكُرْ يَارَبُّ مَاذَا صَارَ لَنَا. أَشْرِفْ وَٱنْظُرْ إِلَى عَارِنَا.","ạudẖ̊kur̊ yārabũ mādẖā ṣāra lanā. ạảsẖ̊rif̊ waٱn̊ẓur̊ ại̹lay̱ ʿārinā."],[5,2,"قَدْ صَارَ مِيرَاثُنَا لِلْغُرَبَاءِ. بُيُوتُنَا لِلْأَجَانِبِ.","qad̊ ṣāra mīrātẖunā lil̊gẖurabāʾi. buyūtunā lil̊ạảjānibi."],[5,3,"صِرْنَا أَيْتَامًا بِلَا أَبٍ. أُمَّهَاتُنَا كَأَرَامِلَ.","ṣir̊nā ạảẙtāmaⁿạ bilā ạảbiⁿ. ạủmãhātunā kāảrāmila."],[5,4,"شَرِبْنَا مَاءَنَا بِٱلْفِضَّةِ. حَطَبُنَا بِٱلثَّمَنِ يَأْتِي.","sẖarib̊nā māʾanā biٱl̊fiḍãẗi. ḥaṭabunā biٱltẖãmani yā̊̉tī."],[5,5,"عَلَى أَعْنَاقِنَا نُضْطَهَدُ. نَتْعَبُ وَلَا رَاحَةَ لَنَا.","ʿalay̱ ạảʿ̊nāqinā nuḍ̊ṭahadu. nat̊ʿabu walā rāḥaẗa lanā."],[5,6,"أَعْطَيْنَا ٱلْيَدَ لِلْمِصْرِيِّينَ وَٱلْأَشُّورِيِّينَ لِنَشْبَعَ خُبْزًا.","ạảʿ̊ṭaẙnā ٱl̊yada lil̊miṣ̊rīĩyna waٱl̊ạảsẖũwrīĩyna linasẖ̊baʿa kẖub̊zaⁿạ."],[5,7,"آبَاؤُنَا أَخْطَأُوا وَلَيْسُوا بِمَوْجُودِينَ، وَنَحْنُ نَحْمِلُ آثَامَهُمْ.","ậbāwủnā ạảkẖ̊ṭāủwạ walaẙsūạ bimaẘjūdīna, wanaḥ̊nu naḥ̊milu ậtẖāmahum̊."],[5,8,"عَبِيدٌ حَكَمُوا عَلَيْنَا. لَيْسَ مَنْ يُخَلِّصُ مِنْ أَيْدِيهِمْ.","ʿabīduⁿ ḥakamūạ ʿalaẙnā. laẙsa man̊ yukẖalĩṣu min̊ ạảẙdīhim̊."],[5,9,"بِأَنْفُسِنَا نَأْتِي بِخُبْزِنَا مِنْ جَرَى سَيْفِ ٱلْبَرِّيَّةِ.","biạản̊fusinā nā̊̉tī bikẖub̊zinā min̊ jaray̱ saẙfi ٱl̊barĩyãẗi."],[5,10,"جُلُودُنَا ٱسْوَدَّتْ كَتَنُّورٍ مِنْ جَرَى نِيرَانِ ٱلْجُوعِ.","julūdunā ٱs̊wadãt̊ katanũwriⁿ min̊ jaray̱ nīrāni ٱl̊jūʿi."],[5,11,"أَذَلُّوا ٱلنِّسَاءَ فِي صِهْيَوْنَ، ٱلْعَذَارَى فِي مُدُنِ يَهُوذَا.","ạảdẖalũwạ ٱlnĩsāʾa fī ṣih̊yaẘna, ٱl̊ʿadẖāray̱ fī muduni yahūdẖā."],[5,12,"ٱلرُّؤَسَاءُ بِأَيْدِيهِمْ يُعَلَّقُونَ، وَلَمْ تُعْتَبَرْ وُجُوهُ ٱلشُّيُوخِ.","ٱlrũwảsāʾu biạảẙdīhim̊ yuʿalãqūna, walam̊ tuʿ̊tabar̊ wujūhu ٱlsẖũyūkẖi."],[5,13,"أَخَذُوا ٱلشُّبَّانَ لِلطَّحْنِ، وَٱلصِّبْيَانَ عَثَرُوا تَحْتَ ٱلْحَطَبِ.","ạảkẖadẖūạ ٱlsẖũbãạna lilṭãḥ̊ni, waٱlṣĩb̊yāna ʿatẖarūạ taḥ̊ta ٱl̊ḥaṭabi."],[5,14,"كَفَّتِ ٱلشُّيُوخُ عَنِ ٱلْبَابِ، وَٱلشُّبَّانُ عَنْ غِنَائِهِمْ.","kafãti ٱlsẖũyūkẖu ʿani ٱl̊bābi, waٱlsẖũbãạnu ʿan̊ gẖināyỉhim̊."],[5,15,"مَضَى فَرَحُ قَلْبِنَا. صَارَ رَقْصُنَا نَوْحًا.","maḍay̱ faraḥu qal̊binā. ṣāra raq̊ṣunā naẘḥaⁿạ."],[5,16,"سَقَطَ إِكْلِيلُ رَأْسِنَا. وَيْلٌ لَنَا لِأَنَّنَا قَدْ أَخْطَأْنَا.","saqaṭa ại̹k̊līlu rā̊̉sinā. waẙluⁿ lanā liạảnãnā qad̊ ạảkẖ̊ṭā̊̉nā."],[5,17,"مِنْ أَجْلِ هَذَا حَزِنَ قَلْبُنَا. مِنْ أَجْلِ هَذِهِ أَظْلَمَتْ عُيُونُنَا.","min̊ ạảj̊li hadẖā ḥazina qal̊bunā. min̊ ạảj̊li hadẖihi ạảẓ̊lamat̊ ʿuyūnunā."],[5,18,"مِنْ أَجْلِ جَبَلِ صِهْيَوْنَ ٱلْخَرِبِ. ٱلثَّعَالِبُ مَاشِيَةٌ فِيهِ.","min̊ ạảj̊li jabali ṣih̊yaẘna ٱl̊kẖaribi. ٱltẖãʿālibu māsẖīaẗuⁿ fīhi."],[5,19,"أَنْتَ يَارَبُّ إِلَى ٱلْأَبَدِ تَجْلِسُ. كُرْسِيُّكَ إِلَى دَوْرٍ فَدَوْرٍ.","ạản̊ta yārabũ ại̹lay̱ ٱl̊ạảbadi taj̊lisu. kur̊sīũka ại̹lay̱ daẘriⁿ fadaẘriⁿ."],[5,20,"لِمَاذَا تَنْسَانَا إِلَى ٱلْأَبَدِ وَتَتْرُكُنَا طُولَ ٱلْأَيَّامِ؟","limādẖā tan̊sānā ại̹lay̱ ٱl̊ạảbadi watat̊rukunā ṭūla ٱl̊ạảyãạmi?"],[5,21,"اُرْدُدْنَا يَارَبُّ إِلَيْكَ فَنَرْتَدَّ. جَدِّدْ أَيَّامَنَا كَٱلْقَدِيمِ.","ạur̊dud̊nā yārabũ ại̹laẙka fanar̊tadã. jadĩd̊ ạảyãạmanā kaٱl̊qadīmi."],[5,22,"هَلْ كُلَّ ٱلرَّفْضِ رَفَضْتَنَا؟ هَلْ غَضِبْتَ عَلَيْنَا جِدًّا؟","hal̊ kulã ٱlrãf̊ḍi rafaḍ̊tanā? hal̊ gẖaḍib̊ta ʿalaẙnā jidaⁿ̃ạ?"]],"bis-obbr":[[1,1,"Taon ya Jerusalem* we fastaem i fulap gud long ol man, naoia i no gat man nating long hem, mo hem i harem nogud tumas from. Fastaem olgeta man long wol oli stap ona long hem, be naoia hem i stap hem wan, olsem wan woman we man blong hem i ded. Taon ya we fastaem i gud moa i winim ol narafala taon, naoia hem i kam slef* finis.","Taon ya Jerusalem* we fastaem i fulap gud long ol man, naoia i no gat man nating long hem, mo hem i harem nogud tumas from. Fastaem olgeta man long wol oli stap ona long hem, be naoia hem i stap hem wan, olsem wan woman we man blong hem i ded. Taon ya we fastaem i gud moa i winim ol narafala taon, naoia hem i kam slef* finis."],[1,2,"Oltaem long naet hem i stap krae gogo kasem delaet, we wota blong ae blong hem i stap ron bigwan. Ol fren blong hem oli giaman gud long hem, nao oli kam enemi blong hem. I no moa gat wan long olgeta i stap blong givhan long hem.","Oltaem long naet hem i stap krae gogo kasem delaet, we wota blong ae blong hem i stap ron bigwan. Ol fren blong hem oli giaman gud long hem, nao oli kam enemi blong hem. I no moa gat wan long olgeta i stap blong givhan long hem."],[1,3,"Ol enemi oli ronemaot ol man Juda* i gowe long hom blong olgeta. Naoia oli kam slef, oli stap long ol narafala kantri. I no gat wan ples we oli save talem se i ples blong olgeta. Mo ol enemi oli blokemgud olgeta, nao oli no save ronwe.","Ol enemi oli ronemaot ol man Juda* i gowe long hom blong olgeta. Naoia oli kam slef, oli stap long ol narafala kantri. I no gat wan ples we oli save talem se i ples blong olgeta. Mo ol enemi oli blokemgud olgeta, nao oli no save ronwe."],[1,4,"Naoia i no moa gat man i save kam long haos* blong Hae God long ol tabu dei ya blong mekem wosip long hem. Ol gel we fastaem oli stap sing long haos ya, naoia oli stap harem nogud nomo, mo ol pris tu oli harem nogud oli stap krae. I no moa gat man nating i stap long ol doa* blong stonwol blong taon ya, mo hil ya Saeon* i stap harem nogud tumas.","Naoia i no moa gat man i save kam long haos* blong Hae God long ol tabu dei ya blong mekem wosip long hem. Ol gel we fastaem oli stap sing long haos ya, naoia oli stap harem nogud nomo, mo ol pris tu oli harem nogud oli stap krae. I no moa gat man nating i stap long ol doa* blong stonwol blong taon ya, mo hil ya Saeon* i stap harem nogud tumas."],[1,5,"Ol enemi blong hem oli winim hem nao hem i stap long han blong olgeta. Hae God nao i mekem hem i harem nogud from we sin blong hem i plante we plante. Ol enemi oli holem ol man blong hem oli tekemaot olgeta oli go wok slef longwe.","Ol enemi blong hem oli winim hem nao hem i stap long han blong olgeta. Hae God nao i mekem hem i harem nogud from we sin blong hem i plante we plante. Ol enemi oli holem ol man blong hem oli tekemaot olgeta oli go wok slef longwe."],[1,6,"Taon ya Jerusalem, fastaem i flas gud, be naoia i nogud we i nogud. Ol lida blong hem oli olsem anamol we i hanggri tumas nao i slak from, mo taem man i stap ronem hem be hem i stap ronwe we i no gat paoa nating.","Taon ya Jerusalem, fastaem i flas gud, be naoia i nogud we i nogud. Ol lida blong hem oli olsem anamol we i hanggri tumas nao i slak from, mo taem man i stap ronem hem be hem i stap ronwe we i no gat paoa nating."],[1,7,"Naoia we Jerusalem i harem nogud, mo ol man blong hem oli no moa gat ples blong olgeta, hem i stap tingbaot laef ya blong hem bifo we i flas gud. Taem ol enemi oli winim hem, i no gat man nating i stap blong givhan long hem. Olgeta ya we oli winim hem, oli stap laf long hem from we hem i lus.","Naoia we Jerusalem i harem nogud, mo ol man blong hem oli no moa gat ples blong olgeta, hem i stap tingbaot laef ya blong hem bifo we i flas gud. Taem ol enemi oli winim hem, i no gat man nating i stap blong givhan long hem. Olgeta ya we oli winim hem, oli stap laf long hem from we hem i lus."],[1,8,"Jerusalem ya, hem nomo i mekem hem i kam doti long ol sin blong hem we i nogud tumas. Hem i stap neked nomo, nao ol man oli no moa ona long hem, oli stap lukluk rabis long hem. Hem i harem nogud i stap krae, mo i haedem fes blong hem from we i sem tumas.","Jerusalem ya, hem nomo i mekem hem i kam doti long ol sin blong hem we i nogud tumas. Hem i stap neked nomo, nao ol man oli no moa ona long hem, oli stap lukluk rabis long hem. Hem i harem nogud i stap krae, mo i haedem fes blong hem from we i sem tumas."],[1,9,"Bifo ol enemi oli stap luk sin blong hem, be hem i no wari nating se bambae hem i ded from ol sin ya. Be naoia ol enemi blong hem oli daonemgud hem, mo i no gat man i save mekem tingting blong hem i kam gud bakegen. Ol enemi blong hem oli winim hem, nao hem i stap krae long Hae God blong i sore long hem.","Bifo ol enemi oli stap luk sin blong hem, be hem i no wari nating se bambae hem i ded from ol sin ya. Be naoia ol enemi blong hem oli daonemgud hem, mo i no gat man i save mekem tingting blong hem i kam gud bakegen. Ol enemi blong hem oli winim hem, nao hem i stap krae long Hae God blong i sore long hem."],[1,10,"Hae God i bin talem se i tabu blong ol man afsaed oli go long haos blong hem long ples ya we ol laen* blong Isrel* oli stap go long hem blong mekem wosip. Be ol man Jerusalem oli luk we ol enemi blong olgeta oli go moa, oli go insaed long haos ya oli stilim ol gudgudfala samting blong hem.","Hae God i bin talem se i tabu blong ol man afsaed oli go long haos blong hem long ples ya we ol laen* blong Isrel* oli stap go long hem blong mekem wosip. Be ol man Jerusalem oli luk we ol enemi blong olgeta oli go moa, oli go insaed long haos ya oli stilim ol gudgudfala samting blong hem."],[1,11,"Oltaem ol man Jerusalem oli harem nogud, oli stap krae, from we oli trabol tumas blong kasem kakae blong olgeta. Oli stap yusum ol gudgudfala samting blong olgeta blong pem kakae blong olgeta long hem blong oli save stap laef. Taon ya i stap krae, i talem se, “!Hae God, mi mi stap harem nogud tumas! !Plis yu lukluk i kam long mi!”","Oltaem ol man Jerusalem oli harem nogud, oli stap krae, from we oli trabol tumas blong kasem kakae blong olgeta. Oli stap yusum ol gudgudfala samting blong olgeta blong pem kakae blong olgeta long hem blong oli save stap laef. Taon ya i stap krae, i talem se, “!Hae God, mi mi stap harem nogud tumas! !Plis yu lukluk i kam long mi!”"],[1,12,"Hem i stap krae, i talem long olgeta we oli stap pas klosap long hem se, “Yufala i luk. Mi mi stap harem nogud tumas, i no gat narafala man i harem nogud olsem mi. Hae God i kros long mi, nao i mekem mi mi stap harem nogud olsem.","Hem i stap krae, i talem long olgeta we oli stap pas klosap long hem se, “Yufala i luk. Mi mi stap harem nogud tumas, i no gat narafala man i harem nogud olsem mi. Hae God i kros long mi, nao i mekem mi mi stap harem nogud olsem."],[1,13,"“Hem i stap long ples blong hem antap, i sanem faea i kam, mo faea ya i stap bon insaed long mi. Hem i putum wan trap blong kasem mi, i mekem mi mi foldaon, nao hem i lego mi, i livim mi mi stap, we mi stap harem nogud oltaem nomo.","“Hem i stap long ples blong hem antap, i sanem faea i kam, mo faea ya i stap bon insaed long mi. Hem i putum wan trap blong kasem mi, i mekem mi mi foldaon, nao hem i lego mi, i livim mi mi stap, we mi stap harem nogud oltaem nomo."],[1,14,"“Masta* blong mi, hem i stap makem ol sin blong mi, mo i putum olgeta i stap wanples. Olgeta oli olsem hevi samting we hem i putum long solda blong mi, nao i mekem mi mi slak we mi slak. Hem i putum mi long han blong ol enemi blong mi we mi mi no gat paoa nating, blong faet agens long olgeta.","“Masta* blong mi, hem i stap makem ol sin blong mi, mo i putum olgeta i stap wanples. Olgeta oli olsem hevi samting we hem i putum long solda blong mi, nao i mekem mi mi slak we mi slak. Hem i putum mi long han blong ol enemi blong mi we mi mi no gat paoa nating, blong faet agens long olgeta."],[1,15,"“Hae God i laf nogud long ol nambawan soldia blong mi. Hem i sanem ol enemi i kam blong spolem ol yang man ya blong mi. Mo hem i smasem olgeta man blong mi olsem we man i stap purumpurumbut long ol grep* blong wokem waen long wota blong hem.","“Hae God i laf nogud long ol nambawan soldia blong mi. Hem i sanem ol enemi i kam blong spolem ol yang man ya blong mi. Mo hem i smasem olgeta man blong mi olsem we man i stap purumpurumbut long ol grep* blong wokem waen long wota blong hem."],[1,16,"“Taswe mi mi stap krae tumas, from we ol man we oli save leftemap tingting blong mi blong mekem mi mi harem gud bakegen, oli go stap longwe long mi. Ol enemi ya oli winim mi, nao ol man blong mi oli no moa gat wan samting i stap.","“Taswe mi mi stap krae tumas, from we ol man we oli save leftemap tingting blong mi blong mekem mi mi harem gud bakegen, oli go stap longwe long mi. Ol enemi ya oli winim mi, nao ol man blong mi oli no moa gat wan samting i stap."],[1,17,"“Mi stap pusumaot han blong mi blong man i halpem mi, be i no gat man i wantem givhan long mi. Hae God i sanem ol enemi ya, oli kam long evri saed, oli agens long mi, mo oli mekem long mi olsem we mi mi wan samting we i doti tumas.","“Mi stap pusumaot han blong mi blong man i halpem mi, be i no gat man i wantem givhan long mi. Hae God i sanem ol enemi ya, oli kam long evri saed, oli agens long mi, mo oli mekem long mi olsem we mi mi wan samting we i doti tumas."],[1,18,"“Be Hae God hem i stret olgeta. Mi nomo mi no stap obei long tok blong hem. !Ol man blong ol narafala kantri! !Plis yufala i lesin long mi! Mi mi stap harem nogud tumas. Yufala i luk i kam long mi. Ol yang boe blong mi mo ol yang gel blong mi, ol enemi oli tekemaot olgeta finis oli go wok slef long narafala kantri.","“Be Hae God hem i stret olgeta. Mi nomo mi no stap obei long tok blong hem. !Ol man blong ol narafala kantri! !Plis yufala i lesin long mi! Mi mi stap harem nogud tumas. Yufala i luk i kam long mi. Ol yang boe blong mi mo ol yang gel blong mi, ol enemi oli tekemaot olgeta finis oli go wok slef long narafala kantri."],[1,19,"“Mi singaot i go long ol kantri we oli fren blong mi be oli no wantem kam givhan long mi. Nao ol pris mo ol lida blong mi, oli stap lukaot kakae blong olgeta be oli no save faenem, nao oli stap ded long hanggri olbaot long taon.","“Mi singaot i go long ol kantri we oli fren blong mi be oli no wantem kam givhan long mi. Nao ol pris mo ol lida blong mi, oli stap lukaot kakae blong olgeta be oli no save faenem, nao oli stap ded long hanggri olbaot long taon."],[1,20,"“Hae God, yu luk. Mi mi harem nogud tumas, mo tingting blong mi i trabol olgeta. Mi sore we mi sore tumas, from we mi girap agens long yu. Insaed long haos, ol man blong mi oli stap ded, mo afsaed, sam long olgeta, ol enemi oli stap kilim olgeta oli ded.","“Hae God, yu luk. Mi mi harem nogud tumas, mo tingting blong mi i trabol olgeta. Mi sore we mi sore tumas, from we mi girap agens long yu. Insaed long haos, ol man blong mi oli stap ded, mo afsaed, sam long olgeta, ol enemi oli stap kilim olgeta oli ded."],[1,21,"“Plis yu lesin long krae blong mi, i no gat man i stap blong givhan long mi. Ol enemi blong mi oli harem we mi mi stap harem nogud, nao oli glad tumas from we yu yu sanem trabol ya // i kam long mi. Dei ya we yu bin talemaot, plis yu mekem i kamtru. Yu mekem ol enemi blong mi oli harem nogud olsem mi.","“Plis yu lesin long krae blong mi, i no gat man i stap blong givhan long mi. Ol enemi blong mi oli harem we mi mi stap harem nogud, nao oli glad tumas from we yu yu sanem trabol ya // i kam long mi. Dei ya we yu bin talemaot, plis yu mekem i kamtru. Yu mekem ol enemi blong mi oli harem nogud olsem mi."],[1,22,"“Plis yu luk sin blong olgeta, mo yu panisim olgeta olsem we yu panisim mi from ol sin blong mi. Mi mi harem nogud tumas, nao mi krae we mi krae.”","“Plis yu luk sin blong olgeta, mo yu panisim olgeta olsem we yu panisim mi from ol sin blong mi. Mi mi harem nogud tumas, nao mi krae we mi krae.”"],[2,1,"Hae God i kros tumas, nao i kavremap taon ya Jerusalem* long tudak. Fastaem, hem i mekem taon ya i gudfala tumas, be long dei ya we hem i kros, hem nomo i spolemgud taon ya bakegen, mo hem i no moa tingbaot haos* blong hem.","Hae God i kros tumas, nao i kavremap taon ya Jerusalem* long tudak. Fastaem, hem i mekem taon ya i gudfala tumas, be long dei ya we hem i kros, hem nomo i spolemgud taon ya bakegen, mo hem i no moa tingbaot haos* blong hem."],[2,2,"Ol vilej ya long Juda,* Masta* blong yumi i no sore long olgeta nating, hem i spolem olgeta evriwan. Hem i brekemdaon ol taon we oli strong ples blong haed blong yumi, nao yumi wetem ol king blong yumi, hem i mekem yumi evriwan i sem tumas.","Ol vilej ya long Juda,* Masta* blong yumi i no sore long olgeta nating, hem i spolem olgeta evriwan. Hem i brekemdaon ol taon we oli strong ples blong haed blong yumi, nao yumi wetem ol king blong yumi, hem i mekem yumi evriwan i sem tumas."],[2,3,"Yumi ol laen* blong Isrel,* be hem i kros tumas long yumi, nao i flatemgud paoa blong yumi. Taem ol enemi oli kam, hem i no wantem givhan long yumi. Hem i faerap long yumi, i spolemgud yumi olsem faea we i kakae evri samting.","Yumi ol laen* blong Isrel,* be hem i kros tumas long yumi, nao i flatemgud paoa blong yumi. Taem ol enemi oli kam, hem i no wantem givhan long yumi. Hem i faerap long yumi, i spolemgud yumi olsem faea we i kakae evri samting."],[2,4,"Hem i makem yumi long ol ara blong hem mo i stap sutum yumi, olsem we hem i enemi blong yumi. Olgeta we oli stap mekem yumi harem gud, yumi glad, hem i kilim olgeta evriwan oli ded. Long ples ya long Jerusalem, kros blong hem i kasem yumi olsem we faea i kakae yumi.","Hem i makem yumi long ol ara blong hem mo i stap sutum yumi, olsem we hem i enemi blong yumi. Olgeta we oli stap mekem yumi harem gud, yumi glad, hem i kilim olgeta evriwan oli ded. Long ples ya long Jerusalem, kros blong hem i kasem yumi olsem we faea i kakae yumi."],[2,5,"Masta ya blong yumi hem i kam olsem wan enemi blong yumi we i spolemgud yumi. Hem i spolemgud ol taon blong yumi we oli strong ples blong haed, mo hem i spolemgud ol haos blong king blong yumi. Yumi ol laen blong Isrel we yumi kamaot biaen long olfala Juda, be hem i mekem we yumi harem nogud, yumi krae we yumi krae.","Masta ya blong yumi hem i kam olsem wan enemi blong yumi we i spolemgud yumi. Hem i spolemgud ol taon blong yumi we oli strong ples blong haed, mo hem i spolemgud ol haos blong king blong yumi. Yumi ol laen blong Isrel we yumi kamaot biaen long olfala Juda, be hem i mekem we yumi harem nogud, yumi krae we yumi krae."],[2,6,"Hem i smasemgud haos blong hem, we yumi stap wosipim hem long hem. Mo hem i mekem we yumi no moa tingbaot ol tabu dei mo ol Sabat* dei, we yumi stap holem long Saeon.* Ol king mo ol pris blong yumi, be hem i panisim olgeta evriwan tu, from we hem i kros tumas long olgeta.","Hem i smasemgud haos blong hem, we yumi stap wosipim hem long hem. Mo hem i mekem we yumi no moa tingbaot ol tabu dei mo ol Sabat* dei, we yumi stap holem long Saeon.* Ol king mo ol pris blong yumi, be hem i panisim olgeta evriwan tu, from we hem i kros tumas long olgeta."],[2,7,"Masta blong yumi, hem i tanem baksaed long olta blong hem, mo hem i gowe finis long haos ya we i tabu, // i blong hem. Hem i letem ol enemi oli kam pulumdaon ol stonwol blong haos ya. Ples ya we bifo yumi stap glad, yumi stap mekem wosip long hem, be ol enemi oli kam long hem, mo oli stap singsingaot bigwan, from we olgeta oli win.","Masta blong yumi, hem i tanem baksaed long olta blong hem, mo hem i gowe finis long haos ya we i tabu, // i blong hem. Hem i letem ol enemi oli kam pulumdaon ol stonwol blong haos ya. Ples ya we bifo yumi stap glad, yumi stap mekem wosip long hem, be ol enemi oli kam long hem, mo oli stap singsingaot bigwan, from we olgeta oli win."],[2,8,"Hae God i gat strong tingting se ol stonwol blong taon ya Jerusalem oli mas folfoldaon. Hem i makemgud ol stonwol ya blong soemaot we hem bambae i spolemgud olgeta. Naoia ol wajhaos* mo ol stonwol blong taon ya, olgeta evriwan oli foldaon finis.","Hae God i gat strong tingting se ol stonwol blong taon ya Jerusalem oli mas folfoldaon. Hem i makemgud ol stonwol ya blong soemaot we hem bambae i spolemgud olgeta. Naoia ol wajhaos* mo ol stonwol blong taon ya, olgeta evriwan oli foldaon finis."],[2,9,"Mo ol doa blong hem, ol enemi oli brebrekem ol lok blong olgeta, nao oli folfoldaon, graon i berem olgeta. Naoia king blong kantri ya wetem ol haeman blong hem oli go wok slef* long narafala kantri. Naoia, ol tija blong Loa* blong God oli no moa tijim ol man, mo Hae God i no moa soem ol vison* long ol profet blong ples ya.","Mo ol doa blong hem, ol enemi oli brebrekem ol lok blong olgeta, nao oli folfoldaon, graon i berem olgeta. Naoia king blong kantri ya wetem ol haeman blong hem oli go wok slef* long narafala kantri. Naoia, ol tija blong Loa* blong God oli no moa tijim ol man, mo Hae God i no moa soem ol vison* long ol profet blong ples ya."],[2,10,"Ol ololfala blong Jerusalem oli harem nogud, nao oli werem ol rabis klos, mo oli putum asis long hed blong olgeta oli go sidaon long graon, // oli stap kwaet nomo. Mo ol yang gel tu oli harem nogud oli bodaon we hed blong olgeta i go kasem graon.","Ol ololfala blong Jerusalem oli harem nogud, nao oli werem ol rabis klos, mo oli putum asis long hed blong olgeta oli go sidaon long graon, // oli stap kwaet nomo. Mo ol yang gel tu oli harem nogud oli bodaon we hed blong olgeta i go kasem graon."],[2,11,"Mi mi harem nogud tumas, nao mi krae we mi krae, gogo ae blong mi i soa from, mo tingting blong mi i kam nogud olgeta. Ol enemi oli kilim ol man ples blong mi oli ded, nao ol pikinini wetem ol bebi oli stap olbaot nomo long ol rod long taon ya we oli hafded. Mi mi sore tumas long olgeta, nao mi stap krae from olgeta gogo mi slak we mi slak olgeta.","Mi mi harem nogud tumas, nao mi krae we mi krae, gogo ae blong mi i soa from, mo tingting blong mi i kam nogud olgeta. Ol enemi oli kilim ol man ples blong mi oli ded, nao ol pikinini wetem ol bebi oli stap olbaot nomo long ol rod long taon ya we oli hafded. Mi mi sore tumas long olgeta, nao mi stap krae from olgeta gogo mi slak we mi slak olgeta."],[2,12,"Ol pikinini ya oli stap krae long ol mama blong olgeta, oli stap talem se, “!Mi mi hanggri! !Mi mi tosta!” Oli stap folfoldaon long rod olsem we oli karekil, nao oli stap long han blong mama blong olgeta oli stap harem nogud gogo oli ded.","Ol pikinini ya oli stap krae long ol mama blong olgeta, oli stap talem se, “!Mi mi hanggri! !Mi mi tosta!” Oli stap folfoldaon long rod olsem we oli karekil, nao oli stap long han blong mama blong olgeta oli stap harem nogud gogo oli ded."],[2,13,"!Jerusalem, mi mi laekem yu tumas! ?Be bambae mi save talem wanem samting long yu blong givhan long yu? ?Bambae mi save leftemap tingting blong yu olsem wanem? I no gat man samtaem we i harem nogud tumas olsem yu. Trabol blong yu i bigwan we i bigwan, i bitim mak. I no gat man i save mekem yu yu gud bakegen.","!Jerusalem, mi mi laekem yu tumas! ?Be bambae mi save talem wanem samting long yu blong givhan long yu? ?Bambae mi save leftemap tingting blong yu olsem wanem? I no gat man samtaem we i harem nogud tumas olsem yu. Trabol blong yu i bigwan we i bigwan, i bitim mak. I no gat man i save mekem yu yu gud bakegen."],[2,14,"Ol profet blong yu oli stap talemaot long yu ol samting we oli stap luk long ol rabis vison blong olgeta, be oli stap giaman nomo. Neva oli soemaot ol sin blong yu long yu, blong yu tanem tingting blong yu from. Nao from we oli stap mekem olsem yu yu stap ting se yu stret nomo.","Ol profet blong yu oli stap talemaot long yu ol samting we oli stap luk long ol rabis vison blong olgeta, be oli stap giaman nomo. Neva oli soemaot ol sin blong yu long yu, blong yu tanem tingting blong yu from. Nao from we oli stap mekem olsem yu yu stap ting se yu stret nomo."],[2,15,"!Jerusalem! Olgeta we oli stap pas klosap long yu, oli stap lukluk rabis long yu, mo oli laf nogud long yu. Oli stap seksekem hed blong olgeta, from we ol enemi blong yu oli spolemgud yu, mo oli stap jikim yu, oli talem se, “?Olsem wanem? !Hemia nao ples ya we olgeta man long wol oli stap talem se i beswan olgeta!”","!Jerusalem! Olgeta we oli stap pas klosap long yu, oli stap lukluk rabis long yu, mo oli laf nogud long yu. Oli stap seksekem hed blong olgeta, from we ol enemi blong yu oli spolemgud yu, mo oli stap jikim yu, oli talem se, “?Olsem wanem? !Hemia nao ples ya we olgeta man long wol oli stap talem se i beswan olgeta!”"],[2,16,"Ol enemi blong yu oli stap laf nogud long yu, oli no laekem yu nating. Oli stap jikim yu, oli talem se, “!Yumi spolem hem finis! !Hemia nao dei ya we yumi stap wet from!”","Ol enemi blong yu oli stap laf nogud long yu, oli no laekem yu nating. Oli stap jikim yu, oli talem se, “!Yumi spolem hem finis! !Hemia nao dei ya we yumi stap wet from!”"],[2,17,"Tok ya we Hae God i talem bifo olgeta se bambae i spolem yumi, be hem i mekem finis. Hem i spolem yumi, we i no gat sore long yumi nating, olsem we hem i talem. Hem i givhan long ol enemi blong yumi, nao oli kam winim yumi. Mo taem olgeta oli winim yumi, hem i mekem olgeta oli glad we oli glad.","Tok ya we Hae God i talem bifo olgeta se bambae i spolem yumi, be hem i mekem finis. Hem i spolem yumi, we i no gat sore long yumi nating, olsem we hem i talem. Hem i givhan long ol enemi blong yumi, nao oli kam winim yumi. Mo taem olgeta oli winim yumi, hem i mekem olgeta oli glad we oli glad."],[2,18,"Ol man Jerusalem oli krae i go long Masta ya blong yumi. !Ol bigfala stonwol blong Jerusalem! I gud yufala i krae we i krae long dei mo long naet, we wota blong ae blong yu bambae i ron olsem reva. I gud yufala i harem nogud, yufala i krae gogo yufala i kam slak.","Ol man Jerusalem oli krae i go long Masta ya blong yumi. !Ol bigfala stonwol blong Jerusalem! I gud yufala i krae we i krae long dei mo long naet, we wota blong ae blong yu bambae i ron olsem reva. I gud yufala i harem nogud, yufala i krae gogo yufala i kam slak."],[2,19,"Oltaem long naet, taem ol wajman oli stap jenis, yu mas girap, yu krae i go long Masta blong yumi. Yu mas talemaotgud olgeta tingting blong yu, mo yu mas askem long hem blong hem i sore long ol pikinini blong yu. Ol pikinini ya oli hanggri tumas, nao olbaot long ol kona blong rod, olgeta oli stap ded from.","Oltaem long naet, taem ol wajman oli stap jenis, yu mas girap, yu krae i go long Masta blong yumi. Yu mas talemaotgud olgeta tingting blong yu, mo yu mas askem long hem blong hem i sore long ol pikinini blong yu. Ol pikinini ya oli hanggri tumas, nao olbaot long ol kona blong rod, olgeta oli stap ded from."],[2,20,"Nao taon ya Jerusalem i tok, i talem se, “!Hae God! Yu luk ol man ya we yu mekem olgeta oli harem nogud. Nating we ol woman oli lavem tumas ol pikinini blong olgeta, be oli stap kakae dedbodi blong olgeta. Ol pris blong yu mo ol profet blong yu, be ol enemi oli stap kilim olgeta insaed long haos blong yu.","Nao taon ya Jerusalem i tok, i talem se, “!Hae God! Yu luk ol man ya we yu mekem olgeta oli harem nogud. Nating we ol woman oli lavem tumas ol pikinini blong olgeta, be oli stap kakae dedbodi blong olgeta. Ol pris blong yu mo ol profet blong yu, be ol enemi oli stap kilim olgeta insaed long haos blong yu."],[2,21,"“Nating we yangfala no olfala, be olgeta evriwan i sem mak nomo, olgeta evriwan oli ded finis, oli stap olbaot long rod. Ol yang man mo ol yang woman, yu letem ol enemi oli kilim olgeta oli ded long naef blong faet. Long dei ya we kros blong yu i kam strong, yu yu kilim olgeta we yu no gat sore long olgeta nating.","“Nating we yangfala no olfala, be olgeta evriwan i sem mak nomo, olgeta evriwan oli ded finis, oli stap olbaot long rod. Ol yang man mo ol yang woman, yu letem ol enemi oli kilim olgeta oli ded long naef blong faet. Long dei ya we kros blong yu i kam strong, yu yu kilim olgeta we yu no gat sore long olgeta nating."],[2,22,"“Olsem we yu stap singaot ol man oli kam long lafet, long sem fasin, yu singaot ol enemi oli aot long evri saed, nao oli kam mekem mi mi fraet. Long dei ya we kros blong yu i kam bigwan, i no gat wan man nating we i save ronwe. Ol pikinini ya blong mi we mi lavem olgeta tumas, mo mi stap lukaot long olgeta gogo oli kam bigwan, be ol enemi ya oli kam kilim olgeta evriwan oli ded.”","“Olsem we yu stap singaot ol man oli kam long lafet, long sem fasin, yu singaot ol enemi oli aot long evri saed, nao oli kam mekem mi mi fraet. Long dei ya we kros blong yu i kam bigwan, i no gat wan man nating we i save ronwe. Ol pikinini ya blong mi we mi lavem olgeta tumas, mo mi stap lukaot long olgeta gogo oli kam bigwan, be ol enemi ya oli kam kilim olgeta evriwan oli ded.”"],[3,1,"Mi mi savegud panis we Hae God i save givim, taem we kros blong hem i kam bigwan.","Mi mi savegud panis we Hae God i save givim, taem we kros blong hem i kam bigwan."],[3,2,"Hem i ronemaot mi mi gowe long delaet, mi go stap long ples we i tudak we i tudak olgeta,","Hem i ronemaot mi mi gowe long delaet, mi go stap long ples we i tudak we i tudak olgeta,"],[3,3,"mo oltaem hem i stap kilim mi, i stat long moning gogo kasem tudak, we i no gat sore long mi nating.","mo oltaem hem i stap kilim mi, i stat long moning gogo kasem tudak, we i no gat sore long mi nating."],[3,4,"Hem i brebrekem skin blong mi, i mekem mit blong mi i stap afsaed nomo, mo i brekem ol bun blong mi.","Hem i brebrekem skin blong mi, i mekem mit blong mi i stap afsaed nomo, mo i brekem ol bun blong mi."],[3,5,"Hem i mekem i strong tumas long mi, nao mi stap harem nogud tumas olsem we mi stap long kalabus we i nogud we i nogud.","Hem i mekem i strong tumas long mi, nao mi stap harem nogud tumas olsem we mi stap long kalabus we i nogud we i nogud."],[3,6,"Hem i mekem mi mi stap long tudak, olsem man we i ded bifo olgeta.","Hem i mekem mi mi stap long tudak, olsem man we i ded bifo olgeta."],[3,7,"Hem i blokemgud mi, mo i fasem mi long ol jen we i hevi, nao mi mi no save ronwe.","Hem i blokemgud mi, mo i fasem mi long ol jen we i hevi, nao mi mi no save ronwe."],[3,8,"Nating we mi stap prea long hem blong i givhan long mi, be hem i no wantem lesin long krae blong mi.","Nating we mi stap prea long hem blong i givhan long mi, be hem i no wantem lesin long krae blong mi."],[3,9,"Long olgeta ples we mi mi go, hem i stap blokem mi long ol stonwol, mo i mekem rod blong mi i paspas.","Long olgeta ples we mi mi go, hem i stap blokem mi long ol stonwol, mo i mekem rod blong mi i paspas."],[3,10,"Hem i stap wet long mi, olsem anamol ya bea we i stap wet blong kasem kakae blong hem, mo i olsem laeon we i stap haed blong holem kakae blong hem.","Hem i stap wet long mi, olsem anamol ya bea we i stap wet blong kasem kakae blong hem, mo i olsem laeon we i stap haed blong holem kakae blong hem."],[3,11,"Hem i ronem mi mi gowe long rod, nao i holem mi, i terem mi long ol smosmol pis, mo i livim mi mi stap mi wan.","Hem i ronem mi mi gowe long rod, nao i holem mi, i terem mi long ol smosmol pis, mo i livim mi mi stap mi wan."],[3,12,"Hem i pulum bonara blong hem, nao i makem mi long hem, olsem we mi mi wan mak we hem i stap sutum long ol ara blong hem.","Hem i pulum bonara blong hem, nao i makem mi long hem, olsem we mi mi wan mak we hem i stap sutum long ol ara blong hem."],[3,13,"Hem i sutum mi long ol ara blong hem, mo oli go insaed olgeta long bodi blong mi.","Hem i sutum mi long ol ara blong hem, mo oli go insaed olgeta long bodi blong mi."],[3,14,"Mi mi kam wan samting blong laf nomo, ol man oli stap laf nogud long mi, i stat long moning gogo kasem tudak.","Mi mi kam wan samting blong laf nomo, ol man oli stap laf nogud long mi, i stat long moning gogo kasem tudak."],[3,15,"Hem i mekem mi mi harem nogud nomo, nao samting ya i kam olsem kakae blong mi mo wota blong mi.","Hem i mekem mi mi harem nogud nomo, nao samting ya i kam olsem kakae blong mi mo wota blong mi."],[3,16,"Hem i holem mi, i pusum mi mi godaon, mo i ravem fes blong mi long graon, nao ol tut blong mi oli brobrok long ston.","Hem i holem mi, i pusum mi mi godaon, mo i ravem fes blong mi long graon, nao ol tut blong mi oli brobrok long ston."],[3,17,"Fastaem mi mi stap gud, mi no sik, mo mi glad oltaem nomo, be Hae God i tekemaot ol samting ya long mi, nao mi fogetemgud olgeta.","Fastaem mi mi stap gud, mi no sik, mo mi glad oltaem nomo, be Hae God i tekemaot ol samting ya long mi, nao mi fogetemgud olgeta."],[3,18,"Laef blong mi i kam sotwan we i sotwan. Mi no moa save luk long Hae God blong i givhan long mi.","Laef blong mi i kam sotwan we i sotwan. Mi no moa save luk long Hae God blong i givhan long mi."],[3,19,"Taem mi tingting long ol trabol ya blong mi we mi stap harem nogud, mo we mi no gat hom blong mi, mi harem olsem we mi dring posen.","Taem mi tingting long ol trabol ya blong mi we mi stap harem nogud, mo we mi no gat hom blong mi, mi harem olsem we mi dring posen."],[3,20,"Oltaem mi stap tingbaot samting ya, nao tingting blong mi i foldaon.","Oltaem mi stap tingbaot samting ya, nao tingting blong mi i foldaon."],[3,21,"Be mi tingbaot wan samting, nao i leftemap tingting blong mi bakegen.","Be mi tingbaot wan samting, nao i leftemap tingting blong mi bakegen."],[3,22,"Mi mi tingbaot fasin blong Hae God, we oltaem, hem i gat sore long man, mo i lavem man tumas. Tufala fasin ya blong hem bambae i no save finis samtaem,","Mi mi tingbaot fasin blong Hae God, we oltaem, hem i gat sore long man, mo i lavem man tumas. Tufala fasin ya blong hem bambae i no save finis samtaem,"],[3,23,"tufala i niuwan oltaem nomo, olsem we evri moning, niufala dei i kamtru. Hae God i stap sem mak nomo olwe, hem i no save jenis.","tufala i niuwan oltaem nomo, olsem we evri moning, niufala dei i kamtru. Hae God i stap sem mak nomo olwe, hem i no save jenis."],[3,24,"Mo hem nomo i stap givim laef long mi, nao from samting ya, mi mi putum tingting blong mi i stap strong long hem bakegen.","Mo hem nomo i stap givim laef long mi, nao from samting ya, mi mi putum tingting blong mi i stap strong long hem bakegen."],[3,25,"Hae God i gud tumas long olgeta we oli stap trastem hem, mo we oli wantem tumas blong savegud hem.","Hae God i gud tumas long olgeta we oli stap trastem hem, mo we oli wantem tumas blong savegud hem."],[3,26,"Taswe yumi mas gat longfala tingting, yumi mas stap kwaet, mo yumi wet long hem blong hem i sevem yumi.","Taswe yumi mas gat longfala tingting, yumi mas stap kwaet, mo yumi wet long hem blong hem i sevem yumi."],[3,27,"Mo i stat taem we yumi smol, yumi mas lanem fasin ya blong mekem tingting blong yumi i longfala.","Mo i stat taem we yumi smol, yumi mas lanem fasin ya blong mekem tingting blong yumi i longfala."],[3,28,"Sipos man i harem nogud, i gud hem i stap hem wan, i stap kwaet, mo i mekem tingting blong hem i longfala.","Sipos man i harem nogud, i gud hem i stap hem wan, i stap kwaet, mo i mekem tingting blong hem i longfala."],[3,29,"I gud hem i mekem tingting blong hem i stap daon, from we maet hem i save win yet.","I gud hem i mekem tingting blong hem i stap daon, from we maet hem i save win yet."],[3,30,"Sipos ol man oli kilim hem, mo oli tok nogud long hem, be i gud hem i glad nomo long ol samting ya.","Sipos ol man oli kilim hem, mo oli tok nogud long hem, be i gud hem i glad nomo long ol samting ya."],[3,31,"Masta* blong yumi, hem i gat sore long yumi, mo hem i no save tanem baksaed olwe long yumi.","Masta* blong yumi, hem i gat sore long yumi, mo hem i no save tanem baksaed olwe long yumi."],[3,32,"Hem i save mekem yumi harem nogud, be hem i gat sore long yumi, from we hem i lavem yumi, mo fasin ya blong hem i no save jenis.","Hem i save mekem yumi harem nogud, be hem i gat sore long yumi, from we hem i lavem yumi, mo fasin ya blong hem i no save jenis."],[3,33,"Hem i no glad nating blong mekem we yumi stap long trabol, yumi stap harem nogud.","Hem i no glad nating blong mekem we yumi stap long trabol, yumi stap harem nogud."],[3,34,"God i hae we i hae, mo taem yumi stap long kalabus, mo tingting blong yumi i foldaon olgeta, be hem i save samting ya.","God i hae we i hae, mo taem yumi stap long kalabus, mo tingting blong yumi i foldaon olgeta, be hem i save samting ya."],[3,35,"Mo taem ol man oli tekemaot ol raet blong yumi we hem nomo i givim long yumi, be hem i save.","Mo taem ol man oli tekemaot ol raet blong yumi we hem nomo i givim long yumi, be hem i save."],[3,36,"Mo taem jaj i no folem stret fasin blong jajem yumi long kot, be hem i save samting ya tu. Mo olgeta samting ya, hem i no glad nating long olgeta.","Mo taem jaj i no folem stret fasin blong jajem yumi long kot, be hem i save samting ya tu. Mo olgeta samting ya, hem i no glad nating long olgeta."],[3,37,"Oltaem Masta ya blong yumi i stap mekem we ol samting we hem nomo i wantem oli kamtru.","Oltaem Masta ya blong yumi i stap mekem we ol samting we hem nomo i wantem oli kamtru."],[3,38,"Ol gudfala samting wetem ol rabis fasin, oli stap kamaot long tok blong hem nomo.","Ol gudfala samting wetem ol rabis fasin, oli stap kamaot long tok blong hem nomo."],[3,39,"Sipos yumi kasem panis from ol sin blong yumi, be i nogud yumi stap toktok tumas from.","Sipos yumi kasem panis from ol sin blong yumi, be i nogud yumi stap toktok tumas from."],[3,40,"I gud yumi lukluk gud long ol fasin blong yumi, nao yumi kambak long Hae God.","I gud yumi lukluk gud long ol fasin blong yumi, nao yumi kambak long Hae God."],[3,41,"Hem i stap long heven, mo i gud yumi leftemap han blong yumi, yumi prea long hem. I gud yumi talemaot olgeta tingting blong yumi long hem se,","Hem i stap long heven, mo i gud yumi leftemap han blong yumi, yumi prea long hem. I gud yumi talemaot olgeta tingting blong yumi long hem se,"],[3,42,"“Hae God, mifala i mekem sin, mifala i girap mifala i agens long yu, mo yu yu no fogivim mifala.","“Hae God, mifala i mekem sin, mifala i girap mifala i agens long yu, mo yu yu no fogivim mifala."],[3,43,"“Yu yu kros tumas, nao mifala i no moa luk fasin ya blong yu we yu yu gat sore long man. Yu girap yu ronem mifala, mo yu kilim mifala we yu no gat sore long mifala nating.","“Yu yu kros tumas, nao mifala i no moa luk fasin ya blong yu we yu yu gat sore long man. Yu girap yu ronem mifala, mo yu kilim mifala we yu no gat sore long mifala nating."],[3,44,"Kros ya blong yu i strong tumas, i olsem klaod we i tik tumas, nao ol prea blong mifala i no save gotru long hem.","Kros ya blong yu i strong tumas, i olsem klaod we i tik tumas, nao ol prea blong mifala i no save gotru long hem."],[3,45,"Yu yu mekem mifala i kam olsem hif blong doti long fes blong olgeta man long wol.","Yu yu mekem mifala i kam olsem hif blong doti long fes blong olgeta man long wol."],[3,46,"“Ol enemi blong mifala oli stap jikim mifala, mo oli stap tok nogud tumas long mifala.","“Ol enemi blong mifala oli stap jikim mifala, mo oli stap tok nogud tumas long mifala."],[3,47,"Mifala i kasem plante trabol we klosap mifala i ded from. Laef blong mifala i kam nogud olgeta, mo oltaem mifala i stap fraet tumas.","Mifala i kasem plante trabol we klosap mifala i ded from. Laef blong mifala i kam nogud olgeta, mo oltaem mifala i stap fraet tumas."],[3,48,"“Mi mi stap krae from ol man ples blong mi we yu yu kilim olgeta oli ded, mo wota blong ae blong mi i stap ron olsem reva.","“Mi mi stap krae from ol man ples blong mi we yu yu kilim olgeta oli ded, mo wota blong ae blong mi i stap ron olsem reva."],[3,49,"“Wota blong ae blong mi bambae i ron bigwan, olsem wota we i stap ron oltaem, i no save spel.","“Wota blong ae blong mi bambae i ron bigwan, olsem wota we i stap ron oltaem, i no save spel."],[3,50,"Hae God, yu yu stap long heven, mo oltaem bambae mi stap krae i go long yu gogo kasem we yu yu luk i kam long mifala.","Hae God, yu yu stap long heven, mo oltaem bambae mi stap krae i go long yu gogo kasem we yu yu luk i kam long mifala."],[3,51,"Taem mi luk ol samting ya we i kasem ol woman blong taon ya, mi mi harem nogud tumas.","Taem mi luk ol samting ya we i kasem ol woman blong taon ya, mi mi harem nogud tumas."],[3,52,"“Ol enemi oli kam holem mi olsem we oli kasem pijin long trap, be blong nating nomo.","“Ol enemi oli kam holem mi olsem we oli kasem pijin long trap, be blong nating nomo."],[3,53,"Oli sakem mi long wan hol, we mi mi laef nomo, nao oli satem maot blong hol ya long ston.","Oli sakem mi long wan hol, we mi mi laef nomo, nao oli satem maot blong hol ya long ston."],[3,54,"Mo wota i stat kavremap mi, nao mi ting se bambae mi mi ded.","Mo wota i stat kavremap mi, nao mi ting se bambae mi mi ded."],[3,55,"“Hae God, hol ya i godaon we i godaon olgeta, mo taem mi stap long hem, mi krae i kam long yu.","“Hae God, hol ya i godaon we i godaon olgeta, mo taem mi stap long hem, mi krae i kam long yu."],[3,56,"Mi prea long yu blong yu lesin long krae blong mi, nao yu yu harem mi,","Mi prea long yu blong yu lesin long krae blong mi, nao yu yu harem mi,"],[3,57,"yu kam klosap long mi, yu talem se, ‘Yu no fraet.’","yu kam klosap long mi, yu talem se, ‘Yu no fraet.’"],[3,58,"“Masta blong mi, yu yu kam, nao yu sevem laef blong mi.","“Masta blong mi, yu yu kam, nao yu sevem laef blong mi."],[3,59,"Yu yu savegud ol fasin nogud ya we ol man oli stap mekem agens long mi. Be naoia, plis yu stretem trabol ya yu soemaot we mi mi stret.","Yu yu savegud ol fasin nogud ya we ol man oli stap mekem agens long mi. Be naoia, plis yu stretem trabol ya yu soemaot we mi mi stret."],[3,60,"Yu yu save we ol enemi blong mi oli no laekem mi nating, oli agens long mi, mo yu savegud ol plan blong olgeta we oli stap mekem agens long mi.","Yu yu save we ol enemi blong mi oli no laekem mi nating, oli agens long mi, mo yu savegud ol plan blong olgeta we oli stap mekem agens long mi."],[3,61,"“Hae God, yu yu harem we oli tok nogud long mi. Yu savegud olgeta plan ya we oli mekem agens long mi.","“Hae God, yu yu harem we oli tok nogud long mi. Yu savegud olgeta plan ya we oli mekem agens long mi."],[3,62,"Oli stap tokbaot mi, mo oli stap mekem ol plan ya blong olgeta, i stat long moning gogo kasem tudak.","Oli stap tokbaot mi, mo oli stap mekem ol plan ya blong olgeta, i stat long moning gogo kasem tudak."],[3,63,"Oltaem nomo, oli stap laf nogud long mi.","Oltaem nomo, oli stap laf nogud long mi."],[3,64,"“Hae God, plis yu panisim olgeta from ol samting ya we oli mekem.","“Hae God, plis yu panisim olgeta from ol samting ya we oli mekem."],[3,65,"Plis yu singaot* trabol i kam long olgeta, mo yu mekem tingting blong olgeta i foldaon.","Plis yu singaot* trabol i kam long olgeta, mo yu mekem tingting blong olgeta i foldaon."],[3,66,"I gud yu kros long olgeta, yu ronemaot olgeta. Yu flatemgud olgeta blong oli finis olgeta long wol ya.”","I gud yu kros long olgeta, yu ronemaot olgeta. Yu flatemgud olgeta blong oli finis olgeta long wol ya.”"],[4,1,"Ol gol blong yumi we fastaem i saen we i saen naoia i no moa saen, i kam doti we i doti. Mo ol ston blong haos* blong Hae God, naoia oli stap wanwan olbaot long ol rod.","Ol gol blong yumi we fastaem i saen we i saen naoia i no moa saen, i kam doti we i doti. Mo ol ston blong haos* blong Hae God, naoia oli stap wanwan olbaot long ol rod."],[4,2,"Ol yang man blong Saeon,* fastaem oli gudfala tumas olsem gol we i beswan, be naoia ol man oli stap spolemgud olgeta, nao oli kam olsem graonpot we i blong nating nomo.","Ol yang man blong Saeon,* fastaem oli gudfala tumas olsem gol we i beswan, be naoia ol man oli stap spolemgud olgeta, nao oli kam olsem graonpot we i blong nating nomo."],[4,3,"Nating we wael dog, be i stap fidimgud ol pikinini blong hem. Be ol man ya blong mi naoia oli kam olsem pijin ya ostrij* we i stap mekem i strong tumas long ol pikinini blong hem, i no stap lukaot gud long olgeta.","Nating we wael dog, be i stap fidimgud ol pikinini blong hem. Be ol man ya blong mi naoia oli kam olsem pijin ya ostrij* we i stap mekem i strong tumas long ol pikinini blong hem, i no stap lukaot gud long olgeta."],[4,4,"Ol man ya oli stap letem ol smosmol pikinini blong olgeta oli stap hanggri mo oli tosta gogo oli ded from. Taem ol pikinini oli stap askem kakae, be i no gat man i save givim kakae long olgeta.","Ol man ya oli stap letem ol smosmol pikinini blong olgeta oli stap hanggri mo oli tosta gogo oli ded from. Taem ol pikinini oli stap askem kakae, be i no gat man i save givim kakae long olgeta."],[4,5,"Ol man we bifo oli stap kakae ol nambawan kakae, naoia oli stap ded nomo long rod from hanggri. Olgeta we oli gruap long haos blong ol haeman, naoia oli stap skrasem ol doti blong faenem kakae blong olgeta.","Ol man we bifo oli stap kakae ol nambawan kakae, naoia oli stap ded nomo long rod from hanggri. Olgeta we oli gruap long haos blong ol haeman, naoia oli stap skrasem ol doti blong faenem kakae blong olgeta."],[4,6,"God i panisimgud ol man blong mi, i winim we hem i panisim ol man Sodom bifo, ples ya we hem i flatemgud wantaem nomo long paoa blong hem.","God i panisimgud ol man blong mi, i winim we hem i panisim ol man Sodom bifo, ples ya we hem i flatemgud wantaem nomo long paoa blong hem."],[4,7,"Ol haeman blong yumi, bifo oli klin gud, bodi blong olgeta i saen olsem sno. Oli strong, mo oli smat, mo i no gat sik i kasem olgeta.","Ol haeman blong yumi, bifo oli klin gud, bodi blong olgeta i saen olsem sno. Oli strong, mo oli smat, mo i no gat sik i kasem olgeta."],[4,8,"Be naoia oli stap olbaot long rod, we man i no moa save luksave olgeta. Fes blong olgeta i kam narafala, mo skin blong olgeta i fas gud long bun blong olgeta, mo i kam drae olsem wud.","Be naoia oli stap olbaot long rod, we man i no moa save luksave olgeta. Fes blong olgeta i kam narafala, mo skin blong olgeta i fas gud long bun blong olgeta, mo i kam drae olsem wud."],[4,9,"Olgeta we oli no gat kakae nao oli hanggri gogo oli ded, oli harem nogud moa i winim olgeta we oli ded wantaem nomo long naef blong faet.","Olgeta we oli no gat kakae nao oli hanggri gogo oli ded, oli harem nogud moa i winim olgeta we oli ded wantaem nomo long naef blong faet."],[4,10,"Trabol ya we i kasem ol man blong mi, i mekem olgeta oli mekem samting we i nogud olgeta. Ol mama we fasin blong olgeta i gud tumas, be oli girap oli kilim ol pikinini blong olgeta, oli kukum olgeta blong oli kakae.","Trabol ya we i kasem ol man blong mi, i mekem olgeta oli mekem samting we i nogud olgeta. Ol mama we fasin blong olgeta i gud tumas, be oli girap oli kilim ol pikinini blong olgeta, oli kukum olgeta blong oli kakae."],[4,11,"Hae God i kros tumas nao i no moa save holem kros blong hem. Hem i spolemgud Saeon long faea we i bonemgud ples ya gogo graon nomo i stap.","Hae God i kros tumas nao i no moa save holem kros blong hem. Hem i spolemgud Saeon long faea we i bonemgud ples ya gogo graon nomo i stap."],[4,12,"Bifo i no gat man i bilif se enemi i save go insaed long ol doa* blong stonwol blong Jerusalem,* nating we ol king blong ol narafala kantri, be oli luk se oli no naf blong go insaed.","Bifo i no gat man i bilif se enemi i save go insaed long ol doa* blong stonwol blong Jerusalem,* nating we ol king blong ol narafala kantri, be oli luk se oli no naf blong go insaed."],[4,13,"Be ol enemi oli go insaed, from we ol profet blong ples ya oli mekem sin, mo ol pris tu oli mekem i no stret. Olgeta ya oli stap kilim ol stret man oli ded.","Be ol enemi oli go insaed, from we ol profet blong ples ya oli mekem sin, mo ol pris tu oli mekem i no stret. Olgeta ya oli stap kilim ol stret man oli ded."],[4,14,"Ol lida blong ples ya oli stap go olbaot long ol rod olsem ol blaen man. Blad i fulap long han blong olgeta, nao man i no save tajem olgeta, mo nating we klos blong olgeta nomo, be man i no save tajem.","Ol lida blong ples ya oli stap go olbaot long ol rod olsem ol blaen man. Blad i fulap long han blong olgeta, nao man i no save tajem olgeta, mo nating we klos blong olgeta nomo, be man i no save tajem."],[4,15,"Ol man oli stap singaot long olgeta se, “!Ei! !Yufala i gowe! !Yufala i doti long fes blong God ya! !Yufala i no tajem mifala!” Nao olgeta oli stap go olbaot long evri ples, oli aot long wan ples oli go stap long narafala ples, be i no gat man i singaot olgeta blong oli kam stap wetem hem.","Ol man oli stap singaot long olgeta se, “!Ei! !Yufala i gowe! !Yufala i doti long fes blong God ya! !Yufala i no tajem mifala!” Nao olgeta oli stap go olbaot long evri ples, oli aot long wan ples oli go stap long narafala ples, be i no gat man i singaot olgeta blong oli kam stap wetem hem."],[4,16,"Hae God i no moa tingbaot olgeta, hem nao i mekem olgeta oli go wanwan. Hem i no moa ona long ol pris mo ol lida blong yumi.","Hae God i no moa tingbaot olgeta, hem nao i mekem olgeta oli go wanwan. Hem i no moa ona long ol pris mo ol lida blong yumi."],[4,17,"Bifo yumi stap lukluk blong man i kam givhan long yumi, be no, yumi stap lukluk blong nating nomo. Yumi stap wet long kantri ya we i fren blong yumi blong i kam givhan long yumi, be hem i no save mekem.","Bifo yumi stap lukluk blong man i kam givhan long yumi, be no, yumi stap lukluk blong nating nomo. Yumi stap wet long kantri ya we i fren blong yumi blong i kam givhan long yumi, be hem i no save mekem."],[4,18,"Ol enemi ya blong yumi oli stap wajemgud yumi blong kilim yumi. Nao from samting ya, yumi no moa save wokbaot long taon blong yumi. Taem blong yumi i finis nao.","Ol enemi ya blong yumi oli stap wajemgud yumi blong kilim yumi. Nao from samting ya, yumi no moa save wokbaot long taon blong yumi. Taem blong yumi i finis nao."],[4,19,"Ol enemi ya oli save ron kwik tumas, olsem we pijin ya igel* i flae i kamdaon kwiktaem nomo. Oli ronem yumi antap long ol hil, mo oli haed long draeples blong kasem yumi, nao oli holem yumi.","Ol enemi ya oli save ron kwik tumas, olsem we pijin ya igel* i flae i kamdaon kwiktaem nomo. Oli ronem yumi antap long ol hil, mo oli haed long draeples blong kasem yumi, nao oli holem yumi."],[4,20,"King ya we Hae God i bin putumap, we yumi trastem hem blong hem i holem laef blong yumi, i blokem yumi blong ol enemi oli no kam insaed // long ples blong yumi, be ol enemi ya oli kam tekemaot hem, oli karem hem i go.","King ya we Hae God i bin putumap, we yumi trastem hem blong hem i holem laef blong yumi, i blokem yumi blong ol enemi oli no kam insaed // long ples blong yumi, be ol enemi ya oli kam tekemaot hem, oli karem hem i go."],[4,21,"Ol man Edom mo ol man Uj, yufala i gohed, yufala i laf fastaem. I gud yufala i glad olsem we yufala i wantem. Bambae trabol i kasem yufala yet ya. Yufala tu bambae i wokbaot olsem we yufala i drong we yufala i stap neked nomo, yufala i sem.","Ol man Edom mo ol man Uj, yufala i gohed, yufala i laf fastaem. I gud yufala i glad olsem we yufala i wantem. Bambae trabol i kasem yufala yet ya. Yufala tu bambae i wokbaot olsem we yufala i drong we yufala i stap neked nomo, yufala i sem."],[4,22,"Ol man Jerusalem, panis blong yumi from ol sin blong yumi i finis nao. Hae God bambae i no save letem blong yumi stap wok slef* longtaem. Be yufala ol man Edom, Hae God bambae i panisim yufala tu, bambae i mekem ol sin blong yufala i stap long klia ples nomo.","Ol man Jerusalem, panis blong yumi from ol sin blong yumi i finis nao. Hae God bambae i no save letem blong yumi stap wok slef* longtaem. Be yufala ol man Edom, Hae God bambae i panisim yufala tu, bambae i mekem ol sin blong yufala i stap long klia ples nomo."],[5,1,"Hae God, plis yu tingbaot trabol ya we i kasem mifala. Yu luk, mifala i sem tumas.","Hae God, plis yu tingbaot trabol ya we i kasem mifala. Yu luk, mifala i sem tumas."],[5,2,"Ol graon blong mifala, naoia oli stap long han blong ol strenja. Ol man blong narafala ples, naoia oli stap long ol hom blong mifala.","Ol graon blong mifala, naoia oli stap long han blong ol strenja. Ol man blong narafala ples, naoia oli stap long ol hom blong mifala."],[5,3,"Ol enemi oli kilim ol papa blong mifala, nao ol mama blong mifala oli kam wido.","Ol enemi oli kilim ol papa blong mifala, nao ol mama blong mifala oli kam wido."],[5,4,"Naoia, nating we wota we i blong mifala nomo, mo faeawud we i blong mifala, be mifala i mas pem.","Naoia, nating we wota we i blong mifala nomo, mo faeawud we i blong mifala, be mifala i mas pem."],[5,5,"Ol enemi oli stap fosem mifala tumas blong mekem wok blong olgeta. Nating we mifala i taed tumas be oli no save givim spel long mifala.","Ol enemi oli stap fosem mifala tumas blong mekem wok blong olgeta. Nating we mifala i taed tumas be oli no save givim spel long mifala."],[5,6,"Mifala i bin go long Ijip mo Asiria, mifala i stap askem kakae long olgeta, blong mifala i save stap laef.","Mifala i bin go long Ijip mo Asiria, mifala i stap askem kakae long olgeta, blong mifala i save stap laef."],[5,7,"Ol bubu blong mifala bifo oli mekem sin, be olgeta evriwan oli ded finis, mo naoia mifala i stap harem nogud from sin ya blong olgeta.","Ol bubu blong mifala bifo oli mekem sin, be olgeta evriwan oli ded finis, mo naoia mifala i stap harem nogud from sin ya blong olgeta."],[5,8,"Ol man ya we oli stap rulum mifala, oli no gat nem, oli olsem slef* nomo, mo i no gat man i save tekemaot mifala long han blong olgeta.","Ol man ya we oli stap rulum mifala, oli no gat nem, oli olsem slef* nomo, mo i no gat man i save tekemaot mifala long han blong olgeta."],[5,9,"Ol man blong kilim man oli stap wokbaot olbaot long bus, mo taem mifala i go lukaot kakae blong mifala, be mifala i mas rere blong lusum laef blong mifala.","Ol man blong kilim man oli stap wokbaot olbaot long bus, mo taem mifala i go lukaot kakae blong mifala, be mifala i mas rere blong lusum laef blong mifala."],[5,10,"Mifala i hanggri tumas nao mifala i fiva from. Mifala i fiva gogo bodi blong mifala i hot we i hot olsem faea.","Mifala i hanggri tumas nao mifala i fiva from. Mifala i fiva gogo bodi blong mifala i hot we i hot olsem faea."],[5,11,"Long tabu hil ya Saeon,* be ol enemi oli fosem ol woman blong mifala blong slip wetem olgeta. Mo long evri vilej long Juda,* oli fosem ol dota blong mifala tu blong slip wetem olgeta.","Long tabu hil ya Saeon,* be ol enemi oli fosem ol woman blong mifala blong slip wetem olgeta. Mo long evri vilej long Juda,* oli fosem ol dota blong mifala tu blong slip wetem olgeta."],[5,12,"Oli tekem ol lida blong mifala, oli hangem olgeta, oli no ona nating long ol olfala blong mifala.","Oli tekem ol lida blong mifala, oli hangem olgeta, oli no ona nating long ol olfala blong mifala."],[5,13,"Oli fosem ol yang man blong mifala, blong granem wit* i kam flaoa long ol bigfala ston we i hevi tumas. Ol pikinini boe blong mifala oli stap karem ol wud we i hevi tumas.","Oli fosem ol yang man blong mifala, blong granem wit* i kam flaoa long ol bigfala ston we i hevi tumas. Ol pikinini boe blong mifala oli stap karem ol wud we i hevi tumas."],[5,14,"Ol olfala blong mifala oli no moa stap sidaon long doa* blong stonwol blong taon ya, mo ol yangfala blong mifala oli no moa mekem stringban.","Ol olfala blong mifala oli no moa stap sidaon long doa* blong stonwol blong taon ya, mo ol yangfala blong mifala oli no moa mekem stringban."],[5,15,"Naoia mifala i no moa save glad, mifala i no moa stap danis, mifala i stap krae nomo.","Naoia mifala i no moa save glad, mifala i no moa stap danis, mifala i stap krae nomo."],[5,16,"Ol samting we bifo mifala i stap praod long hem, naoia i no moa gat wan i stap. Mifala i mekem sin, nao trabol i kasem mifala.","Ol samting we bifo mifala i stap praod long hem, naoia i no moa gat wan i stap. Mifala i mekem sin, nao trabol i kasem mifala."],[5,17,"Mifala i stap harem nogud tumas, nao mifala i stap krae gogo mifala i no moa save lukluk,","Mifala i stap harem nogud tumas, nao mifala i stap krae gogo mifala i no moa save lukluk,"],[5,18,"from we hil ya Saeon i stap we i no gat man nating long hem, mo i kam ples blong ol wael dog nomo.","from we hil ya Saeon i stap we i no gat man nating long hem, mo i kam ples blong ol wael dog nomo."],[5,19,"Be yu, Hae God, yu yu King we yu stap oltaem nomo. Yu bambae yu stap rul gogo i no save finis.","Be yu, Hae God, yu yu King we yu stap oltaem nomo. Yu bambae yu stap rul gogo i no save finis."],[5,20,"?From wanem yu lego mifala longtaem tumas olsem? ?Olsem wanem? ?Yu no save tingbaot mifala bakegen?","?From wanem yu lego mifala longtaem tumas olsem? ?Olsem wanem? ?Yu no save tingbaot mifala bakegen?"],[5,21,"Plis yu tekem mifala i kambak long yu. Plis yu leftemap mifala bakegen, blong mifala i save harem gud bakegen olsem bifo.","Plis yu tekem mifala i kambak long yu. Plis yu leftemap mifala bakegen, blong mifala i save harem gud bakegen olsem bifo."],[5,22,"?No olsem wanem? ?Yu lego mifala olgeta? ?Kros blong yu bambae i no save finis?","?No olsem wanem? ?Yu lego mifala olgeta? ?Kros blong yu bambae i no save finis?"]]}};